window.POEM_DB=window.POEM_DB||{};POEM_DB["song_035"]={"n":"刘攽","dyn":"宋","poems":[{"t":"送邵兴宗之丹阳","f":"五言古诗","c":["赤日裂石土，万家如烘炉。","君行何事役，似为贫所驱。","埃尘稍去眼，云景日萧疏。","扁舟乘长风，倏忽遍三吴。","六年羁旅倦，一旦谁扫除。","慎勿忘回首，浩荡江山娱。"]},{"t":"雨后池上","f":"七言绝句","c":["一雨池塘水面平，澹磨明镜照檐楹。","东风忽起垂杨舞，更作荷心万点声。"]},{"t":"新晴 其一","f":"七言绝句","c":["青苔满地初晴后，绿树无人昼梦馀。","唯有南风旧相熟，径开门户又翻书。"]},{"t":"江南田家","f":"五言古诗","c":["种田江南岸，六月才树秧。","借问一何晏，再为霖雨伤。","官家不爱农，农贫弥自忙。","尽力泥水间，肤甲皆疥疮。","未知秋成期，尚足输太仓。","不如逐商贾，游閒事车航。","朝廷虽多贤，正许赀为郎。"]},{"t":"城南行","f":"七言律诗","c":["八月江湖秋水高，大堤夜坼声嘈嘈。","前村农家失几户，近郭扁舟屯百艘。","蛟龙蜿蜒水禽白，渡头老翁须雇直。","城南百姓多为鱼，买鱼欲烹辄悽恻。"]},{"t":"送王仲素寺丞归灊山","f":"七言古诗","c":["灊山隐居七十四，绀瞳绿发初谢事。","腹中灵液变丹砂，江山幽居连福地。","彭城为我驻三日，明月满船同一醉。","丹书细字口传诀，顾我沉迷真弃耳。","来年四十发苍苍，始欲求方救憔悴。","他年若访灊山居，慎勿逃人改名字。"]},{"t":"大安病酒留半日王守复来招不往送酒解酲因小饮江月馆","f":"七言绝句","c":["江驿春酲半日留，更烦送酒为扶头。","柳花漠漠嘉陵岸，别是天涯一段愁。"]},{"t":"考试毕登铨楼","f":"七言绝句","c":["春云浓淡日微光，双阙重门耸建章。","不上楼来知几日，满城无算柳梢黄。"]},{"t":"舟中夜饮忆和弟联句","f":"五言古诗","c":["人生如浮云，聚散苦不定。","向来诗酒欢，虽唱谁与应。","蟋蟀鸣在户，玉衡逼冬孟。","悠悠千里思，寂寂中夜静。","岂曰无他人，不如我同姓。","吁嗟系名利，有若置机阱。","窘然尘埃中，耻无六翮劲。","访戴舟已惭，攀嵇驾难命。","临觞置不饮，引领起独咏。","莽莽天地昏，谁知我心怲。"]},{"t":"坐啸亭纳凉","f":"五言古诗","c":["长啸振林木，半空鸾鹤声。","清风蘋末来，孤月海上生。","坐久物色改，如有神仙迎。"]},{"t":"颍州和永叔","f":"五言古诗","c":["羁鸟能择木，游鱼知赴渊。","飞沈岂异志，行止私自怜。","玩世本无术，辟人庸得贤。","卜居幸乐国，负郭依良田。","心与地俱远，我徒共熙然。","生涯亦何有，聊以忘吾年。"]},{"t":"过王氏弟兄","f":"词","c":["出城问穷僻，负郭正潇洒。","主人著书长闭关，嘉树当门宜系马。","下马上堂还读书，新诗古琴双起予。","昏鸦栖鸡欲敛翼，兴尽将去犹须臾。","徒见城中轩冕客，不如吾人一逢掖。","安得茅茨同里居，子在东阡我南陌。"]},{"t":"重到谢氏园亭寄裴博士俊叔王主簿宗杰时裴往淮南王出京师","f":"五言律诗","c":["徘徊远林下，幽草为谁芳。","前日同游客，今朝俱异乡。","东风虽淡荡，陈迹似凄凉。","何用江千里，春心故易伤。"]},{"t":"五月望日赴紫宸谒待旦假寐","f":"七言律诗","c":["半夜北风凛凛寒，倒衣惊问紫宸班。","云容不辨阴晴际，月色犹迷爽晦间。","偏喜鸣鸡识钟漏，正怜残梦失江山。","濯缨簪笔初无补，空愧纷纷数往还。"]},{"t":"句 其六","f":"七言古诗","c":["水气横浮飞鸟外，岚光平堕酒杯间。"]},{"t":"雨后回文","f":"五言绝句","c":["绿水池光冷，青苔砌色寒。","竹幽啼鸟乱，庭暗落花残。"]},{"t":"纳凉明教台","f":"七言绝句","c":["台上井泉冰冷滑，城隅川色剑光芒。","多惭簿领相宽假，全得南风一日凉。"]},{"t":"出长芦口","f":"七言绝句","c":["涛翻鹭羽连天白，山叠屏风到海青。","客路浮生两如寄，万重波里一浮萍。"]},{"t":"杂诗 其五","f":"五言古诗","c":["齐有梁丘据，晋有乐王鲋。","据能爱晏婴，鲋欲残叔誉。","二臣嬖两朝，事君为悦豫。","景有尚贤志，据逆以为助。","平失宥善心，鲋乃速其去。","毋以据为贤，易地则同趣。","丈夫处世间，必有遇不遇。","岂无觉者乎，正色君亦悟。","区区嬖幸徒，何忍就朋附。"]},{"t":"周节推移曹州","f":"五言律诗","c":["珠履幕中客，行行亦倦游。","劳歌一长铗，历聘五诸侯。","捧檄为亲喜，问程轻旅愁。","遥怜在陈士，无友重悲秋。"]},{"t":"上书行","f":"词","c":["仕不至二千石，贾不至五百万。","此事夸者忧，而非志士叹。","君不见下邳少年授书起，幄中运筹制千里。","功成不受三万户，拂衣归从赤松子。","君不见计倪半策诛强吴，鸱夷扁舟浮五湖。","三致千金不自擅，至今籍籍宗陶朱。","大贤富贵不为己，心事邈与常人殊。","逢时致身如反手，云蒸龙变无时无。","君勿爱上书献赋称贤豪，刺绣倚市相矜高。","丈夫昔曾笑徒劳，商贾旦旦争锥刀。"]},{"t":"拟古六首 其一","f":"五言古诗","c":["南辕适郢都，日与冥山背。","重生与徇名，夙昔不相待。","藜羹采薇蕨，芰制兰为佩。","游乐天地间，安知一身外。","麒麟斗大荒，日食星见沬。","夷齐饿西山，咨嗟尔胡罪。"]},{"t":"拟古六首 其二","f":"五言古诗","c":["泽陂生芙蕖，映此蒲与荷。","彼美不可逢，忧心涕滂沲。","行乐在及时，株林起酣歌。","欢宴未渠央，国门拥干戈。","巫臣视不悟，室家婴祸罗。","谋己既不忠，孰能为君多。"]},{"t":"拟古六首 其三","f":"五言古诗","c":["赵王飞龙驾，翱翔羾天关。","尘土暂反顾，金玉高如山。","自喻固适志，超遥亡愧颜。","安知马服子，军破不得还。","前亡四十万，后复围邯郸。","虚盈固天理，循环乃无端。","觉寐已不殊，何况百岁间。","嗟嗟道傍子，万金非所安。"]},{"t":"拟古六首 其四","f":"五言古诗","c":["秦昭登西山，慕与火帝游。","颓林刊乔木，诏世为博筹。","富贵良未厌，夸谩岂知尤。","投龟诟苍苍，楚灵轻九州。","涂穷乾溪旁，众散不可留。","徘徊饿山泽，觉失涓人畴。","新王固有命，玉衣被累囚。"]},{"t":"拟古六首 其五","f":"五言古诗","c":["嵯峨三神山，浩荡仙圣游。","金台冠绝景，玉果垂千秋。","龙伯日已侵，巨鳌幸无忧。","波涛各一隅，但见云气浮。","跂予望可及，隐约清浅流。","大帆交问津，长风辄回舟。","不怨道路邅，所悲到无由。","世主自甘心，仙者非有求。"]},{"t":"拟古六首 其六","f":"五言古诗","c":["老莱隐穷楚，因与时世隔。","暮归怪车辙，夜起避山泽。","若人不可见，况肯低颜色。","安知丛台下，一旦三千客。","西边竟不还，嗟哉少良画。"]},{"t":"读黄寺丞十月十三日寄原甫诗因同作","f":"五言古诗","c":["寒日流短明，凉风起秋色。","嗷嗷雁晨翔，悄悄蛩夜织。","节物悲旅人，天地亦行客。","心事已如翁，但知头未白。","黄公青云气，畴昔振六翮。","成纪独不侯，长沙尝远谪。","卖瓜青门外，种豆南山侧。","浩歌写穷愁，我预闻损益。","外事来无涯，开口笑不得。","惟当林下游，相存度阡陌。"]},{"t":"续董子温咏陶潜诗八首 其一","f":"五言古诗","c":["佳鱼乐潜深，智鸟不远飞。","达人避形役，逝与风波辞。","逍遥彭泽下，聊然三径资。"]},{"t":"续董子温咏陶潜诗八首 其二","f":"五言古诗","c":["好酒岂吝情，读书不求解。","天真任自我，淳白忘机械。","鼎鼎世上名，百年竟何赖。"]},{"t":"续董子温咏陶潜诗八首 其三","f":"五言古诗","c":["嘉树每交荫，时鸟初变声。","欣然环堵居，自觉轩冕轻。","予亦葛天民，千岁同此情。"]},{"t":"续董子温咏陶潜诗八首 其四","f":"五言古诗","c":["马队待贤士，久知喧且卑。","周生自晚悟，徂谢仍响随。","岂若田亩间，尊酒时赋诗。"]},{"t":"续董子温咏陶潜诗八首 其五","f":"五言古诗","c":["时命昔大谬，贤杰同隐沦。","陶公晋卿族，晚节耻屈身。","躬耕抱羸疾，嗟哉畎亩勤。"]},{"t":"续董子温咏陶潜诗八首 其六","f":"五言古诗","c":["道术既分裂，人人得其偏。","丹青照千载，始觉真检全。","尔时扬仁风，到今犹慄然。"]},{"t":"续董子温咏陶潜诗八首 其七","f":"五言古诗","c":["贵生未必全，徇名良自贼。","区中共兹患，形影相与惑。","神释乃超然，道真于此得。"]},{"t":"续董子温咏陶潜诗八首 其八","f":"五言古诗","c":["篮舆适山野，葛巾傲宾客。","既无轩冕拘，讵可形骸索。","富贵能畏人，千秋但惭色。"]},{"t":"偶作","f":"五言古诗","c":["时命有通塞，百龄皆谓然。","流行自非我，底滞亦在天。","人知信百龄，阴定不可迁。","苟云有所系，朝旦犹亿年。","天地无穷期，百龄未为绵。","朝旦不可期，人事皆具前。","所以贤达人，放心无所县。","万涂以一究，会理宁复偏。","六月淮水深，南风阻归船。","客行厌滞淫，亲朋限长川。","至言莫与闻，达理谁为诠。","无以谢羁愁，聊作言命篇。"]},{"t":"效白公诗 其一","f":"五言古诗","c":["不得起厌心，厌便住不得。","不得作恋想，恋即去不适。","厌生憎疾业，对面为怨贼。","恋结贪著因，转脚落沈惑。","上士体自然，知慧金刚力。","中人勤埽除，补阙塞瑕隙。","行莫到门返，饥莫看人食。","欲验齐死生，且觑居官职。"]},{"t":"效白公诗 其二","f":"五言古诗","c":["默坐念逝者，身存至头白。","起行观病者，身健有馀力。","出门视劳者，身閒免事役。","入乡阅贫者，身足饱衣食。","寓形天地间，幸已不失职。","奈何不自休，汲汲复戚戚。","大鹏弥九区，转动恐逼窄。","鹪鹩巢一枝，随意翻羽翼。","驰光无停留，驷马方过隙。","君看北邙山，贵贱一真宅。"]},{"t":"效韦苏州古调诗","f":"五言古诗","c":["于人无旧新，相见常为欢。","本不作崖岸，中亦非断刓。","宾僚自了事，县邑无旷官。","岂惟竞勉力，退亦绝閒言。","观者以为稀，不自知其然。","吾闻西方说，夙世常有缘。","将此会中人，厚德无雠怨。","文人讳异术，且以儒事论。","孔圣不可及，孟氏固所尊。","轲云创业易，成功则在天。","乃知古今士，无有能与贤。","达人同众人，不肯妄自专。"]},{"t":"古意 其一","f":"五言律诗","c":["牛刀割雏鸡，未足为深耻。","奈何狐父戈，资以斸牛矢。","鲁人称家丘，会计当而已。","郢匠不挥斤，其质久已死。"]},{"t":"古意 其二","f":"楚辞体","c":["秉心若松柏，洁志如雪霜。","松柏摧为薪，雪霜晞春阳。","乃知丈夫勇，万物无以方。","赐兮不受命，枨也安得刚。"]},{"t":"杂诗 其一","f":"五言古诗","c":["重生世所同，徇利良独愚。","嗟彼纬萧子，安事千金珠。","沈身九重渊，脱死骊龙胡。","得失觉寐间，危哉悲矣夫。","九方焉知祥，梱也终奚如。","虽同国君仓，乃在渠公衢。","馁也命使然，颜原亦多娱。"]},{"t":"杂诗 其二","f":"五言古诗","c":["荆山有奇璞，贵乃和氏俦。","连城讵云多，一视以为优。","携挈向都市，光彩倾天球。","虽无指瑕累，顾得千金售。","惊诧遽自反，闭匿成千秋。","岂忘待时意，欲往仍迟留。","凡目陋至宝，后生异前修。","苍蝇矧多变，珉石仍先收。","万一人我欺，永为神物羞。"]},{"t":"杂诗 其三","f":"五言律诗","c":["樊迟请学稼，尼父已深愠。","安知连城守，榷酤殿最问。","周公无彝酒，用是垂大训。","愿得烹弘羊，耕织始安分。"]},{"t":"杂诗 其四","f":"五言古诗","c":["龙伯钓鳌时，连六方自快。","事缘贪饵起，上帝独何罪。","土疆日侵削，形躯仍眚杀。","才馀数十丈，尚足令人骇。","寄言诤毕人，努力事机械。","何当大荒野，与尔竞行迈。"]},{"t":"杂诗 其六","f":"五言古诗","c":["伯夷饿首阳，太公封营丘。","同时海滨人，将老归西周。","世故莽难量，后王异前修。","徒让千乘邦，不如畜阴谋。","良知命分然，何怨复何尤。","尘埃采薇诗，益使夸者羞。","自兹奸雄人，日日希公侯。"]},{"t":"杂诗 其七","f":"五言律诗","c":["虚舟适谁迕，飘瓦殊暂然。","忮心自无怨，岂必绝世贤。","握火欲提人，唾空不至天。","一心抱区区，万事长可怜。"]},{"t":"杂诗 其八","f":"五言律诗","c":["佚女处瑶台，丰肌艳皎皎。","端令鸩为媒，告我以不好。","犹豫令人悲，自悔辩不早。","如何问雄鸠，佻巧岂可道。"]},{"t":"杂诗 其九","f":"五言古诗","c":["野人构茅茨，栎柱樗作栋。","不意豫章材，一时同见送。","拓手百尺长，连轸万钧重。","斤斧欲安施，弃置因无用。","本是绝世姿，胡为与众共。"]},{"t":"杂诗 其十","f":"五言古诗","c":["臧孙被恶名，鲁侯失其位。","轩冕非不尊，家富马千驷。","不用子家羁，而弃柳下惠。","末仪谅何为，矧论仁与智。","窃位良足羞，乃复为君谥。"]},{"t":"杂兴","f":"五言古诗","c":["阿嫫年八十，睢盱事妆饰。","仍夸少年日，自谓美无敌。","与子不同时，寥落复异域。","人事虽万殊，近者犹可测。","颓颜与白头，何日好颜色。"]},{"t":"读李某诗","f":"五言古诗","c":["李某崆峒人，生长西北蕃。","赤鬓如猬毛，仅能为汉言。","筋力勇自负，马上带两鞬。","作贼十数年，身有百刃痕。","泳河不用舟，羊革随轻轩。","危厄辄自脱，天幸尚得存。","过壮忽自悔，翻然归汉恩。","徙家汾水阳，百口蒙轻温。","拜官随立功，俄列上閤门。","封侯未可量，专城谁复论。","已见狄将军，堂堂枢府尊。","由来功名际，雕鹗胜皇鹓。","富贵百恶除，讵问钳黥髡。","岂与诗书士，履绳不敢奔。","终身蹈薄冰，众口犹喧喧。"]},{"t":"王四十处见舅氏所录外祖与日本国僧诗并此僧诗书作五言","f":"五言古诗","c":["沧波浩无涯，泱漭际朝日。","安知鲛鱼渊，而有邑居室。","便风送来帆，夙昔多人物。","始信天地间，见闻岂云悉。","惆怅蓬莱说，胡为浪自黜。","夷倭与侏离，九译迷彷佛。","书问顾已同，纸墨存落笔。","俛仰六十年，举指不任屈。","好事见君家，闻诗初未失。","杜邺富小学，平通知祖述。","鄙老独何能，执书几涕出。"]},{"t":"偶题","f":"五言古诗","c":["旦出辄暮归，终年长役役。","自顾若有营，谁言了无益。","少小不如人，老大转衰僻。","昏忘复相仍，十事不一忆。","劳心非所长，但觉安坐食。","使我忍愧羞，不如学劳力。","劳力当自耕，自耕还自织。","百亩为己忧，虽忧乃易释。"]},{"t":"喜雨和任判官奉呈太守","f":"五言古诗","c":["愆阳历冬序，入春日光赤。","原野为之焦，无复青青麦。","明廷恤农功，诏旨怀悯恻。","谁能共此忧，惟良二千石。","祷祠遍群望，百神潜率职。","迅雷出深渊，密云会将夕。","应龙不无神，女鲜罪所极。","滂沲浃宇宙，变化才瞬息。","矧兹颢穹意，岂独垂沛泽。","尝听君平言，以兹消薄蚀。","周宣成阳事，往往在简籍。","不闻二美具，介福逾万亿。","三农耒耜出，自此丰黍稷。","使君凭熊轩，劝耕驻阡陌。","上客歌吉祥，清文缀环璧。","我岂击壤翁，不能知帝力。","斐然遂成章，聊用同悦怿。"]},{"t":"赠周员外鼎","f":"五言律诗","c":["束发去乡里，白首还旧丘。","曾无高盖车，顾为夸者羞。","岁晏东皋田，躬耕方薄收。","知君近有道，足以无外求。"]},{"t":"次韵和王平甫赠张舍人","f":"五言古诗","c":["通物乐自任，济时常后安。","戢翼思迅风，腾鳞慕惊澜。","天书进廉良，大罟纲目宽。","顷来中林士，继踵青云端。","王侯经纬气，锦绣罗肺肝。","念当五鼎食，肯甘一瓢箪。","著书成揣摩，脱剑横镆干。","孟明已焚舟，廉颇方据鞍。","闭门谢尘轨，釜鱼朝未餐。","竟完稽古力，已使同学叹。","凤池响鸣佩，芸阁峨高冠。","忘年义已深，踵门情更欢。","纵谈剧流輠，处画逾转丸。","广廷来风清，落日微雨残。","凉泉为濯溉，佳树聊盘桓。","长歌斓篇轴，大盟粲珠盘。","宁为端木子，矜此道旁观。"]},{"t":"闵雨","f":"五言古诗","c":["山上田万顷，江中水千里。","东流自瀰漫，旱苗日焦死。","惜哉不能救，地势正如此。","云雷未兴潜，蛟龙困泥滓。","昭回虽在天，叹息真已矣。"]},{"t":"君子行","f":"五言古诗","c":["君子贵自然，不为时俗观。","升车不广欬，即席不变颜。","疾驱不駷辔，高张不急弹。","尘埃视流俗，中立何可干。","颜生处陋巷，求仁得所安。","箪食一瓢饮，孔圣推其贤。"]},{"t":"雨中","f":"五言古诗","c":["丹桂更束薪，白璧偿斗粟。","况兹风雨朝，泥潦坏墙屋。","败灶方生鱼，并日能薄粥。","始知箪瓢人，陋巷本自足。","宁见子桑诗，若歌复若哭。"]},{"t":"游景灵宫","f":"五言古诗","c":["汉家祈年宫，玉宇黄金阶。","回廊起层城，高阁横苍崖。","觚棱拂星斗，广除霁尘霾。","清渠寒泉交，盛夏凉风湝。","火云赤宇宙，道涂若燔柴。","幸兹清凉游，复此朋友偕。","前殿朝众灵，瑄玉兹禋柴。","顾予尘土姿，进拜增慄斋。","扫庭有馀洁，酌水欣素怀。","并坐俯坚珉，长吟翳高槐。","丹青四壁画，权舆自轩娲。","千年羽化人，志怪非齐谐。","始知慕神仙，自顾轻形骸。","圣贤几吹吷，寒暑一病痎。","学道赖远复，养生知有涯。","悟真觉理胜，适志忘事乖。","伯阳推谷神，庄叟称安排。","英风摩盖壤，遗躅欣吾侪。","飞云肆冥鸿，拘井嗤沈蛙。","虚心自兹得，归去颜色佳。"]},{"t":"惠州丰湖","f":"五言古诗","c":["昔在葛稚川，求为勾漏令。","丹砂颇易得，罗浮聚仙圣。","穷荒非人情，适己自无竞。","千岁若须臾，斯人已辽夐。","忽闻惠州守，修旧有佳政。","涨泉作丰湖，百顷湛明镜。","芰荷争秀发，鱼鸟恣潜泳。","新畴日已多，耕者乐其盛。","高斋面空阔，写影穷绿净。","长啸来清风，炎蒸亦无病。","勤忧本劭农，爽豁赖怡性。","宁须学神仙，岂必谢朝请。","明珠还合浦，夙昔人相庆。","君有近郭田，足继甘棠咏。"]},{"t":"柘湖","f":"五言律诗","c":["南海浮柘山，尝试问水滨。","桑海变未久，婉娈兹为神。","昔闻仇池穴，上有牛女津。","物理宁可穷，空惊舟楫人。"]},{"t":"东关山水","f":"五言古诗","c":["青霭望不极，连峰如置关。","不知清溪水，漾漾出其间。","孟夏江水深，溪流正西还。","崖根乱石多，散激声潺潺。","杂树色相映，密竹不可删。","造幽览众妙，抚事清心颜。","洄洑自多鱼，网罟罗前湾。","幽人闭上方，缭径才可攀。","畴昔新安江，寤寐龙门山。","目击暂有遇，绝胜犹班班。","客程非趋时，淹泊宁所艰。","少留尽馀兴，更伴浮云閒。"]},{"t":"束刍","f":"五言律诗","c":["束刍食骐骥，斗水活蛟龙。","辕下虽可哀，泥蟠未必穷。","解骥就衢路，借龙起雷风。","寥寥四海广，去矣君安从。"]},{"t":"题常宁黄令洒然堂","f":"五言古诗","c":["叔度万顷陂，清浊谁能料。","割鸡用牛刀，吾亦寄一笑。","示我林下诗，笔力勇奔峭。","故知才者心，玩好必同调。","岑岑青玉竿，千百壮非少。","清风扫埃尘，日影金色照。","环墀发寒泉，霜剑初脱鞘。","枕流不枕石，俯仰穷听眺。","上堂梵呗声，空寂总众妙。","兹亦忘言徒，领理会其要。","翔禽竟来集，狐猿远相啸。","不作问鵩翁，刻意湘累吊。"]},{"t":"十月一日","f":"五言古诗","c":["十月西北风，肃肃天雨霜。","节物感人多，客子心内伤。","心伤鬒发变，引领望故乡。","故乡多乔木，丘垄生白杨。","柏叶自宜翠，草根今已黄。","旦思归阳陂，暮忆栖后冈。","况此佳辰朝，都邑事有常。","平明重城开，车马如飞翔。","贵贱同一丘，蒿艾连石羊。","恸哭朔风悲，一豁沉痛肠。","奈何守微禄，局促限一方。","隳官固非孝，捧檄固已狂。","黾俛聊自抑，涕流浩沾裳。"]},{"t":"吹台","f":"五言古诗","c":["梁王游赏地，乔木空白云。","无复歌吹响，况乃麋鹿群。","梵刹拟化出，山河如绮分。","北望十二衢，佳气正絪缊。","贤者而后乐，固如孟轲云。","感此多远怀，因之濯尘纷。","闻君已先我，携手皆能文。","置酒临沧流，披窗溯南薰。","由来登此台，寂寞谁独闻。","慷慨作歌诗，怅然哀古人。","千载岂不辽，忽如波沄沄。","适意正在饮，无为惜酣醺。"]},{"t":"送欧阳永叔留守南都","f":"五言古诗","c":["白水帝旧里，大火天明堂。","王都异丰镐，原庙崇高光。","毕命继三后，商邑正四方。","保釐自古贵，佥曰朝论昌。","前旌鸟隼旟，左佩麒麟章。","阨途乱铙吹，先路交壶浆。","风物盛山东，令人忆游梁。","缅然严邹徒，赋笔尝慨慷。","废池扫清冷，旧苑开荒凉。","终留相如坐，一伴凫雁翔。"]},{"t":"竹床","f":"五言古诗","c":["炎光裂厚地，江汉如燖汤。","闭户乐甘寝，婉娈在一床。","问我何独尔，爱此编竹光。","侧身照琬琰，热手循雪霜。","有时万里梦，倏往浮湖湘。","遂令傲轩冕，弥日慵下堂。","昔闻负暄老，意欲夸天王。","我亦悲世人，触热趋道傍。"]},{"t":"南窗诗 其一","f":"五言古诗","c":["习静觉自逸，养恬遂忘俭。","始知一席安，不比千乘忝。","微风触乔木，清气袭珍簟。","心空物莫喧，神超梦无检。","簟瓢敢望回，弦歌欣与点。","彼哉晋楚富，吾道安用慊。"]},{"t":"南窗诗 其二","f":"五言古诗","c":["抱书南窗下，日午天光亮。","阴阴夏木长，翙翙巢禽鬯。","因之省疏慢，亦喜就閒旷。","散帙寄忘怀，曲肱从所尚。","临文眩今古，抚事杂欢怅。","劳形竟何为，有心得非妄。","释卷忽自娱，收视已神放。","远从华胥游，却立钧天上。","万缘倏皆空，至乐了无状。","悲哉俗学徒，头白迷归向。"]},{"t":"登慈佛寺","f":"五言古诗","c":["清溪浅褰裳，嘉树大盈抱。","古寺向百年，地幽景深好。","连峰拱苍翠，秋雨洗穹昊。","客至登高楼，西风动衰草。","雄豪昔未遇，饭粥殆将老。","岂知风云期，草昧及天造。","杖箠城下邑，倾囷载金宝。","良知积困约，固不慰枯槁。","铭勋久犹存，馀烈漫浩浩。","空馀祇树园，常此伊蒲祷。","阶除稍芜没，梁栋乍倾倒。","顾览为徘徊，物化那能道。"]},{"t":"筑室种树","f":"五言律诗","c":["筑室非我乡，种树非我庐。","未尝三年淹，劳力岂不虚。","远嘉叔孙子，去故情若初。","此意人不知，嗟哉贤大夫。"]},{"t":"和王绚道赠高七植竹","f":"五言古诗","c":["人言植物中，唯竹类有德。","虚心道所存，外劲礼自饰。","风霜不改阴，一何金玉色。","丘泽无变根，还如古人直。","繁花岂无实，所待鹓鸾食。","卑枝亦可栖，不许鸱鸢息。","为君裁管籥，于此谐金石。","为君度短长，于此齐寻尺。","济川倚巨楫，扶老杖轻策。","大厦莞簟安，射侯弓矢力。","乃知天材美，固待君子识。","饱闻昆崙秀，盛说潇湘碧。","岂曰生不迁，念当厚封植。","惟君傲声利，心远地更僻。","择交独此君，开径如三益。","清风共忘言，明月为莫逆。","还当扫尘榻，会待遗名客。"]},{"t":"涉伊水宿宝应寺","f":"五言古诗","c":["日夕车马烦，路绝临清伊。","云光与水色，极望相逶迤。","饮马清泠泉，凉风吹人衣。","白石可历数，游鱼仍俯窥。","浅濑乍褰裳，榜舟亦迟迟。","古木号乱蝉，白鸟时独飞。","上方两高阁，向水双朱扉。","迢迢际烟霞，安得青云梯。","暝投中峰宿，四山凝夕霏。","钟鸣众禽寂，孤灯明翠微。"]},{"t":"弹乌","f":"五言古诗","c":["夷羿射赤日，霍然落天衢。","独成万世名，皆曰摧九乌。","逼仄慨时俗，臂射妨四禺。","谁能雏鷇间，计校死与枯。","孰谓党频频，莫黑相为徒。","何用知雌雄，攫肉争欢呼。","控弦非百钧，投丸匪明珠。","弃捐不俟时，讵比墉隼诛。","矫翼似知机，回空如改图。","但使庭户清，何必残尔躯。","念无网罗祸，宁当怨除驱。","吾庐正深沈，嘉木多桐梧。","萋萋映朝阳，会待鸾鹓雏。"]},{"t":"雪中退朝与诸同舍登秘阁","f":"五言古诗","c":["密雪晦空曲，天作白玉京。","都城百万家，漠漠浮云生。","束带听鸣鸡，谒帝开承明。","脱身尘埃外，自觉肌骨轻。","归从诸仙子，笑语来蓬瀛。","仰望策府高，天禄郁峥嵘。","步登云蜺表，俯视朝日晴。","寒门杳无涯，珠宫联五城。","珍木比后凋，冥鸿亦同声。","还因阊阖风，共此夷旷情。"]},{"t":"清涟阁","f":"五言古诗","c":["平湖侵危台，天水相竞入。","萦回古屿间，空阔众境集。","大邦屏东南，开府记百十。","胜游虽日来，面势忍遗葺。","能声绍岂弟，敏政常暇给。","喜闻栋梁新，甫见规模立。","横空眩藻丽，构迥愁嶪岌。","居然心意会，似匪人谋及。","草树亦增华，神明非旧习。","青凝夕霏翠，冷激回风湿。","去鸟指暝飞，潜鳞视幽蛰。","达生贵夷旷，外物辞妄执。","皋壤正欣然，苍波仍可挹。","虽云吏隐最，世复登贤急。","徒使棠树诗，千秋意相袭。"]},{"t":"岁寒谷 其一","f":"五言古诗","c":["高松含悲风，绿竹带凝雪。","碧落翻怒涛，深崖堕寒月。","萧条非人境，合沓隐城阙。","爽气露草木，精神立毛发。","初无隐居迹，似为吾人发。","世事谁得捐，相从理营窟。"]},{"t":"岁寒谷 其二","f":"五言律诗","c":["长松过千尺，好馀万丈材。","上有积雪翻，下有清风来。","四时景常好，六月冻不开。","何事吹燕律，独令阳气回。"]},{"t":"过开元寺","f":"五言古诗","c":["晨霜耸乔木，初日明广庭。","俯巢鸟鹊驯，步径莓苔青。","即心百虑扰，造境众独醒。","安禅到无闷，看画匝已经。","梵音腾潮波，幡影垂流星。","天花雨贝叶，帝乐飘鸣铃。","胜缘此邂逅，法界俱清泠。","世喧暂回首，但觉尘冥冥。"]},{"t":"久旱","f":"五言古诗","c":["山城带嵩高，常候嵩高云。","云兴似焚柴，雨注如翻盆。","田莱数百里，下泽犹平原。","虽有耕凿勤，不如霢霂恩。","哀此民生微，所赖刍狗仁。","乃知丘陵外，独有五岳尊。","今春苦淫霖，宿麦才廑存。","过夏乃不雨，穷秋气如燔。","象龙杳无艺，巫鼓空屡奔。","豆苗落为萁，藜莠乘冬温。","黔首困粒食，或有茹草根。","卖牛供租赋，不忍闻此言。","此事亦神羞，谁能叫其阍。","登高望连峰，正见朝烟昏。"]},{"t":"寄题汉中三亭","f":"五言古诗","c":["梁山屏西南，汉水相萦带。","古惟千骑居，今亦一都会。","守邦多伟人，按节森大旆。","治声我家贫，能事斯亭最。","苍峰上盘云，清川近泻濑。","隅分地俱胜，鼎搆势争大。","扶危新栋梁，增旧加粉绘。","功成人不劳，事得文无害。","长涂拥行辀，高宴罗羽盖。","开筵揽锦绣，劝客喧竽籁。","陪游惭望回，请赋嗟自郐。","安得凌风翰，径厉褒斜外。"]},{"t":"养生","f":"五言律诗","c":["世自不乏我，我亦安慕时。","形骸与轩冕，冉冉相背驰。","守约道可学，战胜心自知。","虽无一朝乐，亦免终身悲。"]},{"t":"昆山","f":"五言律诗","c":["兹山本无玉，而有昆丘名。","若人东南秀，遂驰终古声。","蓝田亦若初，荆山高不倾。","嗟嗟九原骨，千年不重生。"]},{"t":"正月四日燕饮江氏","f":"五言古诗","c":["献岁发春阳，青炜焕城邑。","群公三朝暇，冠盖如云集。","主人高阳老，馔客素丰给。","开门陈壶觞，从使来者入。","春盘具柔蔬，香稻进玉粒。","高谈剧倾波，纵饮甚啜汁。","战棋效军实，度曲俪风什。","欢穷罍不空，顾惜驰景急。","东风卷初雨，泱漭天地湿。","震雷动龙蛇，稍复离幽蛰。","而我独何为，无闻既三十。","人生行乐尔，身外非所及。"]},{"t":"五行王相诗","f":"五言古诗","c":["长生不我欺，幼学每自坚。","沐浴蕙兰芳，呼吸朝霞鲜。","冠带谒紫皇，左右宾列仙。","临官太清上，拜赐玉案前。","帝王固陈迹，圣智不足甄。","衰容了成稚，白发倏更玄。","病笑留侯晚，妙许成子贤。","死者不复作，尘埃殊可怜。","墓隧侵人居，海水为桑田。","绝迹自此远，飘飖周九天。","胎化两珍禽，羽翼为我先。","养志幸有成，眷言惭自然。"]},{"t":"自蔡河至陈州","f":"五言律诗","c":["舟行过林樾，密树相排挤。","仰视青冥天，飞鸟犹不移。","临流方浩叹，照水分鬓眉。","三十有二毛，中肠默兴悲。"]},{"t":"除日得王深甫书因寄","f":"五言古诗","c":["除日令休吏，官曹停簿按。","深居念驰光，忽忽自兴叹。","七十称寿翁，我今已过半。","时命岂不知，胡为此羁宦。","况兹山野性，放荡破崖岸。","应接人事间，何时无谤讪。","屡诵小雅章，惧为朋友怨。","忽传故人书，远道情不问。","上言久别离，下有加餐饭。","赠我新诗谣，金碧光凌乱。","鹓鸾不铩翮，龙虎谢鞿绊。","乃知鞲上鹰，不及蒿下鴳。","往事那复追，来今犹可谏。","终当颍水滨，躬耕为尔伴。"]},{"t":"之官庐州初至仪真寄原甫","f":"五言古诗","c":["家居非不欢，禄仕亦岂急。","愧身无所劳，而兹养生给。","方刚幸未艾，黾勉冀有立。","谫智无远图，挈瓶庶云及。","圣教非一方，吾愚宁妄执。","所惭鹪蝘微，不过枝与粒。","悠悠我之思，去去异乡邑。","大江浩东流，客悲莽交集。","登船眺洲渚，暝色际日入。","鬒变谁昔然，怅焉寄兹什。"]},{"t":"将之官清水李廷老来会探韵得光字","f":"五言古诗","c":["四十身无闻，忝官省中郎。","未尝学治民，缪假铜墨章。","置我所读书，低心课农桑。","况此戎马间，属国皆军羌。","陇山一何高，缇群正相望。","聚粮三月过，始厌西路长。","故人矜我劳，置酒客满堂。","固知后会艰，慨慷俱毕觞。","天弧射狼星，旄头烂垂光。","分我一汉节，系取穹庐王。"]},{"t":"江南曲","f":"五言古诗","c":["江南多芙蓉，水绿看最好。","轻舟浮江来，白露秋意早。","露白秋已晞，游子行未归。","采香欲谁赠，但见群鸥飞。","鸥飞不避人，思我平生亲。","当亲而返疏，怅望空水滨。"]},{"t":"题欧阳永叔新凿幽谷泉","f":"五言古诗","c":["江南多名山，少有琅琊比。","琅琊盛泉石，晚得幽谷美。","将非造物者，留以待君子。","乃知智且仁，必好山与水。","公有高世材，此山共森峙。","公有济物心，此泉共清泚。","泉始居地中，隐塞未如此。","今为万丈流，近自一勺始。","东浮沧溟广，下益松桧喜。","奈何公之惠，及更局千里。","安得从公居，曲肱偃吾几。","安得从公游，枕石洗吾耳。","是非付天壤，尘事如脱屣。","当为谷中叟，肯为轩冕起。"]},{"t":"张六至","f":"五言律诗","c":["君居众人里，有如珠玉然。","世疑假浑沌，我识真神仙。","独抱潇洒意，不为势利牵。","少留衡门下，谈笑忘吾年。"]},{"t":"题园树","f":"五言古诗","c":["看花前日雨，吹叶昨来风。","羁旅淹留际，年光瞬息中。","今朝雪消后，重见树梢红。"]},{"t":"先泊龟山夜闻后来者","f":"五言古诗","c":["秋雁去极浦，寒星落远山。","太虚混茫外，群动有无间。","中夜数声橹，孤舟何处还。"]},{"t":"次韵和苏子瞻赠王仲素寺丞","f":"五言古诗","c":["龙虎不受羁，鸾凤不啄泥。","仙人云涛观，俗子闾巷迷。","念昔喜读书，五车号轻赍。","东瞻识津涯，西顾分町畦。","博物辨鼮鼠，诵赋嗤雌蜺。","轩冕不克求，舌在徒问妻。","世事莫相告，慕虚但攀稽。","赖有逍遥篇，尔来颇思齐。","道真本微眇，至言乃筌蹄。","壹气中夜存，大方刓角圭。","勉从赤松子，定有青云梯。","非若朝市门，强力相排挤。","晚友王子乔，如得照水犀。","因之喻苏耽，衰暮毋噬脐。","缅思灊天柱，云白风凄凄。","筑居留四邻，与子参杖藜。"]},{"t":"次韵和原甫登禅智寺上方院二首 其一","f":"五言古诗","c":["访旧起废境，赏心如此回。","平川似曲沼，崇冈象层台。","前驺经林薮，飞盖凌崔嵬。","漏迟日向永，景照春已来。","即事有馀胜，怀古常兴哀。","寥落江都宫，壮丽安在哉。","方昔盛欢娱，宁知名已颓。","一咏宜春赋，怅然为停杯。"]},{"t":"次韵和原甫登禅智寺上方院二首 其二","f":"五言古诗","c":["夫子信与点，赐也敢望回。","遥知成春服，复此登春台。","一水近清浅，众峰远崔嵬。","林端白云暝，竹下清风来。","谷深莺徐啭，川迥雁仍哀。","宾至赋乐胥，觞行咏康哉。","词锋与醉墨，馀响若底颓。","何以喻珍奇，繁露将玉杯。"]},{"t":"次韵和张屯田新年六十九","f":"五言古诗","c":["春风数尽九，节物都非旧。","幕府省文书，阶除减奔走。","慵怜啼鸟唤，老藉高花诱。","前林通杖屦，小榭勤箕帚。","喜逢张公子，七十健少有。","解吟长韵诗，不避盈樽酒。","囷仓年谷实，邻里均石斗。","樊圃畦陇成，馀力到花柳。","长为子孙主，击壤欢百口。"]},{"t":"人日同弟侄会贾夷叔游射东园和仲冯以退之弄字韵次用","f":"五言古诗","c":["宦情本羁旅，节物犹戏弄。","欻见林下风，初开水滨冻。","登高举遗俗，剪綵随众用。","暄和畅四体，杖履率群从。","觞酒从我来，林塘复君共。","捷奕判死生，劲弓严纵送。","新荑缀高柳，潜颖发枯葑。","天空雁相喜，泉洁鱼始纵。","驰光若漫漫，来事常偬偬。","君看飞云阴，既去不可重。"]},{"t":"从刘园至澄心寺","f":"五言古诗","c":["春泥稍已熟，鹳鸣天气新。","野竹自有径，空林不值人。","悔将车马来，鸥鸟未可亲。"]},{"t":"献欧阳永叔","f":"五言古诗","c":["毛生重九鼎，剧孟雄敌国。","布衣未易轻，壮士多感激。","遍读近古书，仰求当时人。","胶弦非工声，直钓良苦辛。","举世无与游，行且三十春。","岂乏富贵士，相视犹埃尘。","屈指东诸侯，侧闻廷中臣。","霜毛九皋鹤，绝足大野麟。","往者移太常，正气横苍旻。","连翩少垂翼，浩荡俄纵鳞。","天衢自兹亨，要路实有津。","谏疏必焚草，王言粲如纶。","云霄入顾眄，方牧宁逡巡。","岂惟国忧贤，固是材致身。","南金一销铄，荆玉成缁磷。","少留股肱郡，不废廊庙珍。","道悠任逾重，文雄声益振。","指掌五代论，藻鉴盈门宾。","信陵虚左乘，程子倾盖亲。","意气已然诺，许与忘旧新。","孤剑虽蒯缑，丈夫不羞贫。","愿言敝缊袍，试托狐貉邻。","往无鲍叔知，那识夷吾仁。","毋令箕山客，洗耳兹水濒。"]},{"t":"初冬晨起作四声诗 平声","f":"五言律诗","c":["霜风吹帘栊，天高明星晞。","邻鸡三号呼，林乌皆惊飞。","严城开重门，危冠驰轻肥。","疏慵徒安眠，隆冬方无依。"]},{"t":"初冬晨起作四声诗 上声","f":"五言律诗","c":["营居依蓬茅，在我颇显敞。","阳晖馀朝温，野景有远想。","年华无淹停，俛首已古往。","全生谁为贤，偃仰与鞅掌。"]},{"t":"初冬晨起作四声诗 去声","f":"五言律诗","c":["山林何时归，陋巷似好遁。","通衢皆高轩，竟岁谢讯问。","行歌聊逍遥，衣敝信命分。","殊胜蒙尘埃，势利强自困。"]},{"t":"初冬晨起作四声诗 入声","f":"五言律诗","c":["开门谁频来，设榻得逸客。","明窗容棋枰，日昃熟藿食。","丛兰香襟裾，雪色覆辙迹。","忘形非无缘，拙直独莫逆。"]},{"t":"舟次淮阴寄张郎","f":"五言古诗","c":["风波不可测，夷险系所遇。","泊舟淮南岸，始知散千虑。","高秋气萧爽，日夕稍寒雾。","漠漠烟水深，翩翩飞白鹭。","值景信所贪，有怀劳反顾。","何时见归艎，啸吟成一助。"]},{"t":"记梦","f":"五言律诗","c":["光彩曜白日，笑语凌高风。","冥漠分永诀，梦想如暂同。","当寐讵知觉，视色旋成空。","达性悔不早，百忧坐相攻。"]},{"t":"梦杨十七","f":"五言古诗","c":["昔游梁宋都，偶与夫子并。","尔来各分飞，岂独岁月永。","往事若有亡，魂交幸俄顷。","如从杏山宴，坐弄南湖景。","置酒肠已开，论诗心为领。","君言此会难，惊悟卧南郢。","人生日月内，觉寐谁能省。","适心故为欢，好梦亦所幸。","自吾客遐方，尘事久幽屏。","乃知逃空虚，终日思咳謦。"]},{"t":"张君以六十九作诗自道其康宁余时年五十九感而自咏","f":"五言古诗","c":["新年五十九，处事觉陈旧。","敲石火难停，下坡日如走。","诗书本拙画，孔老徒善诱。","谁为万乘器，谬享千金帚。","尔来专城居，迟暮亦何有。","此邦白发人，夫子称祭酒。","贫居玩一瓢，健饮轻五斗。","愧君十年长，顾已甚蒲柳。","方将外形骸，馀事勿挂口。"]},{"t":"送汾西高长官","f":"五言古诗","c":["尧风远以深，千载殊未央。","寥寥蟋蟀诗，在晋谓之唐。","今君试宰邑，正复汾一方。","民社非不荣，腰有铜墨章。","安得六七十，而非诸侯邦。","翳翳桑麻区，鸡犬音相望。","因俗固易治，学古子所长。","勿嗤俭以勤，葛屦从履霜。","期年会有成，坐见鸣凤翔。","吾知尹翁归，治迹由平阳。","远道怅分手，游子怀故乡。","离群以索居，愧惭参与商。"]},{"t":"送陈同年游固陵","f":"五言古诗","c":["送君固陵游，勿忆炎汉初。","天地不中裂，雄杰争锱铢。","追兵下阳夏，百万风雨俱。","鸿沟不可恃，平分知厚诬。","叱咤梁齐君，王业成斯须。","斗智不若谖，小信良区区。","尔来数千岁，英气存信书。","山川未改旧，壁垒皆丘墟。","寄心阮嗣宗，抚掌当踟蹰。"]},{"t":"汴上二首 其一","f":"五言古诗","c":["浑黄下湍流，地势东南泻。","潜石激阴怒，烈风镇相假。","客行何艰哉，极力无可者。","永路未遽央，扁舟安得舍。","端思九衢尘，快意坚车马。"]},{"t":"汴上二首 其二","f":"五言古诗","c":["客从江湖来，风水畏难测。","行行汳渠上，牵挽意不适。","惊湍卷前湾，怒浪潜乱石。","至柔动必刚，况使相推激。","随波叹异心，枉道复退尺。","顾思挂高帆，勇往逾箭射。","行险何足忧，万事亦天力。"]},{"t":"望九华山","f":"五言古诗","c":["初行江南道，山水皆可爱。","忽见九华峰，瑰奇又堪怪。","去之百馀里，青翠若无类。","群山特微茫，屹起视其背。","初疑楚人剑，真能倚天外。","快意入浮云，耻令白日晦。","又如群游龙，垂胡饮江濑。","俯仰令人惊，顷刻千万态。","未知灊与霍，何能配嵩岱。","得无失其真，吾为古人悔。","山中多良田，泉源得灌溉。","颇思藏其间，将家事耕耒。","尘氛未决往，暂若观画绘。","日暮飞鸟还，临风久儓儗。"]},{"t":"晚春登楼","f":"五言律诗","c":["川原自不改，春事已畴昔。","众芳生晚绿，远树森重碧。","流莺歇复歌，乳燕飞暂息。","对酒独慷慨，惜无同心客。"]},{"t":"和谢师厚鸨诗","f":"五言古诗","c":["君为田鸨吟，哀彼田鸨艰。","无舌以自鸣，衔恨安所宣。","我徵古人诗，得之唐国篇。","苞栩何足哀，悲在不得言。","君看鶗鴂鸣，众芳为不蕃。","黔雷讵有知，奋此亦已偏。","万生讵可穷，孰能厌多闻。","颇识鸟兽名，从子求诸田。"]},{"t":"邾园水阁煎茶","f":"五言古诗","c":["溪梅已烂漫，溪水方绿净。","惜春聊插花，愧花还照影。","淹留待烹茶，初觉昼日永。"]},{"t":"登瓜步魏武庙","f":"五言律诗","c":["阴崖不见日，侧径劣容步。","鬼神宅冢奥，与物随绘塑。","惟惜饮马初，想见投鞍处。","木落山势高，潮平洲渚露。"]},{"t":"华山隐者图","f":"五言古诗","c":["六王昔崩荡，秦帝按剑兴。","虎争四十年，方隅为之平。","豪气竟未已，用民如不胜。","因河既为池，起洮复坚城。","嘉哉诸老翁，携手西山行。","避世往不返，逍遥尘外情。","明星备洒扫，巨灵为友朋。","饥食玉井莲，手携三秀英。","世事一朝变，龙蛇复纵横。","石火咸阳焚，蚁聚成皋争。","致身青云外，顾视不为惊。","万期乃须臾，安知谷为陵。","尔来见图画，真气犹冥冥。","世人但蓬蒿，安知鸿鹄征。","桃源迷去路，蓬莱浪知名。","异时三峰游，会当慰平生。"]},{"t":"咏史 其一","f":"五言古诗","c":["原尝四公子，养徒各三千。","金玉弃如沙，快意当目前。","好士要尽心，安知悉英贤。","虽非霸王资，豪气故翩翩。","生为战国雄，死亦名千年。","晋重未反国，曹郑方接连。","靳惜粪土间，不能捐一钱。","宗社几不食，恶名高属天。","山枢刺昭公，死矣悲宛然。","如何万乘邦，徒为人所怜。"]},{"t":"咏史 其二","f":"五言古诗","c":["秦兵谋大梁，决河灌夷门。","百万皆为鱼，闾里无一存。","不用无忌谋，人人皆有言。","天方纵秦毒，荡涤乾与坤。","虽得阿衡佐，谁能救崩奔。","政先趣嬴祸，指鹿遂亡秦。","翟义为汉谋，摄省因即真。","为忠岂不难，杀身亦已仁。","天道良悠悠，成败难重陈。","不见商山翁，采芝乐全真。","羽翼安储皇，天子不得臣。"]},{"t":"晚归望月","f":"五言古诗","c":["落日隐城头，深林已微暝。","相携步明月，诘曲穿缭径。","稍稍归鸟栖，四风乱钟磬。"]},{"t":"六月七日大热及晓微雨","f":"五言古诗","c":["宿云晦城阙，晓雨生微凉。","绿缛草木润，清虚尘土香。","宇宙暂扫除，胸襟豁轩昂。","忽如沉痾去，飘若凌风翔。","适物能须几，执热每相望。","永愧江上翁，终岁浮沧浪。"]},{"t":"苦热登楼","f":"五言古诗","c":["高楼亦炎蒸，况乃楼之下。","念彼生民微，累累尽蜗舍。","上天无清风，何以逃永夏。","顾余更缊蠖，眇然用悲吒。","火流暑当反，日暝天欲夜。","我躬且自阅，于此犹閒暇。"]},{"t":"秋热","f":"五言古诗","c":["蒸暑淹南国，季秋如长夏。","炎凉乱平分，天地错常化。","短日回朱光，六龙顿其驾。","暵似山泽焚，惮我如不暇。","反思岁聿暮，却顾旦辄夜。","宁忍窥昆虫，干时事矜诧。"]},{"t":"夏夜月中","f":"五言古诗","c":["静夜收众响，南轩卧虚寂。","繁星粲文具，初月悬星璧。","流萤急自照，露华重已滴。","鬼神颇虚无，触事生惨戚。","儿童戏相惊，庭有玄冠客。","夜久待不来，微风动松柏。"]},{"t":"苦热","f":"五言古诗","c":["生长自吴会，北游逾十期。","来还遂衰老，衰老何用知。","六月江湖间，烦炎若蒸炊。","畴昔不惮暑，今者殊畏之。","纤絺置如仇，羽扇常自随。","对案不得餐，脍炙成蒺藜。","忆我童稚岁，烈日犹奔驰。","斗草出百品，承蜩睨乔枝。","涧颜不待濯，流汗始为嬉。","自怜筋力便，岂谓天序移。","往闻终南间，盛夏含冰澌。","将家就高寒，长与卑湿辞。"]},{"t":"酷热","f":"五言古诗","c":["坚冰念阳和，广莫思柔风。","天事有驯致，星火俄复中。","飞乌炎千里，羲叔顿六龙。","焚林堕翱翔，沸鼎愁噞喁。","路傍在家田，伛偻头白翁。","恶木不得息，百亩为己功。","如何富贵人，方借明光宫。"]},{"t":"秋热","f":"五言古诗","c":["百里异风土，我行岂蛮越。","中星正常象，未与京洛别。","肃霜乃温风，授衣甫絺葛。","林蜩沸如羹，芳草香未歇。","天令不可推，有时倒生杀。","九土皆若然，蒸灼何由豁。","忆昔过秦陇，连山看秋雪。","阴风鸿雁号，积冻松桧折。","驱车渡河洛，反顾尚明灭。","大笑咫尺途，居然异寒热。"]},{"t":"次韵以道月中作","f":"五言古诗","c":["月从海底出，素景天外来。","解道千里共，斯人安在哉。","洞庭木叶脱，未央帘幕开。","颢气彻霄汉，炯炯不受埃。","群居笑李白，独与影裴回。","愿言常相亲，无使手停杯。"]},{"t":"和孙少述雪","f":"五言古诗","c":["同云晦天地，浩然自生明。","萧条乔木风，断续过雁声。","袁公卧深巷，意得神亦清。","岂知长沙客，漂泊万里行。","饿隐贱禄仕，乃见终古情。"]},{"t":"别黄子温","f":"五言古诗","c":["田园不遇岁，羁旅常苦心。","问君长沙客，几年东武吟。","白发映青春，天涯一相寻。","伤弓双折羽，迟暮多哀音。","平原客如市，珠履玳瑁簪。","担簦义何勇，归袖赢黄金。","世事不足道，丈夫多陆沈。","何以慰别离，春酒方献斟。"]},{"t":"别王深甫","f":"五言古诗","c":["四海不易遇，各自东西人。","那知汝颍间，三岁为比邻。","爱君故清真，有以敦薄鄙。","亦作酒客难，调笑鸱夷子。","一旬辄携手，曷日不寄声。","相期此胸中，无若平生情。","士贫非农商，敢惮抱关役。","经术又不如，空愧上书客。","飞鸿羁旅怀，流水离别心。","长因东南风，一冀子徽音。"]},{"t":"与孙巨源苏子瞻刘莘老广陵相遇苏请赋诗为别各用其字为韵每篇十韵 其一","f":"五言古诗","c":["都城每过从，车马动逾众。","分飞无此欢，会合杳如梦。","薄霜作微寒，浅水未成冻。","秋花正斓斑，幽鸟杂清哢。","此邦人事稠，南北屡迎送。","以兹信宿间，得与数君共。","遂将结吾庐，念有用馀俸。","稍营负郭田，毕力输赋贡。","百龄欲过半，来日颇自纵。","冀君数相存，诗酒尚足用。"]},{"t":"与孙巨源苏子瞻刘莘老广陵相遇苏请赋诗为别各用其字为韵每篇十韵 其二","f":"五言古诗","c":["本为东方生，避世不避喧。","仍慕管夷吾，畏事复畏言。","外物不可期，高风难重论。","我辞金马门，君来西掖垣。","淮濒一相见，握手双泪痕。","矜我鬓雪多，岁月何崩奔。","默然念既往，所遇皆笼樊。","恨不值羽人，拂衣入桃源。","腰间银青绶，车上朱两轓。","专城自不恶，相思徒种萱。"]},{"t":"与孙巨源苏子瞻刘莘老广陵相遇苏请赋诗为别各用其字为韵每篇十韵 其三","f":"五言古诗","c":["因言浙江潮，忆上吴山尖。","八月天地空，千里澄圆蟾。","海水为群飞，迅雷发幽潜。","壮士怀惴栗，怯夫窃窥瞻。","春风潮水平，青玉开镜奁。","轻舟载花女，翠发腰纤纤。","胜事冠东南，君行独能兼。","吾以狂自名，将老无所嫌。","会当从君游，不计岁月淹。","鲙鱼必令鲜，酿酒勿使甜。"]},{"t":"与孙巨源苏子瞻刘莘老广陵相遇苏请赋诗为别各用其字为韵每篇十韵 其四","f":"五言古诗","c":["嗷嗷南飞鸿，羽翼何莘莘。","哀鸣衡山阳，落影湘水滨。","岁晏道路长，雪霜多苦辛。","岂无稻粱谋，毕弋如鱼鳞。","此雁欲谁比，正若羁旅人。","古来瘴疠地，常有忠直臣。","扁舟慎自将，勿重蛟鼍嗔。","鵩鸟恶似鸮，端能伺承尘。","东风发众芳，宿莽熙阳春。","雁归君未归，怅望汀洲蘋。"]},{"t":"季孙肥","f":"五言古诗","c":["季孙事颛臾，祸起萧墙内。","秦皇筑长城，灭国乃胡亥。","蒙公不正谏，地脉岂其罪。","战国尚权谋，阿谀彼何怪。","亲为圣人徒，鄙陋曾莫解。","龟玉毁椟中，危颠竟谁赖。","鸣鼓讵可攻，菹醢死无悔。"]},{"t":"约谢师直出猎师直小疾不行作诗戏之","f":"五言古诗","c":["雪后原野空，风高弓矢劲。","岁时有阴杀，自古顺天令。","跃马径丰草，呼鹰下空夐。","烈火生鼻端，割鲜矧馀兴。","此亦壮夫乐，不与儿女并。","苦无枚叔辨，试起夫子病。"]},{"t":"观猎","f":"五言古诗","c":["立冬杀气凝，清霜会晨朝。","涤涤原野空，烈烈荆棘烧。","鹰饥肯为用，马寒意逾骄。","旌旗带林莽，笳吹含风飙。","突围狡兽怒，得隽壮士嚣。","老狐屈变诈，文雉输英翘。","讨伐顺天时，未许穷奸妖。","翩翩马上儿，弓箭各在腰。","意矜百战雄，巧斗更相招。","控弦落明月，飞镝来九霄。","虽虐终无伤，为乐固已饶。","晚临清汝滨，寒水如落潮。","挥壶酌美酒，醉归遗皂貂。"]},{"t":"杂咏四首 其一","f":"五言古诗","c":["众树日改色，凉风下萧森。","乔柯无定枝，存叶非旧阴。","白露变凝霜，百芳从此侵。","代谢不暂稽，盛衰理相寻。","悬虫自包藏，弃巢绝来禽。","徘徊苍苔地，万籁成哀音。"]},{"t":"杂咏四首 其二","f":"五言律诗","c":["短日不能永，月华代扬辉。","暝暗来四隅，稍复清影随。","迢迢河汉章，天毕前南箕。","簸扬蹇无成，掩兔今亦时。"]},{"t":"杂咏四首 其三","f":"五言律诗","c":["苍苍城隅草，地势元有在。","凉风西北来，摇扤色已坏。","天运正消杀，高明彼先罪。","安见中国葵，浅智亦足赖。"]},{"t":"杂咏四首 其四","f":"五言古诗","c":["疾风吼篱端，啸呼随叱吸。","翻翻走地叶，衮衮强相及。","重门忽开扉，蟋蟀如有入。","飞蓬自无根，邂逅暂相集。","万生共冯寓，智愚因妄执。","区区古今士，陈迹更缀缉。","是非竟何常，得一已漏十。","岁晏莽无成，白头抱书泣。"]},{"t":"广陵蒋生死十四年尸犹温有妻子存尝有书自远与其家","f":"五言律诗","c":["三径积荒草，玉棺不上天。","初疑青竹葬，有值吴门仙。","妻子同脱屣，衣冠如蜕蝉。","何年独鹤归，悲歌城市迁。"]},{"t":"曹司封诗","f":"五言古诗","c":["自我胜冠带，日闻乡党议。","意嫌风俗衰，长老俱喻利。","缅怀千岁士，未谓今昔替。","果哉曹大夫，高度跨一世。","人皆竞锥刀，趋走候形势。","强能弋公侯，弱或丐奴婢。","而公独长往，亦岂恶富贵。","顾当拯颓波，且以伸吾义。","昔在天圣中，太后犹称制。","桓桓谏议公，正色风宪地。","王室依老臣，萧墙屏奸计。","一麾竟谪守，褒赠身后事。","至今诵遗烈，每雪义士涕。","天伦见霜标，粲粲真难弟。","大雅贵老成，春秋有凡例。","吾将编野史，著述二公志。","直清先伯夷，退静后季次。","愿为得者规，不使达者愧。"]},{"t":"骤雨","f":"五言律诗","c":["山川近淮秀，风雨向秋急。","初为空旷游，顿喜清凉集。","鸣蝉断复续，沙鸟飞还立。","平生耽胜事，未暮俱可及。"]},{"t":"驰道","f":"五言律诗","c":["秦皇侈心极，登眺穷阻修。","言从峡中度，复欲沧海游。","车辙去不反，驰道缺每留。","君看鼎湖人，尚畏轩辕邱。"]},{"t":"树下","f":"五言古诗","c":["百芳与春违，嘉树成密叶。","上枝下相副，朝影暮还接。","徐风气清凉，重露香浥裛。","关关变鸣禽，杳杳飞孤蝶。","神仙彼何有，静境我心惬。","万期犹视荫，寸景疑度劫。","何用窥蟠桃，沧溟惮舟楫。"]},{"t":"过荐福寺","f":"五言律诗","c":["下马乔树阴，雪霜寒未晞。","重门开相当，广殿晴日晖。","问僧亦何事，荷锄殊未归。","劳生每多役，向此情依依。"]},{"t":"分题李花得香字","f":"五言律诗","c":["寻幽兴不浅，佳木稍已芳。","积雪春未融，明玉仍自香。","赤日照未好，会待清月光。","念无琼玖报，聊复进雕觞。"]},{"t":"夏雨","f":"五言律诗","c":["邑居苦嚣尘，洒扫长不给。","萧条一雨馀，草木遍青湿。","静无浮埃生，清有凉风入。","愧惭天地功，人力那能及。"]},{"t":"马死答刘先之","f":"五言律诗","c":["马恶忧败群，马死遂徒步。","始知恶有用，但愧非善御。","未能弃山野，不得事篮舆。","犹当谋款段，尚取州里誉。"]},{"t":"顾亭林","f":"五言律诗","c":["逝者如去水，贤达无复居。","朅来顾亭下，但见林木疏。","鱼鸟乐深渊，风烟迷旧墟。","徒幸百世名，历历存绪馀。"]},{"t":"齐鲁","f":"五言古诗","c":["齐鲁大儒师，专门盛章句。","应物非己长，何以责成务。","乃其忠孝心，足以事君父。","不如商利徒，反道趋诡遇。","剥床以及肤，泉货山岳聚。","赐金称百斤，封邑成千户。","若无天事变，岂不厚且固。","商鞅既诛夷，桑羊亦刀锯。","寄言逢掖人，施施幸安步。"]},{"t":"淮上","f":"五言古诗","c":["旦起风颇凉，暑薄意弥惬。","长淮波浪高，咫尺不得涉。","舣舟望连山，青霭乱云叶。","鸥鸟去杳然，空迥晨光接。","卧吟新诗句，閒理旧书帖。","呼儿饲茭茨，看妇治箱箧。","为非急时者，无事用轻楫。","淹留既无闷，何必歌长铗。"]},{"t":"次韵苏子瞻","f":"五言古诗","c":["顾侯磊落人，称是腰腹伟。","不甘封侯相，蔡父誇小史。","功名保唾掌，怀宝岂能已。","鞅掌人所难，见之心独喜。","邺中贵史公，秦谚推樗里。","一蒉障九州，亦自其名美。","金城上方略，万里可寸纸。","顶踵禹墨间，挂冠复遗履。","苏公相知心，乃在汤汤水。","抑扬磕然笑，吾心嘲里耳。"]},{"t":"次韵孙少述二首 其一","f":"五言古诗","c":["蓺苗欲其实，种椒欲其繁。","我本正礼家，世人称二难。","学射庾公斯，取友念必端。","相与今白首，交通可以完。","羡君脱尘垢，顾己羞素餐。","聊为鹏鴳飞，各自天宇宽。","一月三寄诗，一诗千百观。","恍若从君游，君知我心欢。"]},{"t":"次韵孙少述二首 其二","f":"五言古诗","c":["为贫始愿仕，逢辰叨典州。","朴直守故学，迟暮悲旧游。","此邦诗书林，处士原宪俦。","怪我何所为，千骑居上头。","君恩重泰山，未有毫发酬。","远惭遂初赋，清节第一流。","桑榆不相遗，欢笑脱羁愁。"]},{"t":"喜王大自固陵归","f":"五言古诗","c":["日月疾过隙，生者犹行客。","念君于此中，复久事远役。","岁暮山林闭，天寒雪霜积。","归来道路勤，稍见车马色。","田事未宜缓，春冰行解释。","相从今其时，迨此役车息。"]},{"t":"畏途","f":"五言律诗","c":["畏途十杀一，昧者已知戒。","奔航失维楫，将恐亦同败。","凝冰难长清，甘醴复先坏。","桔槔独知道，俯仰非有罪。"]},{"t":"椿下独坐","f":"五言古诗","c":["凯风长群物，赤日流正阳。","幽居似嚣烦，嘉树亦阴凉。","偶坐方丈间，吾非厌华堂。","爱此真不材，保彼千载长。","仰视龙蛇形，屈蟠正苍苍。","忽疑翠羽葆，何以居我傍。","吾闻高盖人，专宠来百殃。","我独安隐幽，入鸟不乱行。"]},{"t":"结庐","f":"五言古诗","c":["结庐东城下，适当车马路。","开门阅过客，扰扰不知数。","客或为我欢，客或不我顾。","欢我我不惊，去我我不慕。","俛仰各异怀，音容暂逢迕。","照影清水中，默然不相语。","魂交夕梦间，昔昔已复寤。","薄厚何从生，善恶非有素。","寄语朝市人，知余养生趣。"]},{"t":"后浦望水","f":"五言古诗","c":["春塘见游鱼，芳草宜白鹭。","溪流定几曲，花发应深处。","重来畏已迷，坚坐不能去。"]},{"t":"奉和宽叔新桥之什","f":"五言古诗","c":["昔贤常夺鬲，彼圣犹伐树。","物情喜崎倾，直道每龃龉。","况兹浑浑川，翻覆不可据。","风波一生忧，忠信多逢怒。","阴虹架层云，雨气生寒冱。","操舟虽云神，失势嗟已屡。","早师漆园学，一悟南华趣。","理会定无闷，神全谅何惧。","吾道乘桴浮，斯文以筏喻。","仰止金玉章，涣然谢烦虑。"]},{"t":"晚泊长芦赠南来邻船","f":"五言古诗","c":["沿溯同一川，风波情岂别。","维舟暂相从，销忧自怡悦。","明发南北飞，离怀更秦越。"]},{"t":"苦寒","f":"五言古诗","c":["不敢怨云雾，不敢悲雪霜。","此是上帝令，所以诛愆阳。","不见李与桃，前日胡为芳。","不见蚊与穥，往日胡为翔。","反时固为妖，徼倖真不祥。","但令冷气除，岂敢虞冻僵。","吾道不终穷，君看松与篁。"]},{"t":"赏心亭","f":"五言古诗","c":["高堂面虚无，水色照群有。","不知归流永，但见来帆久。","苍翠前后山，起伏龙蛇走。","荒芜六朝旧，独此存不朽。","凉风西北至，萧飒惊户牖。","秋意倏已高，玄蝉嘒衰柳。","主人厚宾客，嘉赠随所取。","爽豁破萦纡，高凉谢尘垢。","开筵穷日影，玉斗湛清酒。","长歌激梁尘，烂醉颇无负。","羁游屡飘荡，攀援每迟后。","数公倾盖欢，夙昔故未偶。","夜阑天正黑，出户揽星斗。","明发复殊方，行行但回首。"]},{"t":"汴渠挂帆","f":"五言古诗","c":["翩翩河中舟，一一西上水。","彼船力有馀，我船力无几。","力薄日一舍，力壮日百里。","迟速讵几何，推分故尔耳。","今晨东南风，帆席频轻驶。","舳舻密相衔，前后略相似。","如将平不平，颇复令人喜。","因之念时事，冥寞付天理。"]},{"t":"寄韩持国","f":"五言古诗","c":["帝都冠盖区，百吏鲜閒暇。","学省独优游，儒冠足休假。","腊前辱飞书，雨后果迂驾。","远道靡告劳，心期莫予诈。","三年坐穷山，物色多可讶。","鹤林失昭师，演门吊两谢。","素交怅倾盖，陈迹空怛化。","孤吟不逢人，默坐常逢夜。","朱丹亲簿领，虫旱视禾稼。","全人犹瓮盎，薄赋兼倓幏。","君来慰何多，高论听虽乍。","雄风快披襟，佳境逾啖蔗。","从容外形骸，约略陈酒䏑。","寻芳问名园，临溪陟累榭。","数称滍阳叟，谓实庞公亚。","昔闻固已多，今得逾可诧。","龙门走清洛，伊水共东下。","旧都富形势，时卉芬兰麝。","云峰会深入，芳草正可藉。","乘兴宁有穷，归马何当跨。","小官畏绳墨，局蹐甚缰靶。","苟无咫尺书，限此十数舍。","举头怨鸿鹄，羽翼不我借。","终更行有期，屈指计秋夏。"]},{"t":"寄王深甫兄弟","f":"五言古诗","c":["曹子三败辱，卞和再刖悲。","自古鲜其然，今子何似之。","历块误一蹶，千里差毫釐。","白璧固有瑕，黄金岂无疵。","识君向十年，每叹时尔遗。","天命兹可信，古学滋可疑。","上书欲荐君，身贱不得为。","寄君北门诗，相望空所思。"]},{"t":"寄王子直 其一","f":"五言古诗","c":["三见登贤书，每有千人进。","少年盛名声，高士离幽遁。","吾怜王子秀，屡黜曾不近。","栖迟困家食，屈首仕州郡。","始疑造物意，实于才者吝。","宁与朝廷分，不使山野尽。","间令特达士，竭力事推引。","知音与汇征，千岁名双振。","忆君盛文华，遇事尤精敏。","雷电腾火车，波涛驾蛟蜃。","譬之逢羿射，所发无不准。","固穷当益坚，达生尚无闷。","府公枢轴老，治道常坐论。","屡闻下榻迎，岂惟虚己问。","人生贵意气，感激多发愤。","想见吐胸中，江河出方寸。","便当荐书上，累鸷推孤隼。","咫尺青冥天，励翼见翔奋。","年华不吾与，二毛倏生鬓。","禄仕久益贫，拙谋老仍钝。","干时尚有违，得名谅无分。","行当鸿鹄举，判与麋鹿浑。","江鱼事钩罩，吴稻收囷囤。","君时据亨衢，寄声勿招隐。"]},{"t":"寄王子直 其二","f":"五言古诗","c":["决意千里游，极当何日归。","终朝仍闭关，室迩人竟违。","北风吹长空，弱羽相分飞。","我呼君应闻，何意音问希。","介者当鲜合，俗士所见非。","会知相忆深，不为轻与肥。"]},{"t":"寄王深甫","f":"五言古诗","c":["昔居沈邱门，相过不盈里。","蓬蒿启三径，杖履通彼此。","去颍已数年，居常梦湖水。","陋巷君所安，所居未宜徙。","忆昨春风时，君手种桃李。","二年当著花，今秋应结子。","同生记五人，次卿今禄仕。","馀人皆及冠，谁最饱书史。","娟娟怀中儿，长女久生齿。","侁侁乳下秀，相继今有几。","固陵好田园，往岁未疆理。","菑畬无废功，计程万亿秭。","曩时豫君谋，家事最纲纪。","欲令囊有钱，更使囷馀米。","伏腊足自了，衣食常好美。","自兹谢俗徒，闭门唯隐几。","岂论陶朱公，未慕子贡氏。","有志惧难合，到今可谁比。","将无尚瓢箪，幸不乏甘旨。","南风素轻浮，众口巧排诋。","往闻里中儿，责望多苛礼。","君从段干迫，讵免叔孙毁。","又闻泽宫射，吾子时见罢。","有言厌尘劳，自誓不再起。","穷通非异门，出处皆一体。","达生知顺天，偏智乃私己。","怪君未坦然，尚尔交忧喜。","昨来赦书下，拔滞先贤士。","宁令有道卷，近自吾人始。","丈夫龙蛇变，盖棺事乃已。","探穴必得虎，叱枭会胜雉。","何能守一方，寂寥事行苇。","吾为诸侯客，正得戎曼鄙。","簿书每陈前，弦诵不到耳。","时方尚鸿鹄，自愧杂蝼蚁。","匠石悲运斤，郢人怨流徵。","非君美无度，孰与裁狂斐。","思身若烦酲，淟涊不可洗。","弯弓辄堕雁，投竿常获鲤。","寄书非无缘，勿爱缯与纸。"]},{"t":"寄王子直","f":"五言古诗","c":["王孙意气壮，文武两自适。","著书轻古人，时论有马癖。","尘埃间何阔，陋巷稀轶迹。","西郊秋欲分，风露朝暮积。","岂惟弓矢劲，况乃鹰隼击。","何当共驰骋，一见万夫敌。"]},{"t":"寄原甫","f":"五言古诗","c":["鸡鸣行问津，日昃未得休。","高山有悬车，深水时泛舟。","二殽避风雨，太华行清秋。","旅游月魄毁，始觉岐路修。","缅然望西南，落日荒维陬。","应知念行役，天中时倚楼。"]},{"t":"寄王掾","f":"五言古诗","c":["壮齿行九州，智当任百忧。","常慕马将军，又怜定远侯。","汩汩州郡役，奔走无停留。","朝与簿书期，暮从农夫游。","尽力蒿艾间，令人愧前筹。","会计与牛羊，古来悲孔丘。","王卿与我同，岁晏方田畴。","乌攫道傍肉，貂馀身上裘。","西风木叶零，清雨天地秋。","归来共尊酒，欢言役车休。"]},{"t":"寄王深甫","f":"五言古诗","c":["昔有扬子云，著书恬势利。","家贫官不达，宾客罕肯至。","时复好书者，相从问经义。","千载故寥寥，吾人一何似。","天凉风雨馀，草树有秋意。","蝉吟燕辞归，穷士易失志。","陋巷可相期，箪瓢固多味。"]},{"t":"寻王深甫值其不在归寄此诗","f":"五言古诗","c":["几日欲出门，适此天和柔。","邦人皆异情，我忆从君游。","僻居正穷巷，冰水相交流。","旁舍代应问，檐鸟声啁啾。","士贫难自高，柴水劳深谋。","昂藏尘世间，何异川上鸥。","我能乘兴来，不能兴尽留。","清谈无由接，竟夕心悠悠。"]},{"t":"寄王深甫","f":"五言古诗","c":["公绰志不欲，滕薛非所居。","黄香脱枳栖，仍集东观书。","艅艎不挹浆，鹰隼非捕鱼。","狐裘匪负薪，鼎鬲宁柱车。","物生各有宜，得志皆自如。","违方易故常，操末缪续初。","古贤贵相知，末俗随毁誉。","怀君乏羽翰，临风一踌躇。"]},{"t":"之官汝州舟中作寄都下","f":"五言古诗","c":["浅智惮远谋，弱力量所任。","进途远朝廷，退迹违山林。","代耕抱微愿，儋石安素心。","小官慕既往，有道念在今。","问津自南郭，治舟溯清浔。","鼎鼎去乡悲，冷冷游子吟。","凌风卷晴绿，乔木庇高阴。","黄鸟相喧呼，嘉鱼一浮沉。","晨昏偶素月，信宿在青岑。","所遇多可欢，离念颇用侵。","嵯峨天门高，浩荡瀛海深。","髦士相提衡，精义穷幽寻。","顾余倾盖交，问我瑶华音。","戒车辱祖道，赠策怅分襟。","简书甫祗畏，僻陋方滞淫。","摇怀日三秋，寄情望归禽。"]},{"t":"早春怀都下","f":"五言古诗","c":["沈滞幕府官，三见春华换。","早闻知命言，岂敢窃自叹。","樗老谢彫刻，铅钝缪锤锻。","幸兹省文书，聊以骑款段。","乡闾越南北，弟侄稍婚冠。","蔼蔼西掖垣，哲兄秉天翰。","悠悠思者怀，历历念可看。","仰视归飞鸿，何当为我伴。"]},{"t":"瓜步","f":"五言古诗","c":["苍苍林表山，下惟瓜步水。","忆昔魏皇帝，百万尝驻此。","饮马江水浑，扬旌朔风起。","经营竟无成，叹咤有遗耻。","去去常畏人，闵默垂五纪。","大江限南北，天意固偶尔。","奈何奸雄才，割据争虎视。","不有神武功，畴能混书轨。","吾闻清流战，王业实基始。","楼船蔽空来，天堑才一苇。","此时东流波，不足投马箠。","煌煌轩台威，凛凛向千祀。"]},{"t":"寄老庵","f":"五言古诗","c":["兹山韫奇胜，四野穷眺览。","近峰擢矛剑，远巘矗莲萏。","云霞发光彩，气候变舒惨。","啼禽不能名，秀芳多可揽。","招提就丘壑，初地首铅椠。","精庐烂金碧，净供欢藜糁。","佛香昼绵绵，法鼓晨紞紞。","林风忽飘摇，天乐随簸撼。","灵泉初发蒙，温液遂盈坎。","异源判炎凉，及物万尘黕。","西南江路永，水墨画色淡。","沤鸟破青冥，帆樯出葭菼。","吾人事探讨，绝境更平澹。","悟真心自知，得隽首独颔。","剪茅地夷爽，筑基土强鹍。","长松启门扃，怪石列窊窞。","遂初本逍遥，知略贵刚敢。","颓龄惜鬓发，壮节露肝胆。","由来抱轩昂，岂复甘黯黮。","辞满异多秩，掺袪嗟不寁。","高风故难继，弱质因自感。","涧肩疲负任，勿药羞是鞓。","愿言尔为邻，宁使我馀憾。","即今桑榆景，光翳将就晻。"]},{"t":"潼关","f":"五言古诗","c":["上有苍苍山，下有浑浑流。","两崖类筑甬，中道才容辀。","关门密相望，设险非一秋。","借问前代人，屈指嬴与刘。","乃知伯王功，天险参人谋。","百二制六国，一面当诸侯。","东惭洛阳薄，北视朝歌羞。","时平郡国通，官守轻戈矛。","旅程兹出关，怅然为淹留。"]},{"t":"汜水关","f":"五言古诗","c":["四山环若屏，土色类坚石。","青冥积霭间，古径漏天隙。","虎牢一何险，飞鸟不可历。","狭处乃容车，天形正修白。","山行十里尽，路与洪河直。","惊波走狂沙，澒洞踏虚壁。","寒光著面目，噤蘖避剑戟。","殷然出地雷，下与千仞鬲。","壮哉造化功，置此限南北。","乃知巢居民，老死皆异域。","帝鸿始舟车，夏禹勤底绩。","轮蹄日相寻，隘路遂开坼。","因缘楚汉交，英雄因智力。","杀人何其悲，贻患实自昔。","西风卷零雨，昏雾白日匿。","泥涂未遽央，客子怨行役。"]},{"t":"春日凉榭寄戴大临","f":"五言律诗","c":["老去苦无悰，春还暂真赏。","念无俗虑侵，得以山林往。","寻幽喜人远，习静憎禽响。","东风日暄和，触事全胜尚。"]},{"t":"晚步寄徐从道","f":"五言古诗","c":["日夕兴颇适，逍遥步城隅。","连峰苍翠间，决沟见平湖。","鸟去一何逸，白云与之俱。","太虚自无碍，真意宁有拘。","春华白蔼蔼，欣欣动群枯。","园畦亦成趣，嫩绿荣寒蔬。","思君昨相语，水木西山居。","况此天气新，田野多欢娱。","注想已自尔，念归定何如。"]},{"t":"秋园","f":"五言古诗","c":["夕阳下西山，反照林杪赤。","初惊秋事早，远见霜叶色。","山林得吾心，消散理轻策。","翠香袭晚秀，柔紫拾新坼。","凉蝉时一声，栖鸟相敛翼。","还归卧南檐，初月照虚碧。"]},{"t":"寄王固子坚时在固陵治田","f":"五言古诗","c":["苏秦六国相，晚被谗慝名。","使有东郊田，安得留此声。","古今事可知，达人尽躬耕。","多君家事治，竭力从老农。","白水负郭田，百顷亩一钟。","耕亦勿卤莽，耘亦无灭裂。","秋成霜满畦，玉粒胜白雪。","我怀沮溺心，早晚从君游。","且当学林类，行歌复披裘。"]},{"t":"陆瑁养鱼池","f":"五言律诗","c":["何兹水乡士，尚复穿池居。","宁知湖上龙，不是渊中鱼。","漪澜杳无际，绿净望有馀。","寂寞垂竿叟，啸歌方岁除。"]},{"t":"自舒城南至九并并舒河行水竹甚有佳致马上成五首 其一","f":"五言律诗","c":["升曦上南山，千峰云碧明。","晨风激寒水，琴瑟环佩声。","蚕老桑柘空，麦熟黄鹂鸣。","浩然田野兴，遂尔忘都城。"]},{"t":"自舒城南至九并并舒河行水竹甚有佳致马上成五首 其二","f":"五言律诗","c":["高高嘉树阴，下下修竹林。","水光摇日影，人语乱鸟吟。","兴适尽佳境，有逢皆会心。","安知道路傍，前更登嵚岑。"]},{"t":"自舒城南至九并并舒河行水竹甚有佳致马上成五首 其三","f":"五言律诗","c":["一溪分百泉，一泉流十家。","恶竹莽连云，古树横带沙。","鱼子戏稻秧，凫雏唼荇花。","信美非故乡，无由寄生涯。"]},{"t":"自舒城南至九并并舒河行水竹甚有佳致马上成五首 其四","f":"五言律诗","c":["溪水转山曲，杳如天际流。","浅濑不解衣，浮查曰为舟。","惜无同心子，此地聊淹留。","但爱溪上儿，蓬头坐垂钩。"]},{"t":"自舒城南至九并并舒河行水竹甚有佳致马上成五首 其五","f":"五言律诗","c":["南山近仙居，太古馀积雪。","阴云五月寒，松桧为之折。","如何车马客，尘土倦炎热。","挥手谢世人，吾将与君绝。"]},{"t":"自曹还都舟中奉酬子中见寄","f":"五言古诗","c":["结束溯都门，欢言瞻上东。","宿舂不成装，徒御殊匆匆。","倾城千万人，髫稚随老翁。","揽袪强我留，路隘马不通。","志微术无多，举动非材雄。","畦隧不知拙，雕朽宁谓工。","尚怜畎亩民，欲使衣食充。","吏课才第六，名品出下中。","岂期此邦人，念我如豳风。","竟惭不赫赫，用底书成功。","人事非有常，物变何必终。","移是趣日新，应谐犹不穷。","耻为坚白辩，判别僻与衷。","由是知命来，但觉心源空。","思君天材异，汗血流骠骢。","定交既非晚，接武昆瀛蓬。","岁月使人惊，冠带昔儿童。","别离过三秋，会合今复同。","新诗思何深，清月醒困蒙。","相哀蹇无成，为客谢诸公。"]},{"t":"奉酬孙少述","f":"五言古诗","c":["意合非有求，道远义弥敦。","诗书获我心，将老遂不谖。","颓龄若驰波，哀逝稍不存。","念君税馵羁，饮水栖衡门。","正容悟失道，已矣将何言。"]},{"t":"还家","f":"五言古诗","c":["久客常念归，还家自深愿。","虽非湖海游，早已时节变。","果裸施于宇，蟏蛸巧相衒。","墙根思哀蛩，危栋辞归燕。","贫加乡闾慕，病益儿女恋。","栖迟免路旁，未厌茅屋贱。","衡门过凉雨，秋草盈芳甸。","耕耘傥及时，筋力自此劝。"]},{"t":"雪中检故书见王深甫书因寄","f":"五言古诗","c":["积雪閟穷巷，天寒四岑寂。","常时能来人，今兹亦绝迹。","探囊理文书，卷轴浩堆积。","岁序往不留，其人或成昔。","忽如二三子，共此笑言适。","我游皆可人，回也实莫逆。","诗句何轩轩，有若风中翼。","使我多闻知，令我手不释。","闻君不作官，作官固无益。","由来全生士，不以时世激。","请问紫芝翁，宁知五鼎食。","开门望四野，天地漫无隙。","老鹰冻不飞，何由寄消息。"]},{"t":"送张七和州判官","f":"词","c":["从仕如博弈，百万系一掷。","君看大司马，二十好颜色。","与子昔献赋，共登东堂籍。","留滞向十年，尚为诸侯客。","我愚数亦奇，连蹇不自惜。","念君复何为，无乃玄尚白。","时平弃奇节，幕府鲜筹画。","譬如埘?间，安用鸾鹄翼。","高秋江湖深，莽莽烟水碧。","轻舟犯蛟鼍，勉子慎行役。"]},{"t":"三女冈","f":"五言律诗","c":["吴女飞若烟，兹地留尔名。","上有愁云阴，下有蔓草生。","如此粲者何，遗恨若未平。","宁无东平树，靡靡向孤城。"]},{"t":"澄心寺后阁弹琴","f":"五言古诗","c":["高风动长松，萧瑟清我心。","亦有琴上弦，尽得天外音。","试复向城市，馀响终难寻。"]},{"t":"首春学省同舍十一人集王彦祖为主人人赋十韵得河字","f":"五言古诗","c":["意远智无涯，乐少忧常多。","浮生共兹理，达士默谓何。","岁月如奔车，冰霜变阳和。","废书独长叹，倚席仍浩歌。","王子家千金，世勋誓山河。","敕厨具丰羞，载酒信所过。","重帘筛劲风，暖日苏庭柯。","左手持蟹螯，一釂朱颜酡。"]},{"t":"养鱼","f":"五言古诗","c":["知此升斗狭，鳣鲟非所容。","安知庖所捐，后不成蛟龙。","为尔释囚拘，置之清泠中。","不有网罟忧，安见拯济功。","掉尾一何欢，馀困犹噞喁。","孰云我非鱼，正见所乐同。"]},{"t":"小雨","f":"五言古诗","c":["十日无油云，一春无奔雷。","天事不可知，号令于此颓。","疾风生梁栋，宇宙如沈灰。","惊霆万车走，激裂山石开。","此声昔未有，曩意非所猜。","况闻波涛音，汹汹千里来。","虽无为霖实，犹得驱黄埃。","终忧稻粱枯，所济蒿与莱。","蛟龙乐盘嬉，既往宁复回。","茫然怨云汉，赤日方徘徊。"]},{"t":"检覆郏城旱田示同官及寄河南诸贤","f":"五言古诗","c":["昔岁歉无年，今夏仍荐饥。","罢民去南亩，贱价捐东菑。","籍籍道路间，饿者何累累。","藜藿不充肠，苶然旄与倪。","嗟我禄代耕，每食为不怡。","徒怀仲由志，身贱那得施。","属城上民讼，比牒皆苦词。","奉诏实有无，百闻谢一窥。","星言说桑田，行与父老期。","触热不敢休，重趼宁告疲。","郊原赤如赭，秉穗无孑遗。","垦艺不可分，四旁生蒺藜。","流行诚代有，愚弱岂易欺。","附上亦有刑，残下罪攸司。","鄙夫不忍此，告吏咸赦之。","庶兹咻喔恩，足以苏茕嫠。","大农急经费，言利析毫釐。","二吾犹不足，一切宁谓宜。","国侨敏争承，郑邑用不危。","冯煖焚券书，田氏人若归。","区区二小邦，两士能若斯。","当官在必行，匪石安可移。","诸公悉吾友，此志良弗非。","当令徇路人，一听狂者诗。"]},{"t":"退朝","f":"五言古诗","c":["虑澹事从简，兴发谋岂豫。","退朝建礼门，走马长楸路。","阴风脱林槁，朝日破寒雾。","简书亦优游，宾友慰迟暮。","神仙未尝学，皋壤欣所慕。","静境出自然，胜游非浪聚。","杯觞谋须臾，肴蔌讯无虑。","赏音愧闻弦，和歌容执御。"]},{"t":"引泉诗睦州龙兴观老君院作","f":"五言古诗","c":["上嗣位六载，吾宗刺桐川。","余来拜旌戟，诏下之明年。","是时春三月，绕郭花蝉联。","岚盘百万髻，上插黄金钿。","授以道士馆，置榻于东偏。","满院声碧树，空堂形老仙。","本性乐凝澹，及来更慕玄。","焚香礼真像，盥手披灵编。","新定山角角，乌龙独巉然。","除非净晴日，不见苍崖连。","上有拿云峰，下有喷壑泉。","泉分数十派，落处皆琤潺。","寒声入烂醉，聒破西窗眠。","支筇起独寻，只在墙东边。","呼僮具畚锸，立凿莓苔穿。","灇淙一派堕，练带横斜牵。","乱石抛落落，寒流响溅溅。","狂奴七里濑，缩到疏楹前。","跳光泼半散，涌沫飞漩圆。","势束三峡拄，泻危孤磴悬。","会闻瑶池溜，亦灌朱草田。","凫伯弄翠蕊，鸾雏舞丹烟。","凌风捩桂舵，隔雾驰犀船。","况当玄元家，尝著道德篇。","上善可比水，斯文参五千。","精灵若在此，肯恶微波传。","不拟争滴沥，还应会沦涟。","出门后飞箭，合势浮青天。","必有学真子，鹿冠秋鹤颜。","如龙辅余志，日使疏其源。"]},{"t":"和原甫郓州乐郊诗","f":"五言古诗","c":["人事有背向，胜游不长绝。","闻公乐郊行，慷慨矜岁月。","东山翠屏秀，卢水寒玉直。","尚有昔来人，借问宁异昔。","菱蕖乱幽芳，梧竹凝茂阴。","始知秋意高，讵厌徂岁深。","因宜付乐妨，大巧当不为。","岛鱼皆自欢，贤者能勿违。","华堂庇深沉，皋壤极虚旷。","清池湛明辉，寒郊无近响。","公来会旌旆，公晏盛笳鼓。","鲁酒若醍醐，齐讴艳巴楚。","采芹自胥乐，食葚怀好音。","因成池上篇，为想思归吟。"]},{"t":"刘太尉庙","f":"五言古诗","c":["世乱争斗繁，废兴不可载。","磨灭几何人，独兹有馀爱。","空同气雄武，燕蓟风慷慨。","曾是鞍马间，而为治民最。","桐乡旧墟好，岘首遗碑在。","岁久梁栋倾，地荒松栝大。","古今犹过隙，俛仰成百代。","咨嗟畎亩勤，勋业非永赖。"]},{"t":"欲雨寄张壁","f":"五言古诗","c":["秋事亦已中，江南故炎溽。","北风三日雨，正气还凄肃。","身老虑深简，官閒睡常足。","庭阴堕长梧，园芳乱新菊。","借书喜未见，酿酒欣初熟。","优游谅卒岁，何用恨幽独。"]},{"t":"雨中寄子直","f":"五言古诗","c":["繁阴不时解，雨气如深秋。","朝衣始絺葛，暮服乃重裘。","天事亟变易，得为有常不。","如何世上士，欲以全自求。","行身绳墨间，蹜蹜空白头。","唯君可语此，意豪力且遒。","通衢虽泥涂，未至乘扁舟。","兴发骑马来，垫巾故风流。"]},{"t":"林都官种花","f":"五言古诗","c":["休迹异从告，退居乃靡禄。","劳心不治人，寓兴此嘉木。","客来启荆扉，侧砌纷众绿。","名存洛阳品，秀出海南族。","理会意必欢，谁能伤局促。","时当载酒过，三径成幽熟。"]},{"t":"作假山","f":"五言古诗","c":["幽意难具陈，静境可因就。","远求涧侧石，置彼窗中岫。","前为嵩华高，侧构衡霍秀。","岩崿倏天成，风烟若神授。","他时看图画，应接颇意究。","气色形似间，人人轻宇宙。","尝闻山林士，既往又不复。","此语我知之，衡茅非所陋。"]},{"t":"暑行 其一","f":"五言古诗","c":["憩马道傍舍，解衣仍伫立。","四檐庇阴凉，萧萧风气入。","虽云茅茨陋，枕簟亦自给。","已胜鞍马间，筋力苦倦急。","田野归去来，馀年犹可及。"]},{"t":"暑行 其二","f":"词","c":["赤日成畏途，相与逃热行。","中宵寝不安，两舍鸡初鸣。","据鞍寝梦间，堕策忽自惊。","官身跨官马，倦?奈有程。","愧负田野翁，安稳眠到明。"]},{"t":"伤胡二","f":"五言古诗","c":["古人虽千岁，我见如接迹。","今人虽比肩，我视犹异域。","乃知相知情，心识非貌识。","所以识胡君，不得同砚席。","今朝满衣泪，哭君寝门侧。"]},{"t":"伤逝二首 其一","f":"五言古诗","c":["去水不可还，逝者日已疏。","悲忧若沈痾，百药无能除。","英英韶华子，夭夭昔同车。","令德其芬芬，佩玉联琼琚。","舟移悼藏壑，天祝嗟愁予。","蕙兰秀不实，徒见荆棘墟。","含悽抚众稚，吊影还室庐。","高天杳茫茫，日月空居诸。"]},{"t":"伤逝二首 其二","f":"五言古诗","c":["我昔曾远游，岁晏不得返。","又尝惧而梦，百怪纷乱眼。","迨今疑若人，虚实未敢辨。","促驾逝将归，惊呼寤何晚。","百年非淹期，愚智俱不满。","彭聃与颜殇，究竟同是短。","愁忧浪无端，衷肠若汤涫。"]},{"t":"巢父井","f":"五言古诗","c":["访古慕高远，回首笑流俗。","千世得巢父，萧然慨遗躅。","古来知生民，满腹所愿足。","何为让天下，牛口信为辱。","高风渺不嗣，世态日局促。","至今西山翁，耻甘首阳粟。","爱此盈尺泉，百寻瑩寒玉。","迁陵复改邑，缺甃常湛绿。","君怀浮云志，尘埃兹可浴。","君有冰炭忧，清泠相为沃。","长涂接周楚，轩盖密相续。","能令贪夫廉，更使贤士勖。","岂如汉阴叟，抱瓮伤窘束。","我游阻胜概，长谣慰心曲。"]},{"t":"题李白祠","f":"五言古诗","c":["旧闻谪仙人，多以我为似。","三生去来今，惟独变名字。","泊舟姑熟溪，风月不如意。","举头望青山，酌酒聊一醉。","汉宫三十六，当时各自贵。","昭阳与华清，究竟谁为愧。","奴辈不自省，脱靴更谁避。","而令弃贤材，孤负青云器。"]},{"t":"宿蔡口","f":"五言古诗","c":["竟日鉴寒水，泊舟复新月。","浮光镜上下，空寂照毫发。","华星涌波际，人语自天末。","潜鱼跃相闻，去鸟飞渐没。","明生思虑尽，清入心源豁。","洗耳事诚非，濯缨情愈阔。"]},{"t":"立春","f":"五言古诗","c":["岁阴已暗去，春色复潜动。","嘉树欲芳华，归鸿杂清哢。","乾坤自长久，节物厌迎送。","浊酒欢我愁，浩歌为谁纵。","古人尽流水，世事皆宵梦。","白日少借留，青春亦公共。","举眼向高天，吾谋不能用。"]},{"t":"次韵和杨叔恬赠郑秘丞","f":"词","c":["纬萧弃明珠，龟手安絣漂。","浮生每殊涂，吹万亦异窍。","传剑不成显，谈舌无与掉。","圜冠岂误身，儒术真寡要。","岁时不我与，壮年更稚少。","白发绿鬓多，班班已盈照。","安排慕无闷，推命独孤笑。","趋愚甘就迂，遣累稍夷峭。","嵯峨天门开，事业寄周召。","登贤如弗及，得士故颇料。","乃知古犹今，孰有贺随吊。","寸善曾不遗，有功辄先调。","骅骝自西极，翠羽出丹徼。","黄钟陋巴歈，文鼎嗤畚筱。","况闻丘园秀，得以虚名钓。","唯忧有道卷，莫敢后时诮。","食苹鹿相呼，在鹤鸡群叫。","饭牛歌何哀，筑岩貌惟肖。","顾予乃迷方，黥劓谁与疗。","章甫期适越，风帆欲逾峤。","敦敦乐瓢箪，耿耿甚荧耀。","聊欢龟曳涂，犹畏牺入庙。","同声邈难期，僻陋常耳剽。","逢君独欣然，夙昔共明诏。","屡闻诸侯辟，复见尚书召。","奈何竟栖栖，尘土翳光曜。","西山悲采薇，鼎食归洒削。","飞将不得封，重侯付嫖姚。","新篇一何工，大巧全众妙。","上言道路勤，山海穷听眺。","次述畴昔游，弁髦迨冠醮。","下云厌屡空，藜藿甘咀嚼。","英贤困奇蹇，为善谁复劭。","譬如饮洪钟，伟量乃能釂。","郑公亦全材，大厦方䆗窱。","珉瑶谢尺璧，丝管让清啸。","同当鹄翻云，肯为鱼在?。","千里由咫尺，西城始春烧。","吾闻天祐贤，柞棫民所燎。","胡为沮溺俦，躬耕老蓬藋。"]},{"t":"寄刘道原秘丞","f":"五言古诗","c":["君家庐山南，云水当户庭。","丈人悬安车，鲵齿头发青。","吏隐粟三釜，翻书十二经。","胡然辞羁旅，大江急扬舲。","太史司马公，老成兼典刑。","周南叹留滞，武库森长扃。","叩关起九州，授简欢真詅。","自兹访都邑，乘兴及郊坰。","清洛湛寒玉，嵩高环翠屏。","宫观想旧躅，丛祠记遗铭。","俗物不挂眼，俚言谁载听。","毕事黄鹄举，翩然问长亭。","念昔始相从，子少予壮龄。","定交自倾盖，结好深鹡鸰。","放怀脱羁馵，高论穷杳冥。","纵博恣叱枭，极饮常虚瓶。","后会十五年，见子云龙廷。","官书职雠校，旧简同编硎。","瓠落无所容，柘弹缘蜻蜓。","河梁一分手，南北如漂萍。","岁月不肯留，瞬息无暂停。","跳丸指飞鸟，急雪看凋蓂。","壮怀益漫漫，衰鬓成星星。","劳生百年间，所恃七尺形。","从衰得老病，讵足称最灵。","而君复何为，疲苶非康宁。","目视乱白黑，奇疮出潜丁。","饮肠日以狭，永夜甘独醒。","南方多奇药，芝朮馀芳馨。","引年亦多术，何必非豨苓。","往昔志读书，苦心过聚萤。","期以怪幻闻，岂只辨文鼮。","斑白乃自悟，有为皆浊腥。","古来豪杰士，蒲卢祝螟蛉。","埋骨蒿艾间，鬼火犹青荧。","孰知出宇宙，浩荡浮沧溟。","翳昏照白日，幽蛰惊迅霆。","道心不可传，法语容亲聆。","怀君意无涯，永望几涕零。","寄书南飞鸿，矫矫双翅翎。"]},{"t":"送杨秘丞","f":"五言古诗","c":["结发仕明世，四十列朝籍。","汉庭殊多贤，向子每叹息。","羁旅间何阔，相逢头已白。","车马故匆匆，复为北州客。","萧条大河渚，疲瘵空城域。","思得爱人长，而君著吏迹。","去思常蔼然，所居不赫赫。","推此化百里，坐当致繁殖。","常服子路言，有志千乘国。","饥馑师旅馀，可使义且力。","由来骋骐骥，历险始尽识。","尚恨此中小，颇复拘绳墨。","太平进取难，子云尝执戟。","金张许史间，无所用奇策。","不如课农桑，弦歌树风绩。","无由之武城，赠诗慰相忆。"]},{"t":"题孙昌龄归来亭","f":"五言古诗","c":["丈人发如漆，筋力不知老。","七十置官归，时人以为早。","多公逍遥志，所向豁怀抱。","虽云容膝安，不减专城好。","忘机睨云水，寓兴植芳草。","世故不经听，尘轨从却扫。","壮子官瀛洲，济美擅词藻。","亲欢适为主，家事意承考。","古云陶渊明，避俗非达道。","息交以绝游，自处何枯槁。","公为乡先生，里邑每倾倒。","一言可镇浮，不啻千金宝。","宦游失门户，驽蹇悲栈皂。","祝身得如公，每食心再祷。"]},{"t":"寄题萧山岁寒堂直己亭","f":"五言古诗","c":["我兄昔高第，时论推捷敏。","由也政事科，五人实亲近。","古者邦诸侯，今之县令尹。","试材非不难，善政知所蕴。","投虚刃若新，利刜钟已泯。","遂驰能者声，肯作俗士窘。","高堂久颓挫，往者尝隐忍。","即事新栋梁，开轩凌隐嶙。","后凋拔天材，破的见标准。","山川濯襟尘，药饵纡客轸。","呜呼九州间，胜事岂有尽。","向观松桧姿，稍欲死蒿堇。","始知岩穴士，自古须汲引。","愿赋嘉树诗，为公广招隐。"]},{"t":"与亭","f":"五言古诗","c":["构亭彼为谁，高士自相与。","与游皆可人，与言是真语。","与醉不独醒，与歌从和汝。","与忘形骸迹，与偕同出处。","实与不待求，久与非强许。","世涂异冰炭，咫尺或龃龉。","开此与者风，宁当转弃予。"]},{"t":"次韵穆父送仲至使北","f":"五言古诗","c":["结束大使车，张旃理轻策。","八荒已信浮，万里无直责。","由来昆弟欢，庸非一日积。","冠带引弓民，长城限疆埸。","边人安昼眠，老不逢斗格。","将帅剽甲兵，褒衣垂韨縌。","金缯出王府，百万载书籍。","候馆如鱼鳞，相望交国客。","外门名家驹，长大俨且硕。","诵诗三百篇，岂减崔亭伯。","斯焉思无邪，群书矧探赜。","指掌幽冀州，左右皆阡陌。","皇华一何远，区脱为我役。","前驱弩在覢，郊候抹红额。","天声畅无外，不必关塞斥。","但看书同文，依然具点画。","夷羞珍湩酪，胡舞喧匏革。","猎围得狐兔，割鲜亦奚择。","儒生自古贵，忠信行蛮貊。","虽令博望侯，何敢轻逢掖。"]},{"t":"西都大内作","f":"五言古诗","c":["太紫异垂象，河洛殊出符。","卜食绵往祀，宅中雄别都。","旋宫千万门，层城十二衢。","佳丽帝王州，爽垲神明区。","过位思自饬，檐阙在必趋。","琉璃映瓦翼，玱琅耀金铺。","白日互蔽亏，凉风倏来苏。","仰视制作雄，疑有神物扶。","始知壮丽功，不使来世逾。","择材自千章，衒巧非一图。","傥无日新美，何以除规模。","西宾尚馀谕，望幸犹踟蹰。","何当树翠华，万玉趋赤涂。"]},{"t":"慈孝寺送顾待制次韵和孔舍人","f":"五言古诗","c":["丈夫老益壮，鬓毛岂知秋。","多君志慷慨，不避千里游。","跃马过黄河，北视三四州。","要官在东序，河图间天球。","古来功名人，未就不肯休。","譬如凿空使，尚致安石榴。","况今南亩民，往往东西流。","还定安辑之，千仓仍万辀。"]},{"t":"新作西池呈王守","f":"五言古诗","c":["清源注长波，萦回十里内。","泓澄鉴群物，杂细分毛介。","旱岁未尝减，隆冬方可爱。","传云五龙旧，疑有神物在。","惜此去人近，久随荆棘废。","赏心一朝同，版筑四面会。","凿池两汉集，抗榭群山对。","种花渐成蹊，栽竹俄自倍。","荷芰入四邻，鸥鸟盈千辈。","鱼游明镜中，人语红尘外。","眷兹仁智乐，况乃登临最。","沧浪欢濯缨，药饵劝飞盖。","讼閒固材胜，神逸自形泰。","愿言载笔间，屡得从公迈。"]},{"t":"泛舟","f":"五言古诗","c":["出郭已清思，浮舟暂长啸。","水云两涵泳，青翠相照耀。","赏心随值遇，物色相顾召。","逍遥忘回期，顷刻揽众妙。","白鸥亦知机，潜鱼不可钓。","飞沉信乐然，回首寄一笑。"]},{"t":"和黄节推陪王守泛舟","f":"五言古诗","c":["清池堪百亩，珍木多十围。","灌泉昔未盈，移树今更肥。","境豁自心匠，宴游及韶辉。","居然坐高斋，不减临郊扉。","青旗贳冻酒，春服成单衣。","游人半童叟，好鸟偕鸣飞。","彤襜照银章，宾从相因依。","置觞面高轩，密坐罗芳菲。","清笳急鸣鼓，红妆耀迟晖。","澄潭止可鉴，画楫相与挥。","曳裾载笔简，自顾才也微。","之子倾盖贤，赏心谅云稀。","长歌善必赓，旧令繁勿违。","徒令夕阳暝，不醉终无归。"]},{"t":"舟行","f":"五言古诗","c":["川形直如线，川水疾如箭。","扁舟急鸣橹，顷刻异州县。","晤语不及闻，注视目已眩。","川后扈予桡，黄鹄莫我先。","客行自超越，快意令人羡。","寄语幽并儿，勿誇鞍马便。"]},{"t":"题卞大夫西湖所居","f":"五言古诗","c":["献玉晚见售，刺虎有馀勇。","宦游四十年，老发成种种。","乘轩非不荣，半刻未为冗。","而有田园归，末路益光宠。","平湖澹空阔，古木俱秀耸。","樵斧间渔舟，稻畦连麦陇。","田舍易所求，达生厚自奉。","晏眠胜饮冰，一笑异将恐。","予亦濩落人，不知物外重。","卖书问东家，此计行接踵。"]},{"t":"重用前韵赠卞大夫","f":"五言古诗","c":["辞满苦不早，独往始为勇。","闻君湖上田，二顷容五种。","力农有休期，杂费宁谓冗。","岁事副夙心，素封弥假宠。","若人寿者相，眉豪耳秀耸。","陶公请息交，林类歌面陇。","诸侯非得友，明诏期不奉。","丛茂鸟所安，渊深鱼勿恐。","由来浮云志，九鼎未加重。","胡为突不黔，憔悴摩顶踵。"]},{"t":"江行","f":"五言古诗","c":["移舟次北渚，风水亦有说。","隐几见群山，昂头看新月。","田舍烟微茫，江船火明灭。","夕阳归鸟尽，入夜人语绝。","劳生间忧虞，各自有怡悦。","趣取一时欢，谁能问蛮越。"]},{"t":"题刘羲叟著作泽州园亭","f":"五言古诗","c":["王屋连太行，重关束其左。","自古悲摧轮，多君识高卧。","凿泉深百尺，养竹成万个。","诗书满高屋，谈笑惊四座。","人常求赢馀，世每敝名货。","看君逍遥风，陶阮不远过。"]},{"t":"次韵","f":"五言古诗","c":["落泉无时休，泄云常自还。","居然万峰秀，共此亭户间。","擘华力何壮，凿陇巧已艰。","造幽非近规，会心宁愧颜。","朝扉面苍苍，夜枕听潺潺。","莳以松桂丛，葱翠皆可攀。","长歌发真赏，锦绣先斓斑。","座客齐起予，清玉联玦环。","夙龄慕远游，未能遍人寰。","学仙理茫昧，遁俗事间关。","风波天一隅，不到三神山。","终当振衣往，对境聊自閒。"]},{"t":"贺吴九","f":"五言古诗","c":["儒术喜迂阔，学官每留滞。","君侯诚百一，才智两自异。","新书三十章，慷慨天下事。","每闻一篇奏，左右称万岁。","峨峨蓬莱山，册府上帝秘。","紬书必英才，念子方历试。","前此三数公，致身自容易。","心知青云路，已识翰飞地。","岂独铅椠间，是正琼瑶字。","顾念倾盖交，寂寞弹冠意。"]},{"t":"盆池","f":"五言古诗","c":["覆杯坳堂上，儿戏种莲芰。","自怜守甔石，及物功已细。","虫鱼共涵泳，蘋萍生自恣。","清澄照毛发，列宿镇三四。","炎风久无雨，淮海日腾沸。","岂不潜蛟龙，莫肯救憔悴。","惜哉万里波，贻此升斗愧。","人当问能否，何必嫌小器。"]},{"t":"赠黄安期推官","f":"五言古诗","c":["退之谪阳山，始得区生喜。","其后迁揭阳，颇复称赵子。","穷荒非人境，瘴海绝涯涘。","亲识久去眼，此言不到耳。","所欢诚易为，未必尽洵美。","谕如逃虚空，闻人足音尔。","我来衡山阳，情况本异此。","一意等万殊，何尝分远迩。","四海皆兄弟，蛮貊固州里。","而于择友间，颇戒不如己。","乃得黄夫子，风韵淡如水。","为学本之性，言文贯于理。","遗我累幅书，磊落字盈纸。","不诡亦不矫，不华仍不俚。","胡为连城珍，韫藏椟与匦。","赏心一何快，区赵非所拟。","昔我在朝廷，尝得二三士。","声名未振发，自任以为耻。","于今复何能，有志而已矣。","譬将助飞迁，身方在泥滓。","作诗写吾心，词殚意未已。"]},{"t":"同韩持国游五岳观时原甫暨诸公先在因寄江邻几梅圣俞","f":"五言古诗","c":["简服车马轻，出郭尘埃远。","况兹偶同好，慵惰重推挽。","寿宫如屯云，重门谨关键。","五城十二楼，瑶池芙蓉苑。","境深日迟永，天近春纤婉。","异花秀烨烨，弱柳垂宛宛。","初从钧天游，列帝皆龙衮。","俗骨已屡惊，凌虚翻自忖。","却逢桃源客，笑语何缱绻。","尚留樵叟棋，竞劝胡麻饭。","金醴泛馀杯，芝英饵丰本。","平生此游胜，馀恨相知晚。","重来恐已迷，尽兴仍忘返。","群公谪神仙，吏隐亦肥遁。","尚平夙昔志，读易明益损。","宁知五岳期，不待越崖巘。","何当谢羁束，相与同息偃。"]},{"t":"夏夜露坐","f":"五言古诗","c":["林卧霄露清，仰观众星晖。","上天垂光彩，楼观何参差。","阁道绝银汉，华盖临紫微。","凝神云霓表，忽与汗漫期。","整衣阊阖门，濯足牛女矶。","酌酒援北斗，鼓箑招南箕。","极意谢嚣烦，尘世良喧卑。"]},{"t":"雨后","f":"五言古诗","c":["雨后炎氛减，空堂起清凉。","萧萧野风声，淡淡孤月光。","晚睡梦亦短，常苦秋夜长。","停灯览群书，坐以待未央。","鸡犬互争栖，邻里舂黄粱。","中夜寂无喧，蟋蟀鸣我傍。"]},{"t":"送福州范文学兼寄张宜","f":"五言古诗","c":["山林忍长饥，君门不易入。","今时行路难，自古志士泣。","范生岷峨秀，学古名字立。","流沙万里驹，未恨晚羁絷。","一命吏瓯越，扁舟去乡邑。","文学亦备员，海禺更卑湿。","扬帆下三峡，南斗安可挹。","问津颇浩荡，蹈险实蹇涩。","吾闻养贤俊，不但糠籺给。","乃知黄金台，始隗众士集。","送行勿惆怅，人寿期七十。","古来功名士，白发亦可及。","因君谢张老，青紫未易拾。","且当黄鹄举，不尔玄蛇蛰。"]},{"t":"送孙巨源","f":"五言古诗","c":["衰老不择交，倾怀未尝悔。","非吾相知心，亦有中获罪。","谁能若楸柏，雪霜不变改。","自念孤剑心，炯然镇长在。","识君始恨晚，及此将十载。","相与忘形骸，依然见乐恺。","翔凤刷羽仪，天真辉文彩。","清泉浚长源，滥觞已自倍。","乘间辄相过，慰我胸傀礧。","使我意轩昂，脱我中心痗。","今君官南州，扬帆尽淮海。","腰绶盘青緺，儿衣间缯綵。","兰羞当及时，倚门方有待。","一值归飞鸿，寄声尚无怠。"]},{"t":"登城望山","f":"五言古诗","c":["城隅见连山，苍翠横座中。","白云卷霄汉，千叠张屏风。","此地有佳致，望望情不穷。","忽如出尘寰，相对前后峰。","古墙有石色，草树仍蒙笼。","樵隐事不一，养痾方易容。"]},{"t":"同谢二兄弟游城南王氏园坐竹中水上","f":"五言古诗","c":["昧旦从吏役，中昃既休閒。","慨然田野兴，策马从近关。","谢公虽朝裾，雅意存东山。","相期物外游，待我季孟间。","晴阳煦烟郊，蔼蔼春气还。","南溪已浮冰，乱石声潺潺。","意得境弥好，形劳心讵艰。","名园得暂息，奇树多可攀。","去水贯林竹，脩篁夹澄湾。","波光龙蛇行，微风鸣佩环。","窄径偶深入，交柯存勿删。","并流一长啸，照影清心颜。","胜事岂有尽，向此同蒯菅。","发兴自我辈，忽如远尘寰。","严城迫归鞅，夕阳稍朱殷。","后游期不忘，秀卉春斓斑。"]},{"t":"颍州始居","f":"五言古诗","c":["伐树圣不忧，夺鬲贤不羞。","士生志四海，外物非预谋。","乘流既孤逝，择荫方暂休。","俱非田园归，而愧乡党投。","卜室远人境，开门面良畴。","车马寂不喧，水火仍易求。","主人邦之良，高义逾九秋。","倾盖仍旧交，食薇亦愿留。","如何干旄诗，千载令更酬。"]},{"t":"春葺所居","f":"五言古诗","c":["贫贱智不远，终年谋一身。","北堂甫成冬，西轩已送春。","开窗纳清风，扫地祛凝尘。","今是觉昨非，会意成日新。","一悟蓬荜兴，寄言当世人。","时事亦寒暑，无为迷旧津。"]},{"t":"寄傅推官尧俞","f":"五言古诗","c":["三川帝王宅，二周冠盖都。","上公釐德化，多士盛中区。","是年诏有司，使献贤能书。","传纳事匪易，吾与夫子俱。","率马仰骐骥，治玉惭礛䃴。","同舟共艰难，倾盖聊欢娱。","浮云俨高冠，白雪纷长裾。","驰辞若波涛，掌握皆明珠。","诋诃讵敢然，倚办实有须。","从子骖之靳，相与步骤趋。","棘围似南宫，大暑临通衢。","不遗老成人，颇多君子儒。","丞相顾而叹，里闾共称誉。","狂士或妄谈，众人皆揶揄。","至今颇自矜，快意胜过屠。","不言世所无，请问谁弗如。","微官苦绳墨，离别天一隅。","向风愿相从，不及单飞凫。","云中多宾鸿，河中多鲤鱼。","契阔诚未忘，寄声当勿疏。"]},{"t":"和原甫同诸公饮郇公园","f":"五言古诗","c":["车马何籍籍，相从城南陌。","大第锁名园，朱闳间素壁。","即事览胜槩，抚旧叹陈迹。","零落归山丘，慨吒西州客。","春风几时还，顾盼生颜色。","杂英缀初红，宿荑吐新碧。","故池无还波，乔树实自昔。","赏心及兹辰，缅想缔构力。","十千置尊酒，玉斗雪霜白。","饮醉半欢哀，浩歌怀感激。","天地亦旅人，川谷故变易。","欢娱瞥过目，百年犹暂觌。","即令西驰晖，稍复向禺昃。","我辈不尽兴，将为后时惜。"]},{"t":"送谢大城南还游集禧观寄谢大得箕字","f":"五言古诗","c":["骤雨堕河汉，烈风振南箕。","秋阴变萧爽，重此田野期。","森木蔽严籞，交流会清池。","幽鹭起丰草，鸣蝉嘒乔枝。","客车忽已远，樽酒难重持。","谁令语言适，深作别后思。","夕霁归马轻，叩户仙真祠。","羽人披衣笑，官殿凉参差。","黄鹄自飞来，青竹方可骑。","相从岂无术，望君隔前陂。"]},{"t":"书怀","f":"五言古诗","c":["幼学慕高远，读书不求解。","志为逍遥游，耻以声名卖。","宁从子桑简，不愿伯夷隘。","未常忧瓠落，岂复顾机械。","遁时良无闷，涉俗适得怪。","但使心休休，那论行夬夬。","世涂剧坎阱，人理甚蜂虿。","低颜费将迎，非意成睚眦。","铁冠喜弹画，法吏乐罥絓。","洗濯出瘢痍，丹青恣描画。","抗言畏不伤，奉职谓匪懈。","指擿本无瑕，销铄缘鼓韛。","群嬉更啸呼，斗巧逾狡狯。","抵巇加捷翻，取必期称快。","上恩初优假，一眚犹纵解。","虽蒙三面宽，未免六翮铩。","全生愧液樠，有道羡瘖瞆。","失马未必悲，堕甑何足喟。","后皇物群生，大块为之噫。","在盈或时亏，有支那可坏。","行苇无践履，甘棠勿剪拜。","犹将采葑菲，讵有弃菅蒯。","宁当置韶濩，始欲荐任韎。","厌饫椒与兰，玩惜饐而餲。","宿名守枯槁，知命遗芥蒂。","猖狂蹈大方，屈服嗌若喝。","腰舟虽云慎，吹齑亦已惫。","既往诚无追，有来当自戒。","萧萧鬓毛改，杳杳岁月迈。","愚谋向千失，晚悟犹一洒。","龟手世絣絖，支离保针茝。","鬻渡学操舟，闭肆从问卦。","念皆贤者为，亟闻古人话。","有田倚江湖，往岁成亩浍。","还归岂无图，绪业颇未败。","采菰仍得鱼，种榆因及薤。","小屋蔽蓬茅，大囷输精稗。","逢迎具壶浆，称贷偿私债。","暑从泉流濯，寒有檐日晒。","何苦事明经，区区矜地芥。"]},{"t":"剥枣","f":"五言古诗","c":["枣下人不行，四旁生蒺藜。","秋来见成实，粲粲青红垂。","敲树落碧瓦，溅石投赤矶。","纷纷竞口实，聊混儿女为。","树上已空枝，树下亦有蹊。","人事但如此，桃李真自欺。"]},{"t":"赤甲竞渡","f":"词","c":["古潭苍苍照毛发，龙藏水心波色活。","风雷如在石壁下，有时云雨何仓卒。","今年天旱百昌死，神物亦恐俱埋没。","南人厌龙抱珠睡，骈舟伐鼓探龙窟。","皆言龙惊当上天，九河翻雨石涌泉。","君不见朝来积水上，鱼鳖死尽龙安眠。"]},{"t":"酴醾轩雨中","f":"七言律诗","c":["积雪犹残雨复新，正朝日晦只逡巡。","浮云未省见白日，细草何事知青春。","杖藜苦恨泥污客，解衣生憎寒著人。","迁莺来燕势未可，天意靳靳留芳辰。"]},{"t":"在郡作","f":"词","c":["朱门深沈十二戟，高槐蔽庭有佳色。","今时督府雄汉魏，鲁国太山四千石。","读书作文五十年，齿牙脱落头半白。","平生心事竟何许，衮衮簿书为报国。","吾衰不复梦周公，闻道家丘居在东。","垂老才为少司寇，杀一正卯那为功。","诗书误身既可信，却忆扛鼎之重瞳。","宰割山河一何壮，指麾天地如回风。","背关怀楚更龌龊，沐猴而冠涂遂穷。","区区诸老为城守，头胪晓入旌旗红。","鲁人之皋乃自昔，犹复弦歌一亩宫。","圣贤万事尽有命，世人何用誇材雄。","府丞久吏掾史健，时雨沾足年谷丰。","深居闭閤不复出，曲肱甘寝日正中。","昔闻汲黯淮阳亦如此，乃不及舞文巧诋为诈忠。"]},{"t":"杨之美弹棋局歌","f":"七言古诗","c":["汉皇初厌蹙鞠劳，侍臣始作弹棋戏。","东方诸公盛得名，魏文以来称绝技。","后宫妆奁乃可为，客著葛巾尤更奇。","谁令朱墨异贵贱，百世纷纷无已时。","君从何处得此局，石理温华瑩寒玉。","山形四隤涧谷深，别将望秦森在目。","少年博戏日益新，古事不复传今人。","君能兴此亦先觉，辟雍老儒悲绝学。"]},{"t":"和陆子履鱼胶亦名阿胶可以羽箭又宜妇人贴花钿","f":"七言古诗","c":["汉家金缯抚绝域，远夷畏威亦怀德。","南琛北珍不自惜，译官贾人多未识。","此胶出从辽水鱼，居人钓鱼取专车。","秋风时节候可折，白羽铺缀随呵嘘。","赤车使者来穹庐，并鞶玉玦通函书。","黄河之清那可俟，美人红袖应时须。","丈夫辛勤万里外，少妇深闺苦凝待。","京兆眉怃传长安，翠钿彩饰令人爱。","凤凰得髓麟取角，将来续弦弦不觉。","更嗟珍物空传名，欲倩张骞问方朔。"]},{"t":"昭君怨戏赠","f":"词","c":["武皇听歌长太息，倾城不难难绝色。","连娟脩嫭果自得，三十六宫宠无敌。","君不见孝宣既没王业衰，优游时事牵文辞。","延寿丹青最叵信，无盐侍侧捐毛施。","此时昭君去宫掖，边风侵肌雪满碛。","穹庐旃墙烧?蠡，琵琶怨思胡笳悲。","犹怜敌情不消歇，子孙累世称阏氏。","传闻汉宫翻可愁，纨扇绿衣长信秋。","燕啄皇孙两悽恻，当时无事成深仇。","覆杯反水难再收，深渊瞬息为高丘。","尘沙萧条猛虎塞，边民独记和亲侯。"]},{"t":"春日","f":"七言古诗","c":["春波淫淫泉脉清，揵菑作担芳草生。","女桑柔弱欲动色，落枝投斧声敲铿。","山前一雨杏花白，布谷来往相和鸣。","鞦韆系树径路熟，童稚翁妪欢逢迎。","田家此乐世岂知，人生所急食与衣。","计谋虽拙日有效，筋力无馀身得为。"]},{"t":"幽州图","f":"七言古诗","c":["鄙夫平居常叹息，蓟门幽都皆绝域。","安得猛士守北方，力排敌人复禹绩。","田生手携朔漠图，丹书万里之强胡。","挂图高堂素壁上，壮或阴山来坐隅。","长城迢迢属沧海，古塞历历生黄榆。","纵横指顾皆旧物，抚事慨时惊呼。","太平壮士多虚死，念君避胡来万里。","九关深沉虎豹恶，布衣何由说天子。","卷图还君意黯然，咄嗟世事非余耻。"]},{"t":"汲颍水","f":"七言律诗","c":["城中凿井非不深，苦泉欲饮先烦心。","天生颍水似碧玉，盛夏一酌逾千金。","野童絜壶不盈斗，清能照眉甘适口。","未曾一饭过闾里，犹以空瓶累川后。"]},{"t":"次韵范内翰西圻老人诗","f":"词","c":["大行宫车千乘强，翠华晚驾烟苍苍。","龙髯堕地长秋草，白云悠悠飞帝乡。","先驱轶出塞门外，天宇寥廓初无傍。","凄风疾雨走道路，万灵奔走谁非常。","汉家德泽遍四海，戎夷执绋虚边疆。","翾飞啄息愿效死，以彼壤穴皆容光。","词臣宗功笔力壮，感激顾遇思揄扬。","周宣中兴在云汉，武皇最著惟宣防。","道旁老翁话旧事，面目黧黑情摧伤。","赐缣如雪身独得，无衣自幸方同裳。","桑田变海不可测，恸哭白日悲风长。","君不见封禅之君皆不死，岂以衣冠之葬疑轩皇。"]},{"t":"和苏子瞻韵为石苍舒题","f":"七言古诗","c":["长安材豪雄五都，五陵意气谁能除。","作人不入游侠窟，寓兴聊从草隶书。","崩崖坏山出众宝，石刻鼎铸周秦馀。","江东诸家擅逸气，宜官钟蔡几不如。","腾龙翥凤动光彩，渌池滉漾华芙蕖。","石生临书得微妙，神凝意会下笔初。","浓纤巧致若出一，老庖利刃投空虚。","人间流传不得辨，锦囊玉轴争贮储。","以兹得名号醉墨，聊取胜事题精庐。","岂与西山少年辈，射猎狐兔夸里闾。","杜陵诗仙有祖风，笔洒云雾挥琼琚。","我今才薄厌数语，勉力和歌惭起予。"]},{"t":"傅尧俞草堂歌","f":"词","c":["汉朝名臣有傅伯，谏诤由来犯颜色。","兰台下笔不自休，义阳封侯勇无敌。","石渠昨者承明直，虎符今为二千石。","邀我请赋草堂诗，草堂欲归那可得。","太行之上无高山，济水之外无清源。","闻君筑居山水际，清高正为君家言。","上有无心之云出幽谷，下有劲节之竹森寒玉。","四邻空地犹几许，容我东西一茅屋。"]},{"t":"虎子","f":"词","c":["秦山十月朔风起，寒岩萧萧虎携子。","樵苏绕山不敢采，赤豹黄罴相向死。","关西少年勇似飞，白羽利镞黄金机。","解胸陷脰心应手，功名一决何辞危。","坐皮食肉已自快，况复猛毅充提携。","雄姿英气实少并，不堪笼槛长羁縻。","至今求食每摇尾，摧刚远害诚其宜。","君勿爱泽麋山鹿大如马，牙角虽具无能为。","阨穷隐约岂足讳，曾见白额跳踉时。"]},{"t":"和李公择题相国寺坏壁山水歌","f":"七言古诗","c":["苍山本自千万丈，怪尔断落盈尺中。","枯松挂崖正矫矫，白云出谷方溶溶。","忆昨高秋十日雨，百川涌溢腾蛟龙。","丹青坏劫不可驻，金碧拂地俱成空。","人间流落万馀一，掇拾补缀几无从。","当时画手合众妙，得此诚是第一工。","松阴行人何草草，秃帻小盖马色骢。","长涂未竟不得息，啸歌正尔来悲风。","巨灵擘华疏黄河，夸娥移山开汉东。","海波芥子互出没，大雄游戏神与通。","我今与君未尝觉，指视壁画将无同。","新诗飘飘脱俗格，得閒会复来从容。"]},{"t":"空同","f":"词","c":["汝山不高鲜乔木，汝水不深无巨舟。","荒草连天荆棘壮，土脉疏缓多废畴。","三年力耕食不饱，一时不雨人相忧。","负薪代炭集市井，耳聋眼瞑垂白头。","土风薄陋趋向狭，一金之子称良谋。","百年人物可料数，里闾未见兴公侯。","君不见广成昔从空同居，猗玕亦云隐商馀。","千年两士炯若日，希世之才安可诬。"]},{"t":"画龙","f":"七言古诗","c":["南人谒雨争图龙，画师放笔为老雄。","烟云满壁夺昼色，雷电应手生狂风。","观者皆惊牙爪动，攫拿意似翻长空。","吾疑奋迅出户牖，何事经时留此中。","共言叶公初好画，当时亦有神龙下。","天意为霖非尔能，世俗慕真聊事假。"]},{"t":"冬","f":"七言古诗","c":["蜂房割蜜留度年，中林置罝长击鲜。","朔风吹空塞北户，束薪明暖初无烟。","缺篱补疏已乍密，败屋鬋茅元自坚。","官租事空不复出，积雪塞径长昼眠。","田家此乐不知老，儿孙满前俱寿考。","世俗荣名多变更，不似田翁一生好。"]},{"t":"苏子瞻家画松图歌","f":"七言古诗","c":["君家图画皆所见，近得此松尤可羡。","根蟠平石蹙蛟螭，干出青冥起雷电。","樛枝横斜复几尺，绿叶茸茸铺绣线。","空堂深沈白日寒，谡谡似有风吹面。","此图剪裂人不知，尘外分张数流转。","能令神物还相从，非君苦心谁与辨。","更惜良工名不传，可怜世俗多夸衒。","为君作歌君志之，后千百年无复贱。"]},{"t":"赤甲祈雨是日获之","f":"词","c":["君不见赤甲之渊色如墨，中有神物不可测。","潜虽伏矣心念国，翕忽变化谁能识。","五月亢阳裂金石，妇女悲号望膏泽。","箫鼓甘香乐灵德，须臾晦冥天正黑。","风雷硼轰震穹碧，雾雨霶沱扫炎赫。","生物欣欣动颜色，樵童牧竖亦叹息，千秋万岁无终极。"]},{"t":"市朝","f":"七言古诗","c":["市朝老去无希慕，枕簟秋来觉静便。","何事连宵梦颠倒，犹应三世业攀缘。","蛲虫饱足尸鬼健，尚寐翻令爱不眠。"]},{"t":"贫交行","f":"词","c":["贫交多相怜，富交多相捐。","贫富尚不保，死生安可道。","人能无以声利为，贫交富交皆不欺。","君不见萧朱隙末张陈死，惟有管鲍真相知。"]},{"t":"古信陵行","f":"词","c":["薛公藏卖浆，毛公藏博徒。","侯嬴抱关叟，朱亥市井徒。","我思信陵君，下此四丈夫。","富贵胡为弃贫士，能令君存为君死。"]},{"t":"方仕致仕","f":"七言律诗","c":["在家出家古有此，方仕致仕吾自嗤。","晏眠足当几杖赐，散发每从田野期。","息交便尔宾客绝，省事何说课最为。","山涛非隐亦非吏，仲元不惠仍不夷。"]},{"t":"北门行","f":"词","c":["慕道逍遥游，不作枯槁语。","二年客都城，卒岁厌贫窭。","乃知北门诗，圣人亦有取。","自于万事捷若机，今日已晤前日非。","五月披裘不取金，放歌会采南山芝。"]},{"t":"衰老","f":"词","c":["苍耳婴末疾，浴兰殊未解。","枲耳传愈风，及秋始堪采。","惟昔沙塞阴，偶从羊负来。","葡萄安石榴，安可同语哉。","鸡雍与豨苓，适用即为贵。","何必黄金盘，磊落荐滋味。","老人学道破诸妄，犹有尘缘为疾恙。","安得澡身并澡心，使我有意烟霞上。"]},{"t":"次韵孔常父","f":"七言古诗","c":["老翁衰迟为日久，自知不是文章手。","紫微荧煌十二星，青阁彤庭掖垣右。","谁令孤翼此飞栖，正似枯槎犯牛斗。","诸公可亲复可望，黄钟浑宏秋水光。","但论四海矧故乡，清诗翻翻鸿鹄翔，愿言与子同升堂。"]},{"t":"太液池","f":"七言律诗","c":["建章宫中太液池，水象星汉波涟漪。","凫雏雁子相群嬉，黄鹄来翔金为衣。","主人勿惜稻粱恩，主人勿矜罗网繁。","暂来可见不可亲，乘风一举超昆崙。"]},{"t":"送原甫帅永兴","f":"七言古诗","c":["读书当为王者师，论兵要作万人将。","古来志士希两遂，白首儒生彼无望。","骐驎一出凡马空，豫章蟠根岁逾壮。","金华事业烂然新，徂西谋谟谁与让。","旌旗蔽日红半天，笳鼓隘涂车万两。","中军令出听无哗，秦山渭水皆东向。","荒夷憺威霜雪明，属城阳和春日亮。","赵张成事不足论，方虎遗诗犹可尚。","龙文金铉待调饪，铉枢斡中付群当。","西人欢歌公肯留，公车双鹿画轓上。"]},{"t":"晚起","f":"七言律诗","c":["黄昏就枕日午眠，入春夜短常独然。","不嫌时世欲无觉，每为身谋私自怜。","梦为嘉鱼潜九渊，梦为飞鸟翔高天。","喜来寝觉了不辨，安知此兴非神仙。"]},{"t":"渔翁","f":"七言律诗","c":["老翁年侵耕作苦，官田税多不敢住。","身携儿孙事渔钓，编竹为家寄江浦。","朝寻菱芡逗烟水，暮饭鱼虾宿风雨。","人生如此亦自由，何用车马称公侯。"]},{"t":"和罗著作渔翁","f":"七言古诗","c":["渔翁结网求鱼子，得鱼满船心始喜。","岂知陂池水不深，但有鲲鲕少鲂鲤。","渔翁结网安得疏，渔翁用力常有馀。","心疑他人得厚味，满眼看来池无鱼。","古来任公不如此，期年得鱼雄浙水。","龙伯国人连六鳌，二山漂流不能止。","由来万事不同调，说似渔翁翁必笑。"]},{"t":"大风","f":"七言古诗","c":["朝风吹沙天宇窄，暮风吹沙地载薄。","视天昏冥畏其压，视地震荡忧其坼。","一春三月风不息，局天蹐地劳筋力。","波涛翻空霹礰怒，行路之难行不得。","安得重云十日雨，洗眼去眯分白黑。"]},{"t":"初调江阴主簿","f":"七言律诗","c":["小来读书非为名，约身不肯游公卿。","祇怜狂简真吾党，谩有文章惭老成。","汉廷好武臣尚少，郎官十年不见调。","青衫黄绶赤诏除，落拓敢辞流俗笑。"]},{"t":"送直史馆孙兵部知陕府","f":"七言律诗","c":["侍臣数厌承明庐，太守何妨太史书。","十里九坂二殽道，驷马高盖朱轮车。","分陕已信召南贵，补郡讵比平原疏。","谏垣风彩东观笔，不待上计看回舆。"]},{"t":"湘中阻风","f":"七言古诗","c":["十月北风不肯回，湘中白浪高成堆。","小如飞鸥大奔马，一辈才去群复来。","一旬阴云色死灰，划劙掀簸初全开。","晨阳照空幸澄澈，蜚廉暴怒犹喧豗。","系舟沙渚依曲隈，岁晏永路真悠哉。","棹夫卷缩亦何恨，时乎宁有材不材。"]},{"t":"欲雨寄张壁","f":"七言律诗","c":["北山云起南山雨，返照却见南山树。","逆风燕子能疾飞，隔叶黄鹂犹独语。","忆君池上波悠悠，忆君翠竹声飕飕。","兴来冒雨故相视，薄暮雷电归何忧。"]},{"t":"寄杨十七","f":"七言古诗","c":["杨侯论诗销我忧，昔岁相逢偕旅游。","梁多长者不虚语，倾盖结交子所求。","三年契阔意不展，叹彼栖栖为薮幽。","穷愁著书亦自足，有策肯说东诸侯。","长安富贵易反掌，末路功名犹捶钩。","天公于予岂爱惜，由来万事非人谋。","阴风朔雪五湖冻，岁穷高卧思同裘。"]},{"t":"春寒 其一","f":"七言古诗","c":["越罗裁衫春服新，寒炉委灰无复温。","夭桃著花红满槛，弱柳吹线青映门。","岂知天事有反覆，假借专物矜馀恩。","平明雪片白似玉，败裘死灰仍纷纷。","女桑吐叶蚕欲生，东郊草绿方趣耕。","玄冥欺人人弗信，百虫奋蛰雷已惊。","沈阴驱除坐可待，白日隐隐浮云外。"]},{"t":"春寒 其二","f":"七言古诗","c":["清明东风零雨频，晓来料峭寒著人。","人言天事不可测，欲回暮春成早春。","花红柳绿皆自若，一气变化宜有神。","漆园老人惜光景，求术却老无声影。","忽闻春有再韶时，亦觉身当还壮境。","花前一酌心熏然，敢道朱颜非少年。"]},{"t":"戏谢师直买伊阳田","f":"七言律诗","c":["雒阳东周苏子贤，兄弟驰说雄当年。","一身曾兼六国印，举世皆羞二顷田。","君才十倍鬼谷子，期年已出揣摩篇。","公侯将相可自致，何竟高蹈伊阳川。"]},{"t":"阳翟贾人歌","f":"七言古诗","c":["颍川阳翟赵邯郸，大衢如砥车班班。","重装富贵名游间，轻纨宝玉高若山。","关西王孙龙虎驱，此中奇货奇可居。","千金入秦藉短策，立谈须臾分王符。","华阳松柏成高丘，寿陵蔓草令人愁。","沈沈相府士如市，山东供事河南侯。"]},{"t":"和王平甫韩干画马行","f":"七言古诗","c":["韩干画马出曹霸，得名不在陈栩下。","诏令师栩辞不可，苑中万马师在我。","王侯读书爱此言，由来能事须天然。","看图作诗寄慷慨，锦文织字珠联联。","乘黄騕袅久埋没，安西大宛路超忽。","丹青能令千万年，不比燕人空市骨。","霜蹄踣铁精权奇，耳截筒竹稍垂丝。","超然抉后三十尺，一日千里御者谁。","舐笔和铅人所同，尔今独成第一工。","神凝意会不可料，天驷降精来此中。","少陵作诗讥画肉，惋惜骅骝气凋缩。","未知良工尝苦心，空使时人争贱目。","九皋相马观天机，神隽不辨黄与骊。","君知画手贵自我，何若相法非有师。","拙工俗子纷纷是，畏避权豪如畏死。","生栋湿涂多覆屋，巧书掣肘真难使。","吾知公诗正如此，丈夫特立嗟已矣。"]},{"t":"次韵苏子瞻韩干马赠李伯时","f":"七言古诗","c":["韩干画马名独垂，冰纨数幅横素丝。","诸公赋诗邀我和，我如钝椎逢利锥。","区中才容三万里，正可騕袅一日驰。","朝燕暮吴亦其亚，幸得夷路无絷羁。","此间三马皆国马，瑰资逸态成崛奇。","有如秋空见霜鹘，下睨众禽俱伏雌。","良工苦心为远到，天机要眇潜得之。","区区驽骀浪自负，岂可丑骨包妍皮。","李侯洒笔定超诣，尚有天骥君未知。","宛王母寡今授首，汗血不敢藏贰师。"]},{"t":"送程少卿","f":"七言古诗","c":["使君船舸如浮宫，荡荡帆影垂白虹。","苦无三江五湖水，安见一日千里风。","长蛟巨鱼远避去，水府泉室深玲珑。","使君按俗不异此，意气自觉凌虚空。","滕王阁前流水白，西山落日衔微红。","城头台榭眺望极，玉壶置酒光融融。","胜游重临不隔岁，涂歌巷祝欢南公。","作官得此亦是少，况复章绶弥尊崇。","南金折钩富九鼎，荆扬涂泥多岁丰。","会令利术析毫末，万古江流常向东。","故乡秀水三百里，送远游子情无穷。","遥知躧履待高士，安得羽翼随飞鸿。"]},{"t":"怀信驿亭晚望题其楹","f":"词","c":["吴樯东风晓来入，楚客齐桡暮去急。","行人西，行人东。","逢迎送归景不同，夕日春烟一望中。"]},{"t":"戏题西湖中鱼","f":"七言律诗","c":["重明水深波洗空，嘉鱼万族连西东。","鲲鲕细碎长者惜，赤鲤成就随飞龙。","南风吹雨中宵雷，众鳞不去真常才。","鲂鱼如玉鲙第一，安得大网相随来。"]},{"t":"盆山","f":"七言律诗","c":["青泉盈池底白石，中有高山高不极。","连峰绝壑知几许，朝霏暝烟无定色。","山下清波清浅流，鱼龙浩荡芥为舟。","今君欲渡何由得，纵有神仙君不识。"]},{"t":"出门无马行","f":"七言古诗","c":["市儿暮归钱满把，田翁秋收禾满野。","人生勤苦必有获，天事岂常遗拙者。","鄙夫能言知读书，十五著论惊群儒。","文章不作少壮用，白发垂领皮肉粗。","作官不如閒日多，得禄无若饥寒何。","百年陈人谁比数，满眼贵士难经过。","欲为揣摩心智短，欲学造请颜色赧。","黄金难成丹砂贵，紫芝将秀白日晚。","退居长安百不为，出门无马还步归。","高天报施固有待，可得不如翁与儿。"]},{"t":"次韵子瞻赠乔道人","f":"七言古诗","c":["昔有仙公项曼都，去家十年若斯须。","还归壮语惊妻孥，月边朝拜虽劳躯。","流霞一杯真味腴，世人但怪医多卢。","不知列仙山泽臞，阴阳变化随指呼。","日新无穷非故吾，乔公筑居近潍都。","交游洞宾侪尔朱，又言其师奇丈夫。","璞玉粹美名不沽，郎官仕晋更五胡。","我今老病须人扶，衰颜白鬓日已渝。","捐书绝学休守儒，去不为少犹双凫，公能济我良药无。"]},{"t":"侠少行戏王子直","f":"词","c":["长安少年侠自任，一生意气过人甚。","许身直以豪取名，快意那知武犯禁。","宝刀强弓千里马，风驰电射无敌者。","有时独醉倡楼春，一身歌舞兼百人。","休来著书吐胸臆，脱落章句嗤丘坟。","王侯愿交不可得，贵者虽贵犹埃尘。","君不见汉家云台画良将，高冠长剑森相向。","由来落拓尘土中，不妨论议岩廊上。","乃知功名为世贤，安知轻欺恶少年。"]},{"t":"王家酒楼","f":"词","c":["君不见天汉桥下东流河，浑浑瀚瀚无停波。","游人阅水看白日，骇浪瞥远红影蹉。","感叹世事亦如此，振顿两足行吟哦。","提钱买酒聊取醉，道傍高楼正嵯峨。","白银角盆大如艑，臛鸡煮蟹随纷罗。","黄花满把照眼丽，红裙女儿前艳歌。","乐酣兴极事反覆，旧欢脱落新愁多。","夷门城东门，南对屠儿墓。","信陵今安在，宾客散如雾。","窃符事可鄙，袖椎复何慕。","犹令主人成大功，千岁英名若可遇。","笑杀平原君，耻从毛薛游。","选士十九人，毛遂晚见收。","丈夫一身贵特达，因人成事良足羞。"]},{"t":"和章都官洞庭诗","f":"七言古诗","c":["阅水须阅秋水时，洞庭八月为最宜。","百川涌溢注平旷，倒卷溟海翻天池。","潇湘沅澧绀碧色，千里一片清琉璃。","蜀江亦浊远不杂，正若黄组萦鉴匜。","长风簸轩一何壮，雪浪成山相蹙移。","奔霆击电恣轰磕，素车白马交横驰。","朱垠骋望更无地，翼轸落影光参差。","南极老人坐盘石，赤足皤鬓濯项颐。","修鳞巨鬣出万族，窟穴鳣鲔泥蛟螭。","身躯长大竟无益，机械利器潜相随。","但令渔师贾馀勇，冒突死地常安之。","巴蛇断骨不自免，此曹幺么何能辞。","秦皇属车八十一，赭衣伐山豪不羁。","九疑不到二妃泣，圣贤失势令人悲。","忆登洛阳值摇落，暮霞新月含风漪。","古今光景共一瞬，独绕四壁观题诗。","神官威岩鬓似戟，楼船持节森画旗。","湘灵奔走伺颜色，鼓瑟献巧招冯夷。","新篇秀句远为寄，清风白芷丛余思。","呼儿叠纸作报语，衰老抚事情孳孳。"]},{"t":"新滩行","f":"词","c":["巴江之水西南来，峡束川壅声若雷。","瞿唐五月不敢下，滟滪中流大如马。","风波虽恶石不去，太古以来怨行者。","君不见前日巴山复摧裂，万仞臬兀江中绝。","孟冬水涸石角见，上流下流尽精铁。","当时长年皆有语，后来艰危从此数。","上天设险知为谁，但恐妨人如滟滪。"]},{"t":"和杨十七伤苏子美","f":"七言古诗","c":["苏君在朝素机警，气排青云力扛鼎。","鹓鸿遇风鄙巢栖，骐骥得涂嗤坎井。","千金置酒宴长夜，锦绣照烂丝篁静。","明珠盈车谤随起，白巾还家酒未醒。","翟公署门宾客改，魏牟去阙江湖永。","濯缨渔父唱沧浪，结庐陶令依人境。","时浮扁舟就什一，出从数骑非造请。","穷途诗语尤慨慷，暮年笔法加豪逞。","霜凋兰蕙不待老，一世欢悲竟俄顷。","遗书犹缺茂陵求，卜宅乍许要离并。","生平相望不相接，凛凛气概吾能省。","川流既逝安可回，骏骨虽买何由骋。","知君金石尝定交，末路人琴俱不幸。","大招无复修门期，怀旧邈与山阳等。"]},{"t":"城东观鱼","f":"七言古诗","c":["东城水深色如黛，居人来过不知爱。","我浮扁舟转城曲，苍烟古树寒相对。","忽如身在松江游，况有渔子前操舟。","霜天黯黯始下雁，雪浪杳杳频惊鸥。","万鱼挂网同时急，赤鲤长大犹人立。","旧疑古潭有神物，倏见金鳞却腾入。","楫师献功喜相顾，岸傍欢声仍坌集。","主人置酒乐未央，艇子行䏑轻相及。","吴酸缕鲙白玉盘，四座相喻同加餐。","人生万事岂有难，我能为公成此欢，兴极意移令我叹。","落日蔼蔼沈云端，岸草露白天风寒。"]},{"t":"观鱼","f":"七言古诗","c":["清濠环城四十里，蒹葭苍苍天接水。","使君褰帷乘大舸，观鱼今从北阙起。","开门渔师百舟入，大罟密罾云雾集。","小鱼一举以千数，赤鲤强梁犹百十。","浊醪赏功倾瓦壶，公言锡爵争欢呼。","馀人不及色沮丧，数奇天幸相贤愚。","浓云吹雨寒萧散，置酒移船泊前岸。","暴殄天物古所矜，谁道于今为壮观。"]},{"t":"送张太保知冀州","f":"七言古诗","c":["使君使敌前岁中，手为单于画吉凶。","敌人破胆不敢迕，即日归报明光宫。","汉家牧师三十六，水甘草丰马数足。","问谁虎臣司苑门，极望离宫皆苜蓿。","长河东来横冀州，雄雄大府森戈矛。","红旗照天军令肃，紫髯昂藏居上头。","将军威名动殊俗，天子今无北顾忧。","旧传冀土多良马，岁看北客输旃裘。","庙谋将新赤岸泽，强邻犹知博望侯。","使君家声仍世传，慷慨功名方壮年。","黄金如斗组丈二，富贵光华真谓贤。"]},{"t":"送裴如晦知润州","f":"七言古诗","c":["柳阴深碧黄鹂语，川水平堤鸥鸟舞。","送君临流眼暂明，爱此虚凉少尘土。","何况连樯一月行，吴山楚水相逢迎。","稻花吹雨香不绝，芦叶摇风声正清。","北固楼台似图画，广陵欲渡闻潮生。","缥壶盈前京口酒，红旆相随北府兵。","少年投栗常为乐，晚岁甘棠空涕零。","望君鸿飞不可攀，白头方出玉门关。","独向天涯共明月，犹应梦里借千山。"]},{"t":"送章学士知湖州","f":"七言律诗","c":["昔贤为亲屈小官，使君专城情更欢。","连山大湖水凝碧，高盖驷马车涂丹。","綵衣儿戏养颜色，箬酒宾宴罗杯盘。","吴兴钓碣亦可羡，怅望从事空南冠。"]},{"t":"陈和叔贺兰溪所居近有信来言水竹事戏赠","f":"七言律诗","c":["北山移文那尔为，淮阳招隐殊未归。","流泉涨溪可厉渡，修竹饱雨添旧围。","鸣禽作巢皆有托，白云抱石初无机。","主人已知战胜乐，溪童未老情庶几。"]},{"t":"柿红","f":"七言古诗","c":["柿红梨紫漫山熟，冷雨萧萧落乔木。","东田收谷亩数斛，筑场敛积高如屋。","柴车斑斑黄犊健，丁男肩涧儿指秃。","烹猪漉酒乐社神，急鼓悲笳断仍续。","田家此乐何所忧，闾里至老还相收。","道傍滞穗如山邱，何处老翁宁有求。"]},{"t":"寄题岳阳酒务水楼","f":"七言古诗","c":["洞庭苍苍水拍天，巴陵居人无斗泉。","天生地势正如此，抱瓮臂饮真堪怜。","架楼窾木出百尺，剖竹接筒如笔直。","惊雷发地山鬼忧，白波统霤湘君惜。","吾侯智与神鬼侔，古来能事皆悠悠。","会令太湖变春酒，更使骚客忘离忧。"]},{"t":"关西行","f":"七言古诗","c":["关西居人多闭屋，屋底老翁相向哭。","县官禁钱钱益轻，百姓无钱食不足。","平时斗粟钱百数，今者千钱人不顾。","大家萧条无十金，小家流离半逵路。","忆初铸钱为强国，盗贼无端皆得职。","迩来救弊因宽民，盗贼自苦民逾贫。","安得万物皆为铜，阴阳炽炭造化工。","铸钱万万大似尺，官定足用民家丰。"]},{"t":"移舟城东","f":"七言古诗","c":["厌闻九衢车马喧，泛舟初出城东门。","阴虹吐雨水势怒，河声浩浩如雷奔。","棹工欢呼事拳捷，童稚变色愁惊魂。","济危经险正当尔，安得拱默为希言。","虽无清泠可浣涤，喜见黄浊来原原。","便风催橹两快意，千里万里何足论。"]},{"t":"游济堤傅家园亭","f":"七言古诗","c":["济水与河俱至海，陶邱之北川原改。","由来天事不可料，黄浊长存清晦在。","犹馀平堤十里长，逶迤东注如高冈。","水泉味甘土脉腻，固知馀润宜群芳。","君家园籞临济堤，荆扉茅屋随高低。","当轩古木密如盖，无数杂花行有蹊。","谷虚遥闻樵斧应，昼静便有幽禽啼。","穿栽卜筑事未已，上为层台深凿溪。","东邻可买莫惜费，腊月课种当令齐。","柳绿正如陶令宅，桃红应似晋人迷。","城中老守厌窘束，行乐得至城东西。","此家园亭可屡往，薄酒自足充提携。"]},{"t":"和杨彦文嵩山诗","f":"七言古诗","c":["杨侯作邑山水中，县南百里维青嵩。","官閒身老诗笔健，乐与丘壑研豪雄。","是时新凉背炎夏，草木秀丽全天功。","重青叠碧百万状，有如耋老携儿童。","悬泉落崖泻万丈，震雷发地声隆隆。","阴风岩洞忽悽怆，寒生六月如凝冬。","祠官祀典有常秩，扫除给复何其恭。","孕灵产异远不极，面周负郑人殊风。","生云触石始肤寸，倏忽澍雨成冥濛。","群山相望不足算，礼若小国来朝宗。","幽人羽客此独往，深处时与神仙通。","念君吏职有章绶，池鸿笼鹤思长空。","暂留灵境寄心赏，仰止万古希遐踪。","梯高径侧目力短，涉历庳下非穹崇。","山中居人亦富逸，翠竹寒松名素封。","愿言携家事卜筑，采薇饮水欣长终。","岩田种芝地高下，茅屋溯水溪西东。","君能挂冠共此约，何必绮季东园公。"]},{"t":"送徐君章","f":"七言古诗","c":["每秋送客常羡人，今秋送君尤惜别。","白发相知无几何，明日扁舟成楚越。","忘形谁复到尔汝，末路转忧欺老拙。","西风落叶密如雨，信宿长淮见清月。","紫蟹出簖加二螯，白鱼挂网色胜雪。","人生功名何由致，适意勿羞徒餔啜。","何时亦得东南征，赤脚吴溪嘲钓碣。"]},{"t":"送杨康功知安丰县","f":"词","c":["杨郎作文殊勇为，辩如涛波捷刺蜚。","相逢喜吾故人子，门风宛存令我悲。","艾兰驱车最先入，百箭穿杨谁可及。","擢第胜人十改官，作官不辞万家邑。","劝耕课桑力有馀，吏事不受崇空虚。","后生才资动出众，何至苦心城旦书。","清泉百里环芍陂，楚人千年长不饥。","叔敖子孙负薪苦，念为廉吏何可为。","忽忆云台故侯司空公，五郡士马河西东。","功名亦有际会数，退让自是雄隽风。","谁谓鄙夫老昏忘，屈指古事犹初终。","作诗写此岂有意，正若指点山水书鱼虫。"]},{"t":"天马行","f":"七言古诗","c":["汉家天马来宛西，天子爱之藏贰师。","甘泉贵人宠第一，昆弟封侯真谓宜。","军书插羽庙选将，一朝百万皆熊罴。","大射卢山亦快意，死人乱麻非所悲。","论功庙堂谁与敌，外厩皆是麒麟儿。","白茅金印结紫绶，老将流落多瑕疵。","天生富贵实有命，宁复忆君贫贱时。","势高累愚计虑远，大志落落嗟徒为。","渭桥祖道一语泄，身衅边鼓家流离。"]},{"t":"和梅圣俞食鲙歌","f":"七言古诗","c":["黄河赤鲤非龙材，欲化不化烦风雷。","随波浮沉偷自得，网罗失身成暴腮。","火鬐锦鬣鳞雪霜，红眼照耀珠夜光。","若无鲲鲕与虾蚪，安见品格非寻常。","主人爱客不计钱，少妇缕鲙情可怜。","蜀姜吴橘正相益，炊菰絮羹还慊然。","燕人寸腴不足贵，专诸全䏑非珍味。","属餍默怀一饭报，欲令主人千万岁。","白玉换米桂作薪，主人家居长不贫。","卖鱼一值任公子，厌鲙与遍长安人。"]},{"t":"兖州古桧","f":"七言古诗","c":["兖州宅西有古桧，十寻度高百围大。","生理成全不增长，半枯半荣常常在。","游人相与疑汝年，桧不能言聊臆宣。","百番桃李香扑地，一辈蒲柳长参天。","束薪寻斧不旋踵，种子著花还比肩。","老身寂寞无颜色，犹有黄鹄来枝侧。"]},{"t":"早行","f":"词","c":["东方未明天紫色，凉风吹空声恻恻。","船人起语鸟奋翼，兼葭茫茫江水白。","石潭转旋蛟龙窟，岩壁冥蒙虎豹迹。","生存古木数十围，老死悬藤百馀尺。","民生有为俱事役，岂独羁人不遑息。","商歌浊酒聊慰怀，君不见仲尼旅人常接淅。"]},{"t":"夜携贾十五过巨源作","f":"七言古诗","c":["鄙夫开年便四十，白发垂颐眼眵涩。","不甘老态日见侵，自计多忧诸病集。","待诏侏儒饱欲死，囊空有时都绝粒。","丈夫立气须激昂，岂能中夜牛衣泣。","朱门贵人那易见，后生美仕尤难挹。","敝裘败屦欲安往，蹭蹬通衢还独立。","贾侯游从久不厌，孙君风谊今相入。","由来大瓠矜濩落，尚喜灵珀勤收拾。","暮通水火并邻居，巷无牛羊时屡及。","泛爱已许金石坚，觉我衰迟情汲汲。","清霜著屋万瓦明，白月当空北风急。","排门上堂童孺欢，青灯照书简编缉。","纵谈自尔外形骸，虚舟不值呼张翕。","赤桐烧酒倾玉杯，念君屡空此遄给。","葡萄紫熟梨甘津，寒菹盈盘更啜汁。","酒肠虽狭底能足，邂逅欢娱论串习。","百牢九鼎亦尽空，金带玉符谁等级。","三更还家灯火断，浩气凝虚荣都邑。","斗杓落北草木死，层冰凝水鱼龙蛰。","何时春雷起霖雨，宿云温媚天衢湿。"]},{"t":"次韵裴库部二月二日游傅园","f":"七言律诗","c":["二月二日春意动，东风生物来无垠。","苦怜清济不如古，却爱小园方及辰。","谷鸟出声已脱俗，林花一枝疑占新。","银壶担酒马驮妓，莫辜乘兴宁伤频。"]},{"t":"桃源","f":"七言律诗","c":["武陵溪深山合沓，岩谷掩映秦人家。","仙俗迷涂不可到，春风流水空桃花。","山中道人多百岁，翠发萧条神骨异。","渔舟往往傍林麓，相逢亦问人间世。"]},{"t":"黄金","f":"七言律诗","c":["黄金能成不愿铸，封侯可得差有求。","小来一意今白首，世事万变都无谋。","诗书已废徒博弈，交友益落空沈浮。","江湖渔钓足自给，拂衣归去营扁舟。"]},{"t":"瑞荷","f":"词","c":["西濠本连金水河，天潢之下分馀波。","波深水静生物秀，十步百步皆圆荷。","五月浮舟人不见，瑞荷亭亭尤可羡。","连二雕成白玉盘，合欢裁作青油扇。","浣纱女子红莲房，背面照镜匀鲜妆。","斜阳弄影并高盖，下有戢翼双鸳鸯。","人情贵少瑞云美，亦自天和独钟此。","周王嘉禾献同颖，汉皇奇木誇连理。","君不见今年大田所收十万仓，上客为子歌吉祥。"]},{"t":"凿井","f":"七言律诗","c":["旱天雨少官凿井，凿深源长水泉冷。","涂人无复触热忧，居人况有操瓢幸。","前王扇暍力已劳，后王舞雩功不省。","此功一成千万年，却愿炎日长当天。"]},{"t":"次韵和罗著作风琴诗送毕长官","f":"词","c":["君不见长风翏翏起山林，大木怒呺喧万窍。","是为天籁来无方，中有知音全众妙。","洛阳琴工誇死桐，齐鲁诸儒颂清庙。","刻商变羽不得骋，击手高张空改调。","岂如风琴得自然，但令雕虎长清啸。","铿锵阐缓连昼夜，已断复续谁能料。","不论九奏金石谐，那辨五弦宫徵少。","世间俚耳何足听，幸有杨荂嗑然笑。","高堂置酒月如霜，金盘照筵红蜡烧。","渊明子贱皆有琴，两君叵惜清樽醮。"]},{"t":"保州乱","f":"七言律诗","c":["缘边戍兵精绝伦，腹饱官粟思食人。","健儿睚眦杀刺史，可怜百口同埃尘。","燕云苍苍日色紫，帐前血流守尉死。","乱兵相欢肯畏天，保州去边无百里。"]},{"t":"耳病","f":"七言古诗","c":["风林几处飕飕叶，石涧无时浩浩泉。","正欲登山惊雨过，未经烹鼎怪汤煎。","病身老态何由避，耳疾行当耳顺年。"]},{"t":"竹间亭作","f":"七言律诗","c":["溪东杂花乱如谷，溪西老树交篁竹。","横槎波水才一苇，缭径出林凡几曲。","半旬霖雨泉脉动，四岸春风柳芽绿。","眼前景物向人好，心事幽忧伤局促。"]},{"t":"邓圣求往为武昌令刻石元次山洼尊及苏子瞻谪官黄州游武昌见前刻后同在翰林因有诗示余余为次韵和之","f":"七言古诗","c":["侧江小屋香酒醅，出林缭径丛花栽。","溪风暂过响修竹，岭雪未尽兼寒梅。","往游武昌值佳境，白云漫漫萦崔嵬。","孙家旧事颇可见，樊山杳霭临钓台。","赤壁楼船不馀烬，属车豹尾空尘埃。","埋名腐骨彼谁子，正见邱墟黄土堆。","三分割据亦徒话，今人尚为羞瓶罍。","谢公伏令首佳句，游衍相与期江隈。","次山孟宰继有作，洼尊取饮摩苍苔。","两公雄才又超拔，明珠照人眸睑开。","腾龙始知爪牙壮，掣鹰无复毛羽摧。","腰金佩鱼见官秩，不似迁客谈象雷。","朝廷一入不得出，丘壑何事烦公来。","南人歌声易慷慨，公诗感激成叹哀。"]},{"t":"蔡河渔叟","f":"七言律诗","c":["河冰始消春沮洳，老翁求鱼日来去。","川流容船网罟繁，上流下流密如雾。","跳虾潜斗不自惜，时复鲲鲕聊可识。","吁嗟劳心能几何，信道相看犹羡他。"]},{"t":"高楼","f":"七言古诗","c":["青楼高高危九衢，朱栏画栱相倾扶。","佳人当轩玉不如，红帘翠幕深沉居。","危弦促柱鸣笙竽，哀音感耳心意舒。","浮云不行飞鸟徐，游人驻车马踟蹰。","嘉肴桂酒白玉壶，浩唱烂醉何所居。","乐极哀多盈必虚，世故万变谁能图。","飞鸢堕鼠残诸虞，里闾豪杰何时无。","茂陵老儒空叹息，曲突徙薪才赐帛。"]},{"t":"古诗咏欧阳永叔家白兔","f":"词","c":["飞若白鹭，众不足珍。","走若白马，近而易驯。","古来希世绝远始为宝，白玉之白无缁磷。","乃知白兔与玉比，道与之貌天与神。","瑩然月魄照霜雪，红眼顾眄珠璘㻞。","山农提携越千里，主人得之誇众宾。","网罗脱死鹰犬避，一以洁素能超群。","清江怆神龟，大野伤麒麟。","刳肠折足不免患，智若三穴方全身。","主人好奇意不倦，有来往往蒙金银。","老翁守株更有待，勿使珍物遗今晨。"]},{"t":"始凉夜坐","f":"词","c":["八月秋风高，凉风动天地。","渐疑昼短少閒暇，况复宵长减眠睡。","空林露下物色清，閒堂明灯门不扃。","四隅寂寞群动息，我与蟋蟀皆宵征。"]},{"t":"刘五草虫扇子","f":"词","c":["吾宗白团扇，画作草虫样。","天时变炎凉，弃置几惆怅。","网虫苍苍颜色晦，画工笔法依然在。","剪裁帖缀复生光，白月团团仍可爱。","苍蝇轻巧蝴蝶狂，怒螳斮斧谁能当。","老蚕作茧意自了，露蝉孤嘒殊清凉。","其馀百品随变化，天机所动俱閒暇。","座人咨嗟用笔精，不知犹是今人画。","画工侯生今白头，有时看画还泪流。","壮年名声却自惜，老去心神无处求。","始知能事须当年，盛时一过殊可怜。","即今拙工各自喜，岂知此家先日前，落笔辄得千万钱。"]},{"t":"题欧公厅前两鹤","f":"词","c":["明公真爱鹤，相鹤选仙骨。","遂令千金姿，为君轩墀物。","啄腥岂复辞鸡群，铩翼欲比凫鹥驯。","聆音发舞似矜客，避寒孤警将依人。","吾闻芝田逸翮不如此，世上悠悠谁识真。"]},{"t":"苦热","f":"七言律诗","c":["南方炎德非寻常，六月高下俱探汤。","羲和未息不可避，寒门安在徒相望。","苦怜万物暍且死，反顾一身困在床。","愿呼快雨洗六合，径驭微风周八荒。"]},{"t":"和永叔春雪","f":"七言古诗","c":["陬筒吹灰变冥朔，生气萌泉天不觉。","凝阴忽升气横厉，重云大同势绵邈。","通衢漫漫走流沙，近甸稍稍堆乔岳。","焚炉姹女姿飞扬，匝野神奸谁彫琢。","刀圭不惜透墙隙，捷业俄然垂屋角。","户斜尺剑未及收，窗缺连环如可握。","鲜妆宫女喜深印，红手庠童斗坚搦。","暝鸡误晓屡咿咿，饥雀冲人犹啄啄。","虽怜林篁有摧折，却喜陇苗就优渥。","贫庐败褐憎破牖，富屋珍裘转深幄。","使君高义仍泛爱，颍士多文方力学。","猎师得隽鲜弃薧，厨酿荐甘清间浊。","气随阳春破凝烈，巧夺钧工畏名貌。","吾知郢人不复歌，古声比今为拙朴。"]},{"t":"次韵和裴库部喜雪歌","f":"七言古诗","c":["四时平分气升降，当冬宜藏反宣畅。","玄冥羸孱失其职，骤弛威权避威仰。","由来万事可尽料，一夕同云迷下上。","始疑群灵久猜阻，勿尔觉悟欢相访。","周宣商汤号明主，圭璧垂尽虚卣鬯。","岂如圣神备参两，精意潜发天垂贶。","朔风萧条严莫犯，四野皓白光弥望。","乾施无方意必均，阴杀夸多力尤壮。","松篁得意忍枯槁，鹰隼乘时戾宽旷。","层楼眺远复褰帘，密室就煖仍施幛。","舞投墙隙到中堂，响拂纸疏喧北向。","樵林无声自斤斧，野渡争趋急船舫。","富觞屡举极欢呼，贫屦践行赧嘲让。","谁令小邑尽华屋，不觉南山失青嶂。","月临静夜绝氛埃，涛起风江深荡漾。","豫期晴和当劝耕，径入园林稍挟杖。","宿酲未解鸡三号，照梁辉焕晨光亮。","裴侯清通思豪绝，郢曲不比巴人唱。","老均茵凭游益欢，閒藉杯酒神俱王。","明年三农饱牟麦，病民自可逃无状。"]},{"t":"地震戏王深父","f":"词","c":["员方肇开坼，积块成坤舆。","漂浮大波不自止，幸有万里之鳌鱼。","抃首戴炎州，尾直昆崙墟。","亿载不坠陷，始知力有馀。","扬鬐播四岳，鼓鬣摇五湖。","岂知古今士，竟以地震书。","自是世俗闻见拘，潢污蛙黾相随居。","我从龙伯借钩饵，钓鳌惟子知非诬。"]},{"t":"戏作卖雪人歌","f":"七言古诗","c":["北风冱寒红日短，火炉燃薪不知暖。","南山阑干雪塞满，连玉叠琼何足算。","时移事异不可言，眼看星火垂南天。","道傍暍死常比肩，市儿相与赢金钱。","彻功有时难久全，物生岂有金石坚。","煎汤沸腾在眼前，可得意气长矜权。"]},{"t":"刁景纯得假还丹阳","f":"词","c":["晨霜落川水，行子自相趣。","帝城桂为薪，斗米胜白玉。","丈人乘老犹爱书，十年厌直承明庐。","汉廷三最得予告，此行亦是思鲈鱼。","沙头打鼓朝发船，捩柂已见江湖天。","落帆京口望北固，此溪此山如宛然。","壮年封侯岂不好，金朱祇令夸者道。","闻公东冈长万杉，采芝何似商山老。"]},{"t":"樱桃","f":"词","c":["中庭两樱桃，枝叶密相对。","蟠根不十年，不能开花如绣盖。","前人费力后人赏，曩日春风今日在。","世间万事或如此，富贵功名岂无待。","共知韶光过眼疾，霞红雪白不足赖。","繁华及时数快饮，鸟散蜂飞无所悔。"]},{"t":"题合肥县效裕堂诗","f":"七言古诗","c":["九月霜降公堂成，江侯寄诗求所名。","定名揣称事不易，以予朴直言必诚。","百词号呶片语决，十役漫汗一教行。","令乎于此有馀裕，堂以效实非无形。","庭罗芳草寒转碧，池有鱼鸟閒不惊。","左经右律给啸咏，雨轩风槛含秋声。","今我不乐岁云暮，蟋蟀在堂鸿雁鸣。","主人爱客岂有极，助尔美酒长河倾。"]},{"t":"伤孙曼叔尚书","f":"七言律诗","c":["金声掷赋惟兴公，西河智略称会宗。","曳裾置醴初奋发，听履题剑方从容。","上倚壶遂以为相，众恨王骏不得封。","韫吾良臣九京地，此意自昔悲重重。"]},{"t":"茂陵徐生歌","f":"七言古诗","c":["茂陵徐生老且迂，一心区区长信书。","拜章北阙三待报，意欲霍氏安无虞。","那知世主心不同，积恶未极难为功。","徙薪曲突事不尔，壮侯几人能受封。","高岸为谷邱渊移，鲁酒之薄邯郸为。","人生决己各以时，旧意望君君不思。"]},{"t":"幽谷泉","f":"七言古诗","c":["幼卿初凿琅琊溪，忆当大历六年时。","欧阳今疏幽谷泉，复在庆历之六年。","两公相望几百载，中间游客常比肩。","山神爱惜第一境，邂逅知者方流传。","乃知胜事未有尽，可怜岁月犹依然。","穿云斸苔色澄澈，宝镜霜刃光蜎蜒。","岩前滥觞如可鉴，山下积石还成川。","如公好事诚难得，推公此心人莫识。","且如泉源在污泥，谁道汲引非人力。","作诗刻石歌泉池，欲问何似阳冰题。"]},{"t":"熙州行","f":"七言古诗","c":["自胡请盟供贡职，关西二纪剽兵革。","胡人岁来受金帛，地虽国本常不惜。","帝家将军勇无敌，谋如转圜心匪席。","精神动天天不隔，凿空借筹皆硕画。","贾生属国试五饵，买臣朔方发十策。","偏师倏然尽西海，一月三捷犹馀力。","百蛮解辫慕冠带，五郡扫地开城壁。","葱岭陂陀蒲类深，回笑秦并与禹绩。","尚书论功易等差，御史行封自明白。","武功貤爵十万金，彻侯印组丈二尺。","奋行过望理自尔，少从进熟来无极。","忆昔汉武开西域，天下骚然苦征役。","哀痛轮台置肥美，割弃造阳损斗僻。","岂知洮河宜种稻，此去凉州皆白麦。","女桑被野水泉甘，吴儿力耕秦妇织。","行子虽为万里程，居人坐盈九年食。","熙州欢娱军事息，天王圣明丞相直。"]},{"t":"庵岭渔叟诗","f":"五言律诗","c":["溪叟厌尘网，移家临水居。","开扉对山色，堰水活嘉鱼。","蓬棹自相得，笑歌还自如。","犹嫌子陵傲，老更就蒲车。"]},{"t":"道人申演","f":"五言律诗","c":["先生隐君子，暮齿寄山林。","苍鹤齐筋力，清泉漱语音。","衣冠犹似俗，心事独非今。","归去峨嵋路，千峰何处寻。"]},{"t":"幽居","f":"五言律诗","c":["住处必松竹，经年长自閒。","青苔仍有径，乱石更成山。","饮水却馀乐，荷锄谁愧颜。","悠然谢车马，听客到门还。"]},{"t":"小雨 其一","f":"五言律诗","c":["微云兴缥缈，疏雨过森阴。","润积衣裳腻，凉生户牖深。","尘埃聊洗眼，宇宙快开襟。","寂寞城闉暮，归飞见水禽。"]},{"t":"小雨 其二","f":"五言律诗","c":["好风随细雨，萧飒过吾庐。","野兴锄瓜后，衡门隐几初。","积阴生绿缛，清气袭空虚。","耳目遗尘土，还当读我书。"]},{"t":"小雨 其三","f":"五言律诗","c":["宿云留暝色，细雨逼残春。","芳树看红湿，垂杨亦翠颦。","高风吹燕翼，定水涨鱼鳞。","渐恐年华改，桃源忆晋人。"]},{"t":"立春","f":"五言律诗","c":["得新矜白鬓，数九喜和风。","菜甲成春事，郊园付野翁。","天开池水碧，雪尽树梢红。","颇复寻樵隐，柴门步武通。"]},{"t":"挽故相国尚书令忠献公 其一","f":"五言律诗","c":["四转更注意，两朝公受遗。","大明开日月，全德冠皋夔。","已悟骑箕事，犹馀罢市悲。","太常难纪绩，天语诏丰碑。"]},{"t":"挽故相国尚书令忠献公 其二","f":"五言律诗","c":["意气万夫望，衣冠八尺身。","有为悲凤鸟，不作画麒麟。","馀烈周宗近，英威汉相真。","召棠终勿剪，昼锦仰乡人。"]},{"t":"挽故相国尚书令忠献公 其三","f":"五言律诗","c":["殄瘁虚人望，哀荣备宠章。","畴功萧相国，异数郭汾阳。","鼎实宵无味，阶星昼陨光。","惟应文考庙，万岁共丞尝。"]},{"t":"曾鲁公挽诗 其一","f":"五言律诗","c":["扶阳诗礼乐，丞相始安车。","世祚公之鲁，门风行在书。","三朝推帝赍，九叙见民馀。","古有骑箕事，今知定不虚。"]},{"t":"曾鲁公挽诗 其二","f":"五言律诗","c":["云台存画像，毕陌想遗风。","文彩阶符在，仪型岳镇空。","考终方备福，言念始为忠。","今日缁衣美，能明善善功。"]},{"t":"曾鲁公挽诗 其三","f":"五言律诗","c":["南公工说谶，故老笔通灵。","本自符千运，宜然享百龄。","嵩高雄作镇，河润溢为荥。","考卜佳城处，无须石椁铭。"]},{"t":"齐国公主挽诗","f":"五言律诗","c":["汤沐侯家贵，山林主第开。","天孙乌鹊水，萧史凤凰台。","遇事悲风烛，新阡怆劫灰。","清秋降北渚，不奈楚声哀。"]},{"t":"秋园晚步 其一","f":"五言律诗","c":["惨惨高秋兴，萧萧欲暮天。","地荒逢败叶，日下听残蝉。","感物偏无赖，悲秋私自怜。","如今已如此，何待二毛年。"]},{"t":"秋园晚步 其二","f":"五言律诗","c":["摇落西风早，苍茫晚日斜。","木兰休紫艳，篱菊委黄花。","兴似陶潜赋，愁如庾信家。","向来吟思苦，直恐鬓霜华。"]},{"t":"晚步","f":"五言律诗","c":["日没城阴合，人归草露凉。","浅池宜短艇，高树倚胡床。","清啸激秋气，孤吟留月光。","敢言吾独善，鱼鸟正相忘。"]},{"t":"城西晚归南山马上口占","f":"五言律诗","c":["尘土辜双眼，驱驰损壮颜。","夕阳衔远树，马首看南山。","应接都忘倦，神明自觉还。","无心非自强，最识白云閒。"]},{"t":"便风挂帆欣然有作","f":"五言律诗","c":["泛梗江流疾，转蓬风力强。","天时周必复，吾道不终藏。","白鹤先余路，飞乌送客樯。","挂帆资隐几，北走万山苍。"]},{"t":"巢湖","f":"五言律诗","c":["天与水相通，舟行去不穷。","无人能缩地，何术可分风。","宿雾凝深黑，朝曦浴嫩红。","四山千里远，晴晦已难同。"]},{"t":"晨至后园","f":"五言律诗","c":["白露晨已重，晚花秋正繁。","城阴到少息，林下寂无喧。","圃老能呼鹤，樵奴竞戏猿。","山林何异此，机事复谁存。"]},{"t":"寄范佑之","f":"五言律诗","c":["徽宗随武后，相与亦通家。","望气如丰剑，闻名省渥洼。","将门严棨戟，王略尽流沙。","好取封侯印，谁能读五车。"]},{"t":"寄和父","f":"五言律诗","c":["行李资章甫，秋期看海涛。","埃尘乍振袂，淮泗幸容舠。","飏舄双凫健，飞乌五两高。","须君菊花酒，慰此寸心劳。"]},{"t":"寄杨十七","f":"五言律诗","c":["宰邑成三异，吾兄复妙年。","长愁越声短，不似古诗传。","高唱今独步，知音深谓然。","还疑剡溪上，纸贵几多钱。"]},{"t":"寄梅圣俞","f":"五言律诗","c":["独骑驽马出，强逐众人行。","贫始怨寡与，老仍畏后生。","吾子忘年友，新诗独步名。","秋风梦无限，时过许昌城。"]},{"t":"寄王深甫","f":"五言律诗","c":["箕颍多奇士，他年洗耳翁。","古人皆直道，吾子嗣高风。","解榻迎徐孺，名乡礼郑公。","正怜贤太守，心赏与人同。"]},{"t":"寄隐直","f":"五言律诗","c":["远身嗟道敝，筑室笑劳生。","应接知侪俗，浮沈得避名。","陈家星不昧，灌氏水长清。","往事今闾里，悠悠旅客情。"]},{"t":"洞庭寄张四","f":"五言律诗","c":["壤俗三苗旧，湖波八月寒。","天形渐水近，秋气逼枫丹。","漠漠萍号雨，潇潇澧有兰。","东流无限水，一洗故人冠。"]},{"t":"滑州罢为白马县舍弟司法省归寄此诗","f":"五言律诗","c":["散军收棨戟，改邑壮三畿。","太守朝行在，诸曹自免归。","大河终北注，旅雁独南飞。","迟尔宽相忆，他时信息稀。"]},{"t":"送韩太祝罢官归许昌觐","f":"五言律诗","c":["吏课三年最，归装五日粮。","朋情惜分散，子舍想辉光。","泉洁湖波白，春融柳带黄。","因君老莱戏，遥奉使君觞。"]},{"t":"自江南将归先寄和甫 其一","f":"五言律诗","c":["五湖休作客，八月去乘槎。","天地凝秋日，山川照落霞。","寄声西道主，好在嗣宗家。","盛酝重阳酒，登高饮菊花。"]},{"t":"自江南将归先寄和甫 其二","f":"五言律诗","c":["狂直非侪俗，文章念及门。","无成似冯衍，失路比虞翻。","抱瓮机先息，书空事不言。","江南香草地，一一赋荃荪。"]},{"t":"风雨寄张野人","f":"五言律诗","c":["宿雨萍号苦，凄风虎啸频。","喜开虫豸蛰，怅阻物华春。","鸡叫思君子，莺迁忆故人。","泥涂塞车辙，相过独无因。"]},{"t":"寄张六","f":"五言律诗","c":["十里一反顾，去君垂五千。","远身卑湿地，归意泬寥天。","南极多来雁，秋阴减跕鸢。","寄书江汉水，好送北归船。"]},{"t":"寄张宜","f":"五言律诗","c":["屈指张生老，无人事隐沦。","鲸鱼空自饱，章甫向谁亲。","丹荔充庭实，明珠逐贾人。","如何沧海上，甔石一生贫。"]},{"t":"寄张六","f":"五言律诗","c":["君为弃官去，豪气故风流。","无复池中物，真能方外游。","浮生都物变，衰俗使人愁。","闻有桃源路，归来试力求。"]},{"t":"省中寄王平甫","f":"五言律诗","c":["簿领秃千兔，禺中强一餐。","未为勤事吏，空负写书官。","奇兽名天禄，层楼近井干。","林花今正盛，梦想月边寒。"]},{"t":"重寄苏子瞻","f":"五言律诗","c":["空胸迷旧学，华发怅颓龄。","江海容孤翼，云霄寄客星。","未堪循吏传，默守太玄经。","正恐声闻酒，令人醉不醒。"]},{"t":"寄仲冯","f":"五言律诗","c":["府掾西曹贵，星华使节雄。","我行千里镐，即叙百馀戎。","王略持筹内，边山聚米中。","因成率然势，不陈取奇功。"]},{"t":"夏木闻禽","f":"五言律诗","c":["爱此南轩木，亲闻好鸟声。","夏阴双绿缛，幽韵独凄清。","带雾知天晓，因风觉晚晴。","忘机是幽客，相见不相惊。"]},{"t":"挽卢通议 其一","f":"五言律诗","c":["射策兰成岁，归全韦相年。","聪明百龄事，冠带五朝贤。","赐几元知止，临雍尚缺然。","秋风正摇落，哀挽向新阡。"]},{"t":"挽卢通议 其二","f":"五言律诗","c":["山东推望族，泉室閟归真。","善政馀谈舌，清风在缙绅。","薤晞无复露，草弱漫栖尘。","赖有传家庆，光华列世臣。"]},{"t":"唐参政挽诗 其一","f":"五言律诗","c":["天夺悲杨绾，人亡怆魏公。","终疑仁者寿，尚想直臣风。","听履馀荣在，牵裾旧事空。","惟应司隶姓，更使世知忠。"]},{"t":"唐参政挽诗 其二","f":"五言律诗","c":["倜傥先言路，经纶重鼎司。","武文兼二允，爱直见双遗。","无复灵台论，空伤薤露诗。","邢山向郑国，千古意同悲。"]},{"t":"挽冯当世母朱太君 其一","f":"五言律诗","c":["郡封家邑盛，羹遗主恩频。","所以令勤贵，由来得孟邻。","文轩空旧事，吊鹤怪来嫔。","摇落千山暮，陔兰不复春。"]},{"t":"挽冯当世母朱太君 其二","f":"五言律诗","c":["躬绩维公父，平反在不疑。","荣兼綵衣养，孝著白华诗。","黄发全天寿，遗风盛女师。","画輀丹旐远，宁记鹿车时。"]},{"t":"挽王正仲母永寿太君 其一","f":"五言律诗","c":["天锡期颐寿，恩疏石窌封。","母仪兼事事，子贵亦重重。","归旐沧江水，新阡翠岭松。","曾参无所系，不待禄千钟。"]},{"t":"挽王正仲母永寿太君 其二","f":"五言律诗","c":["平日南陔养，诸公为美谈。","儿啼因戏綵，羹遗复调甘。","盛事一知十，修龄百与三。","青乌传吉卜，乔木蔼相参。"]},{"t":"濮王任夫人挽词","f":"五言律诗","c":["思齐疏庆族，圣善积慈恩。","子贵哀荣在，舟移謦欬存。","绋讴悲薤露，象服照鱼轩。","惟有秦原望，东西见寝园。"]},{"t":"挽韩侍郎夫人范郡君 其一","f":"五言律诗","c":["名卿俱令族，庆善集清门。","佩玉师柔训，称诗得妇言。","已嗟封马鬣，不待归鱼轩。","从此公侯事，凄凉属采蘩。"]},{"t":"挽韩侍郎夫人范郡君 其二","f":"五言律诗","c":["夫尊因受郡，子贵亦通朝。","象服违偕老，幽宫不复朝。","长川空滚滚，落叶自飘飘。","哀挽青郊道，悲风送大招。"]},{"t":"西戎","f":"五言律诗","c":["旄头占虏候，鸣镝射单于。","哀死知明主，和亲愧腐儒。","边锋少南牧，天马自东趋。","看撤山西戍，无劳议远图。"]},{"t":"晚过西湖","f":"五言律诗","c":["落日微雨好，浮云近水多。","空濛乱林树，涵泳著星河。","赏极兴不尽，迹归心更过。","犹须明月夜，濯足弄金波。"]},{"t":"泛舟西湖 其一","f":"五言律诗","c":["靡亹蘋萍合，夤缘岛屿深。","操舟非有术，鉴水会清心。","老树成重盖，初荷散万簪。","名园皆有主，费日试幽寻。"]},{"t":"泛舟西湖 其二","f":"五言律诗","c":["懒意适自强，旧游疑触新。","如从剡溪客，忽晤武陵人。","钟磬高低寺，渔樵来去津。","凉风水云合，天半是鱼鳞。"]},{"t":"郑侍郎挽词 其一","f":"五言律诗","c":["置驿无留客，名卿拟上公。","应惟泣遗爱，竞欲颂宽中。","赐履灵台隔，开阡梦泽空。","秋音送归旐，依约认樵风。"]},{"t":"郑侍郎挽词 其二","f":"五言律诗","c":["治狱馀阴德，哀矜出片言。","千金无重比，驷马见高门。","星落林乌暝，愁悲薤露喧。","江风伤远目，楚些一招魂。"]},{"t":"送张六入浙东","f":"五言律诗","c":["君侯曾一仕，已作弃官归。","又欲过吴市，还愁脱赐衣。","春风解冰雪，泽国尽芳菲。","相望不可及，孤云天外飞。"]},{"t":"上清宫花木自夏及秋相续","f":"五言律诗","c":["信此神仙地，经时玩物华。","残红未零落，暗紫续矜夸。","扫石分文绣，开林碎晚霞。","秋风兰菊茂，此去有黄花。"]},{"t":"将去上清宫题梧桐","f":"五言律诗","c":["旧日见春华，圆阴羽盖斜。","野轩何必扫，小径故从遮。","秋气先摧叶，春风别有花。","野夫心好静，异日到山家。"]},{"t":"九日","f":"五言律诗","c":["九日秋萧瑟，登高亦少欢。","黄花宜澹泊，碧树早凋残。","醉舞乌纱落，弹歌短剑寒。","可怜西北望，白日远长安。"]},{"t":"九日寄江北兄弟","f":"五言律诗","c":["登高虽有兴，羁旅亦消魂。","插鬓茱萸细，题诗蟋蟀喧。","黄花一樽酒，斜日最高原。","回首江天迥，翩翩塞雁翻。"]},{"t":"张比部景真挽诗 其一","f":"五言律诗","c":["埋轮负壮志，持节向炎墟。","反户惊殊俗，彤襜岂定居。","跕鸢愁瘴雾，断雁哭来书。","天理真冥漠，谁能问太虚。"]},{"t":"张比部景真挽诗 其二","f":"五言律诗","c":["五岭瘴疠地，宦游前事存。","求为勾漏令，卧念少游言。","夫子独不返，壮心谁复论。","凄凉大招赋，不见入修门。"]},{"t":"苏度支挽诗 其一","f":"五言律诗","c":["翰墨兼能事，功名自壮图。","云霄曾几许，意气即通衢。","埋玉情何已，修文理不诬。","敢忘徐稚礼，絮酒望江湖。"]},{"t":"苏度支挽诗 其二","f":"五言律诗","c":["前年伯鸾死，卜葬近要离。","今日延陵墓，仍书季子碑。","人琴俱已矣，林壑助悽其。","心许千金剑，终当挂树枝。"]},{"t":"建公挽诗","f":"五言律诗","c":["燕祺欢受福，阳禄痛离灾。","胙土乘初载，宾天遽不回。","弄璋迷梦幻，壮发变尘埃。","唯有华封祝，能宽上圣哀。"]},{"t":"题鲁氏老桧堂","f":"五言律诗","c":["当日山林客，移根近小轩。","树阴今百尺，人世亦曾孙。","坚节寒逾甚，清风老更存。","犹馀双白鹤，终恋主人恩。"]},{"t":"柏悦堂 其一","f":"五言律诗","c":["往说齐侯寝，此堂申甫馀。","千龄长秀耸，众木既消除。","杖履每多兴，冰霜深自如。","凉风破蒸暑，真赏复谁须。"]},{"t":"柏悦堂 其二","f":"五言律诗","c":["华堂柏两株，清景喜多馀。","密影随步武，凉风自扫除。","苍颜师尚父，劲节蔺相如。","寄谢繁华子，荣枯可立须。"]},{"t":"夜凉","f":"五言律诗","c":["稀星映斜汉，孤月静前轩。","意喜凉风过，遥看碧树翻。","劳生共裘葛，辞秩愧田园。","高枕息群动，吟蛬依草根。"]},{"t":"自蔡河之陈州","f":"五言律诗","c":["扁舟去凫雁，川路正龙蛇。","日色暝如午，风鸟端复斜。","渐渐过陇麦，短短被堤花。","涕泪元无极，那堪视物华。"]},{"t":"重伤胡二","f":"词","c":["逝水竟不复，死生嗟可怜。","所思今已矣，归使一悽然。","尚想飞凫?，终辜忆戴船。","神交如有验，会付广陵弦。"]},{"t":"五龙井祷雨","f":"五言律诗","c":["汤年不过此，丘祷亦何频。","石井无多水，泥蟠讵有神。","舞雩声寂寞，剪爪事酸辛。","万古为霖意，长嗟傅野人。"]},{"t":"苦寒","f":"五言律诗","c":["苦寒殊不意，衰老若为谋。","赐隔青绫被，贫馀白罽裘。","蛰龙才自脱，过雁可深忧。","靳靳西颓日，墙阴肯为留。"]},{"t":"秋过荐福院竹亭 其一","f":"五言律诗","c":["入秋才一到，风物已凄凉。","旧筱全侵席，新梢乱出墙。","萧萧吹叶雨，稍稍坠枝霜。","为有留人意，嘉游不可忘。"]},{"t":"秋过荐福院竹亭 其二","f":"五言律诗","c":["开门金锁碎，绕径碧檀栾。","钟呗风馀韵，房栊日暮寒。","老僧长入定，好鸟故相看。","何事扁舟客，殷勤觅钓竿。"]},{"t":"济川亭 其一","f":"五言律诗","c":["谁谓此池小，远将天汉通。","分明涵列宿，迢递引来风。","松竹凌虚碧，轩窗倒影红。","高明推李杜，不负傅岩功。"]},{"t":"济川亭 其二","f":"五言律诗","c":["自倚杖九节，时携书一通。","石桥照影水，竹槛纳凉风。","高柳参天碧，新莲映日红。","由来帝何力，况数济川功。"]},{"t":"晒书","f":"五言律诗","c":["幽事随时有，移书晒日华。","囊开鱼蠹字，眼晕石榴花。","病忘多三箧，劳心愧五车。","赐书仍有品，前辈羡吾家。"]},{"t":"夜过曾孚先","f":"五言律诗","c":["索我形骸内，从君里巷居。","度阡仍越陌，酌醴更焚鱼。","残雪春泥熟，青灯缺月初。","谁能惮乘兴，叹息岁将除。"]},{"t":"将赴官庐州寄张四隐直二首 其一","f":"五言律诗","c":["一为弹冠仕，遂废东皋田。","不至二千石，行登四十年。","羁游无定许，鬓发欲苍然。","万里南江路，春风棹客船。"]},{"t":"将赴官庐州寄张四隐直二首 其二","f":"五言律诗","c":["江路西南永，风波岁月淹。","赖君同此役，久客复谁嫌。","榜叟誇忠信，津童识孝廉。","云山仍在眼，诗兴力能兼。"]},{"t":"贺隐直","f":"五言律诗","c":["举国皆儒服，吾人智有馀。","焚舟济河后，埋剑发硎初。","天路骞黄鹄，云涛纵巨鱼。","殷勤故人意，青眼看乡书。"]},{"t":"送隐直归扶离","f":"五言律诗","c":["羁旅自无友，非因七不堪。","逃空见人喜，失学向君惭。","贫病意不展，滞留情未甘。","相从欲有问，空法本传南。"]},{"t":"雪中忆隐直","f":"五言律诗","c":["北风吹朔雪，遥想度关西。","覆阁眼初熟，登楼望独迷。","巧妆梅意密，偏压柳条低。","竟日思君饮，空怜骏马蹄。"]},{"t":"哭张隐直 其一","f":"五言律诗","c":["结友儿童岁，对门兄弟辞。","存亡殊不意，晚暮可胜悲。","宰木归吴远，輀车出剑迟。","善人鲜百福，神理傥吾欺。"]},{"t":"哭张隐直 其二","f":"五言律诗","c":["二星占使者，九折见忠臣。","白发犹强力，青云早致身。","劳生真梦寐，过事悉埃尘。","已矣寝门泪，石交兼懿亲。"]},{"t":"占晴 其一","f":"五言律诗","c":["南国无全腊，江天可喜晴。","山林开雪色，凫雁与风声。","春物催群动，年华强旅情。","无人同此酒，叹息滞蛮荆。"]},{"t":"占晴 其二","f":"五言律诗","c":["蒸湿何由解，暄和自不禁。","片云常蔽日，小雨不成霖。","蚊蟆晴明地，蛟龙老病心。","雄风不易得，无处可披襟。"]},{"t":"雪晴","f":"五言律诗","c":["山雪喜初霁，意行因肆观。","岩光花半散，峰势玉新攒。","鸟去树冰落，水来溪舍寒。","还愁向融散，立到夕阳看。"]},{"t":"还郡寄洛中诸贤","f":"五言律诗","c":["虽勤车马役，而与故人同。","濯热宜清洛，忘饥为碧松。","御风思禦寇，缩地忆壶公。","待我成仙术，相过岂有穷。"]},{"t":"送江淑寺丞弃官归江州","f":"五言律诗","c":["时事不可愿，还家方自由。","看山一长啸，饮水亦消忧。","林竹通邻里，陔兰洁膳羞。","还将计然策，江上倚扁舟。"]},{"t":"霍邱谢令寺丞","f":"五言律诗","c":["明府双飞凫，南归鸿鹄俱。","东风解冰雪，春水渡江湖。","光禄诗为乐，渊明酒自娱。","公田皆种秫，三径更何须。"]},{"t":"送王肃侍禁新安监酒","f":"五言律诗","c":["丹穴凤皆好，蓝田玉自温。","流传洛生咏，叹赏贵公孙。","好事欲成癖，著书经闭门。","看君桂枝擢，禄仕复谁论。"]},{"t":"山寺","f":"五言律诗","c":["叠嶂横秋水，招提隐半峰。","白云迷到路，晓日自鸣钟。","法会樵渔熟，斋时鸟雀慵。","试寻方外士，系马就长松。"]},{"t":"画雪扇子","f":"五言律诗","c":["洒落瑶花薄，苍茫杀气深。","因风惊拂面，濯热幸开襟。","夜色非关月，朝云不待阴。","秋风来应起，好在郢中吟。"]},{"t":"晓起东园","f":"五言律诗","c":["禽鸣知欲曙，野客自晨兴。","春草生三径，朝光下九层。","园林问圃老，笋蕨待岩僧。","即此甘幽屏，趋时要未能。"]},{"t":"古桧亭 其一","f":"五言律诗","c":["散栎厌为社，枯梧非有神。","一身具松柏，千岁作秋春。","风影日亭午，露香宵向晨。","唯应仙鹿迹，不悔白头新。"]},{"t":"古桧亭 其二","f":"五言律诗","c":["昔闻上升桧，传作亳宫神。","念此亦千载，玩之经一春。","凉蝉号永昼，独鹤起清晨。","谁与画屏幛，长令水墨新。"]},{"t":"上櫰","f":"五言律诗","c":["人世南柯梦，看君葺旧居。","小庭长汛扫，暇日省文书。","黑叶生烟外，黄花过雨馀。","那知山谷兴，不向市朝疏。"]},{"t":"登楼","f":"五言律诗","c":["溪谷含冰雪，川原见草芽。","春生三峡水，日照万人家。","时节长如此，风光会有涯。","唯应多美酒，厌看海棠花。"]},{"t":"雨中过汜水关入巩县","f":"五言律诗","c":["泥涂出关恶，风雨过云寒。","悬水馀百仞，层峰知几盘。","攀跻头目眩，揭厉衣裳单。","稍出万山外，始知人世宽。"]},{"t":"次韵谢三利涉寺见寄","f":"五言律诗","c":["众水会苍山，僧房积翠间。","夕阴留到客，清暑独开关。","月出乱峰白，天明游子还。","他时望君意，馀恨不同攀。"]},{"t":"题利涉寺","f":"五言律诗","c":["云水上方居，迢迢百尺馀。","水光摇几席，岚翠彻窗疏。","鹤树追前佛，隆中问结庐。","已知禅寂意，仍得揣摩书。"]},{"t":"哭王子直 其一","f":"五言律诗","c":["积水忽变浊，聚星无复光。","风流都灭尽，天理竟冥茫。","过事皆陈迹，馀哀祇泪行。","遥怜转麈柄，顾影夜灯旁。"]},{"t":"哭王子直 其二","f":"五言律诗","c":["衰老惜年岁，羁孤慕友生。","一哀谁为恸，百志尔无成。","弓剑轻前敌，诗书足自名。","人皆期不朽，持此傲公卿。"]},{"t":"荷花","f":"五言律诗","c":["白水满方塘，荷花五月芳。","弄珠圆不定，濯锦冷逾光。","香忆风醒酒，声宜雨送凉。","扁舟学骚客，葺室近沧浪。"]},{"t":"黄州临皋亭","f":"五言律诗","c":["远国江千里，荒城水一涯。","居人愁避虎，过客竞乘槎。","秋雨吹天暮，寒涛浸日车。","从来迁谪地，卑湿是长沙。"]},{"t":"野竹亭","f":"五言律诗","c":["劲节四时好，此君常眼青。","影摇金破碎，声动玉珑玲。","方丈尘埃绝，高斋醉梦醒。","由来谋野意，不异在林坰。"]},{"t":"闻西戎乞降","f":"五言律诗","c":["玉关依斥堠，荒服祀春秋。","干羽由来事，桑榆尚可收。","发书迎宝马，锡贡入貂裘。","高枕兴王世，吾生免外忧。"]},{"t":"冬夜赏月","f":"五言律诗","c":["晕逐阴风起，光随凛气多。","霜应摧桂树，冰恐彻天河。","池镜初容鉴，窗棂亦戏磨。","关山千里雪，此夕共金波。"]},{"t":"雪夜月中","f":"五言律诗","c":["雪霁流云尽，天虚片月升。","气清群玉府，光彻满壶冰。","过雁明可数，啼鸟寒不胜。","山阴自此去，野兴岂难乘。"]},{"t":"玩芳亭","f":"五言律诗","c":["谁与玩芳草，慨然思古人。","东风千里目，红蕊一城春。","贺燕自高下，浮云无旧新。","南山际沧海，更觉尔为邻。"]},{"t":"留别诸兄弟","f":"五言律诗","c":["羁游路万里，物色共悽然。","霖雨伤秋意，西南接漏天。","壶公缩地远，列子御风旋。","信有神仙术，诸公一见怜。"]},{"t":"暂之霅上留别一二兄弟","f":"五言律诗","c":["回首嗟行役，吟诗怆物华。","西风凋木叶，客子去天涯。","日暮看边雁，江秋见海槎。","重阳谁对酒，野菊自开花。"]},{"t":"春日登楼 其一","f":"五言律诗","c":["水国春归晚，晴楼旅望赊。","青丝垂地柳，白朵出墙花。","听鸟参人语，看云任帽斜。","沧浪殊不极，春色故无涯。"]},{"t":"春日登楼 其二","f":"词","c":["野性耽章句，春容看旅愁。","眼前都俗物，天外倚高楼。","芳草茫茫绿，清淮??流。","片云还欲雨，怅望恐花休。"]},{"t":"绿野亭偶题 其一","f":"五言律诗","c":["记得春晚句，缘情因谢公。","名贤共标准，清境定无穷。","乐矣登临际，悠然坐啸中。","壶觞聊发兴，随俭亦随丰。"]},{"t":"绿野亭偶题 其二","f":"五言律诗","c":["倚郭遍禾黍，安知私与公。","为农亦可乐，遇岁不终穷。","累榭白云外，壤歌明月中。","谁言鲁酒薄，自觉胜新丰。"]},{"t":"日晚步过孙监丞","f":"五言律诗","c":["夕阳喧鸟雀，幽径入蓬蒿。","于此兴不浅，行吟殊未劳。","市朝移俗态，麋鹿共吾曹。","稍稍钟声暝，林梢白月高。"]},{"t":"望华山","f":"五言律诗","c":["荆山连太华，青翠望难分。","岭首明新旭，山腰暝白云。","玉攒光自照，波荡势成文。","应接宁知倦，清辉远送君。"]},{"t":"凤翔官宅园亭","f":"五言律诗","c":["退食自閒暇，空堂仍集虚。","秋林长费扫，寒草不教锄。","移石改迂径，拂墙看旧书。","枝栖亦云稳，何用忆吾庐。"]},{"t":"马当山","f":"五言律诗","c":["云壑断无土，江流横倒山。","蛟涎晴出没，鸟羽倦飞还。","神禹遗疏凿，天机藉险艰。","长风且破浪，帆席慰愁颜。"]},{"t":"送毕长官","f":"五言律诗","c":["铜墨非君志，仙凫为我来。","三年话倾盖，十日算衔杯。","许与羞垂白，飞腾指上台。","倚门方有待，未觉厌京埃。"]},{"t":"送郑推官","f":"五言律诗","c":["此邦人事少，离恨不关心。","顿与吾子别，如何旅思深。","暖风随跃马，永路变鸣禽。","蓬鬓添衰白，知予厌滞淫。"]},{"t":"咏雪","f":"五言律诗","c":["北风吹朔雪，楚塞亦凝寒。","天地浮云满，江湖行路难。","醉宜乘马出，高爱倚楼看。","会是丰年候，居人意似宽。"]},{"t":"书堂对雪","f":"五言律诗","c":["天寒不成寐，看雪坐清晨。","默怪人声绝，都迷物态真。","璇宫寒烁目，琪树静无尘。","信有昆崙圃，神游属此身。"]},{"t":"和裴库部诸家雪 侯家","f":"五言律诗","c":["裘马寒逾壮，歌钟暝未閒。","排云朝象阙，踏冻猎黄山。","上客珠装履，妖姬玉缀鬟。","园林通夜赏，洞户不须关。"]},{"t":"和裴库部诸家雪 山家","f":"五言律诗","c":["云暗峰疑断，林长路稍迷。","庭隅时卧鹿，旁舍远听鸡。","隐几添樵火，应门倚杖藜。","儿童别村至，薄酒自提携。"]},{"t":"和裴库部诸家雪 酒家","f":"五言律诗","c":["缭径集瓶罂，江楼倚上层。","青帘吹淡墨，翠幕映飘灯。","劝客寒威壮，歌时岁事登。","十千赊可得，不恨价仍增。"]},{"t":"和裴库部诸家雪 猎家","f":"五言律诗","c":["寒事轻杯酒，晨装急制衣。","狐麋寻去迹，鹰隼竞横飞。","沙路浓随马，风毛盛合围。","兴酣生鼻火，狂发会忘归。"]},{"t":"和裴库部诸家雪 樵家","f":"五言律诗","c":["山木琼瑶合，溪风虎豹哀。","旧林迷处所，破斧独归来。","世路深泥滓，生涯半死灰。","谁怜廊庙语，正复此遗材。"]},{"t":"和裴库部诸家雪 船家","f":"五言律诗","c":["云白连沙渚，风高杂浪花。","解帆依下雁，沽酒看栖鸦。","篷响投珠乱，门攲堕剑斜。","山阴路不远，去问戴逵家。"]},{"t":"雪后 其一","f":"五言律诗","c":["高城催戍鼓，病枕听哀鸿。","洒竹萧萧雪，开门峭峭风。","消忧樽酒绿，久雨烛花红。","旅梦还知路，孤舟向剡中。"]},{"t":"雪后 其二","f":"五言律诗","c":["朔雪冻乾坤，黄云昼景昏。","宿酲犹恋酒，静卧亦开门。","乌鹊时时语，松篁处处翻。","问知淮水冻，不复渡头喧。"]},{"t":"陆子履有诗赠行次韵留别","f":"五言律诗","c":["尚白不自悟，愧君称绝伦。","高秋独去国，下水不留人。","菊秀鸿初过，鱼肥稻已新。","淮山见明月，千里最情亲。"]},{"t":"留别傅钦之","f":"五言律诗","c":["驱车长值险，投足正临深。","白首抱壹意，故人知此心。","巢禽欢避弋，辙鲋偶为霖。","去矣江湖兴，凄然东武吟。"]},{"t":"苦热 其一","f":"五言律诗","c":["炎晖不可避，郁郁度朝晡。","飞鸟有时堕，高林无事枯。","形骸等外物，橐籥任洪炉。","正有捐尘浊，东浮万里桴。"]},{"t":"苦热 其二","f":"五言律诗","c":["炎晖共兹世，南纪独何偏。","天地大炉耳，江湖沸鼎然。","鱼龙危失所，黍稷恐无年。","浩荡思雷雨，长吟云汉篇。"]},{"t":"画鹤","f":"五言律诗","c":["置此怜神骏，三年故不飞。","轩车宁假宠，野客会忘机。","燕雀那相笑，凫鹥直自肥。","蓬莱千万里，正想玉为衣。"]},{"t":"得杨十七书见报所居近种花木诗","f":"五言律诗","c":["堪忧虽陋巷，寓兴即名园。","似得壶公乐，如吹黍谷暄。","艳花争献笑，芳草共忘言。","近种南轩竹，春来亦有孙。"]},{"t":"眼昏","f":"五言律诗","c":["因循衰便至，邂逅眼成昏。","稍与诗书隔，初惭长老言。","谈空迷起灭，蝇翼竞飞翻。","懒卧称长策，深居欲杜门。"]},{"t":"登浴室院阁 其一","f":"五言律诗","c":["秋霁登临好，危栏百尺梯。","层城斜照里，双阙五云西。","杂树黄映绿，生烟高复低。","章台少年子，走马锦障泥。"]},{"t":"登浴室院阁 其二","f":"五言律诗","c":["稍出红尘外，方知万象虚。","林端辨远水，楼角怪行车。","灯续黄金像，香馀贝叶书。","谁能捐世事，即地亦山居。"]},{"t":"中夜见月","f":"五言律诗","c":["月午四邻静，高斋人寂然。","虚空时有警，影响善惊眠。","宿羽移深树，商胡惯夜船。","无云更可恨，珍重此婵娟。"]},{"t":"新月","f":"五言律诗","c":["稍见桑榆上，还沈河汉西。","气凉知露白，天阔见星低。","静色馀帘额，回光射鸟栖。","城乌偏可恨，到晓不休啼。"]},{"t":"次韵和黄朝议 其一","f":"五言律诗","c":["下武新周烈，讴歌属禹谟。","恭闻始元诏，远绍帝轩图。","山海无加赋，戎胡遂息徒。","英风逾草偃，俯仰逮樵苏。"]},{"t":"次韵和黄朝议 其二","f":"五言律诗","c":["已作华颠老，欣闻紫诏新。","经纶兼事事，哀痛及人人。","愿辍须臾死，求观富寿民。","短歌随击壤，感动不无神。"]},{"t":"伤丁元珍学士","f":"五言律诗","c":["休沐非连骑，投沙迫去身。","似鸮忧鵩鸟，比鹤望乡人。","梦与江湖隔，情存翰墨新。","定交相得晚，抚事亦酸辛。"]},{"t":"喜雨","f":"五言律诗","c":["山雨来何暮，高天始震雷。","江声翻滟滪，水气逼昭回。","洒落芳年晚，空凉醉眼开。","蛟龙定神宅，蜗角更谁猜。"]},{"t":"漫成","f":"五言律诗","c":["经旬柳已绿，过雨草齐生。","无事观儿戏，閒游识鸟情。","看花低帽立，弄水棹舟行。","宦学都如梦，浮生底自名。"]},{"t":"次韵和司法掾陈郛","f":"五言律诗","c":["晚得诗人赋，长谣长者言。","坐曹凉雨过，归舍暮禽喧。","交态伤贫富，时情任轾轩。","怀归空有梦，郢路属营魂。"]},{"t":"送慧思归吴","f":"五言律诗","c":["尘埃十年梦，江海一身归。","境与夙心会，事容前日非。","连山横远势，定水湛明辉。","别后相望处，云孤雁自飞。"]},{"t":"奠昭禅师","f":"五言律诗","c":["昭公不住世，岑寂白莲宫。","煮水终还冷，浮云本自空。","诸天方丈室，万事百年翁。","俯仰成今昔，萧萧鹤树风。"]},{"t":"送僧子南","f":"五言律诗","c":["脱身游万里，空手出长安。","犹以抱琴乐，不知行路难。","春归吴国远，水满紫溪寒。","越俗今章甫，疑师不著冠。"]},{"t":"宋门城下新居","f":"五言律诗","c":["颇习田野事，偶居朝市间。","前尘应妄想，旧观辄来还。","甘井如汲涧，高城疑望山。","更怜车马绝，日在掩柴关。"]},{"t":"新居","f":"五言律诗","c":["举世同逆旅，此身那拙谋。","趣营容膝地，适似种瓜侯。","药饵扶多病，躬耕强隐忧。","弹冠仍应客，车马肯淹留。"]},{"t":"雪后行小园","f":"五言律诗","c":["晚照开霁色，闭园幽事增。","树摇风落雪，池涨水浮冰。","鹊乱声已变，鸢飞谁为矜。","风光看满眼，取醉此吾能。"]},{"t":"过丁晋公旧园","f":"五言律诗","c":["宁知陵谷变，遂见曲池平。","乔木祇益老，储胥空复情。","废墀盈叠藓，颓榭迹微行。","桑霍为厚戒，千秋馀叹声。"]},{"t":"雪夜酌酒","f":"五言律诗","c":["雨雪寒休市，春泥早闭门。","严城深窈窕，孤月静黄昏。","栖翼此中树，高舂何处村。","物容烦应接，乘兴即开樽。"]},{"t":"送雍元直使浙右","f":"五言律诗","c":["诏给四封传，自乘千里船。","云山深发兴，秋物正萧然。","零雨随持节，惊涛避执鞭。","鲈肥稻米白，胜事奈君偏。"]},{"t":"引泉","f":"五言律诗","c":["春池冻已消，泉落白鱼跳。","石浅喧鸣玉，沙虚没暗潮。","晚寒妨濯足，竟日欲平桥。","最爱临波柳，东风万万条。"]},{"t":"金凤花","f":"词","c":["妖娆如自媚，红白竞为娱。","共笑翔千仞，犹疑将九雏。","轩墀蒙?睐，风雨易泥涂。","静扫苍苔地，还令近酒壶。"]},{"t":"景潮亭","f":"五言律诗","c":["泽国水遥远，归舟亭短长。","他方向夕景，此地正朝阳。","物色桑榆上，风波凫雁行。","临流问渔父，好在濯沧浪。"]},{"t":"退朝观御沟上杂花赠陆四","f":"五言律诗","c":["沟水去无穷，宫花映日红。","惜阴犹宿露，照影独衰翁。","燕语晴明外，风香锦绣中。","为非温室问，心赏幸君同。"]},{"t":"上三山矶","f":"五言律诗","c":["江湍趋绝壁，山木映云涛。","野路青冥近，孤舟应接劳。","鱼龙防碎首，鸟兽几亡曹。","生事垂堂戒，愁心欲二毛。"]},{"t":"过龙眼矶","f":"五言律诗","c":["洪波浮一叶，弱发引千钧。","虎豹公横道，蛟龙喜得人。","强颜犹失色，乘险屡伤神。","回首双凫翼，随波愧此身。"]},{"t":"送郑五下第西归","f":"五言律诗","c":["万里河西路，怜君徒步归。","游人并塞少，落叶待霜飞。","相得不恨晚，知音深谓稀。","壮心须慷慨，勿学泪沾衣。"]},{"t":"送人之官岭南","f":"五言律诗","c":["过岭几千里，孤城近海涯。","地温饶瘴毒，民恶半蛮家。","并日初开市，非春亦有花。","知君望星斗，西北认京华。"]},{"t":"和孙少述中秋 其一","f":"五言律诗","c":["月出东山表，遥思泽国秋。","绿云孤镜上，透水大珠浮。","重露梧桐落，微寒蟋蟀愁。","我时携客饮，浮白最高楼。"]},{"t":"和孙少述中秋 其二","f":"五言律诗","c":["竟夕云四敛，始知天意偏。","西风不胜冷，亭午更添圆。","老发缘诗苦，秋怀得酒便。","君居江浦上，望我想依然。"]},{"t":"春日野次","f":"五言律诗","c":["溪云晴漠漠，野日昼阴阴。","燕翼飞高下，花房乱浅深。","和风快吹面，净水喜清心。","极目伤千里，曾无枫树林。"]},{"t":"南原","f":"五言律诗","c":["南原殊可望，桑柘百家村。","紫赤春晴气，青葱旧烧痕。","远川飞雁鹜，平壤牧鸡豚。","更待花如织，临高置一樽。"]},{"t":"远信","f":"五言律诗","c":["清秋万里梦，久客一封书。","长日看鸿雁，呼儿问鲤鱼。","凉风郢路远，落叶洞庭初。","无限归凫翼，南飞最跂予。"]},{"t":"金沙花","f":"五言律诗","c":["苒弱金沙树，花奇名字珍。","移从今日晚，恨失去年春。","嫩绿藤垂架，深红棘刺人。","东风会入手，照眼万枝新。"]},{"t":"赠邻翁","f":"五言律诗","c":["与彼茅茨接，看渠卜筑初。","丈人真耄矣，孺子复何如。","翁且勤杯酒，儿教读道书。","衡门来往近，时为过吾庐。"]},{"t":"初晴赠某翁","f":"五言律诗","c":["云随夜色改，日与曙光升。","已变前除雪，犹馀北户冰。","鸿飞知适意，鹤语若矜能。","天事宽羁旅，幽人亦有朋。"]},{"t":"晨起","f":"五言律诗","c":["断角续鸣钟，惜时春已空。","晓星犹伴月，早雨不禁风。","眠食须颐老，衣冠强自公。","庭阴全绿色，无复见残红。"]},{"t":"挽胡元夫母寿安县太君二首 其一","f":"五言律诗","c":["应妪金琛社，桓釐邑致膰。","母仪真盛德，禄养现兴门。","尚想君羹遗，那悲口泽存。","苍山松梓暮，吊鹤去翩翻。"]},{"t":"挽胡元夫母寿安县太君二首 其二","f":"五言律诗","c":["清德畏人知，传家赖母慈。","何时丹桂擢，相戒白华诗。","戏綵欢无极，藏舟事密移。","千钟已不暨，后日可胜悲。"]},{"t":"孟冬","f":"五言律诗","c":["十月江南暑，居人尚葛衣。","秋花看不绝，沙鸟听忘归。","气郁愁成瘴，霜轻叹失威。","异方羁旅思，岁事每多违。"]},{"t":"午睡","f":"五言律诗","c":["浮云蔽白日，风雨近秋天。","车马欲安适，户庭方阒然。","世涂高枕外，身事曲肱前。","似觉松生腹，迢遥不记年。"]},{"t":"古槐二首 其一","f":"五言律诗","c":["地有藏丹井，人传不死乡。","南柯经腊李，黑叶胜枯杨。","甲错龙鳞断，花明鼠耳黄。","离宫缘望幸，仙桧俨相望。"]},{"t":"古槐二首 其二","f":"五言律诗","c":["仙人鍊形骨，枯槁不知年。","秀色倏还观，阳和仍宛然。","今古山川异，乾坤雨露偏。","东阳无歇息，生意会绵绵。"]},{"t":"复和前韵二首 其一","f":"五言律诗","c":["遗履事悠远，白云飞帝乡。","潜真社寄栎，观化肘生杨。","秀叶发垂绿，杂英牙变黄。","牺尊与沟断，俗骨尔何望。"]},{"t":"复和前韵二首 其二","f":"五言律诗","c":["父老见枯朽，皆从童稚年。","孙枝复秀色，仙事故依然。","巢鹤千龄异，源泉一溉偏。","颇笑海棕陋，崎岖留在绵。"]},{"t":"秋暑呈冯守","f":"五言律诗","c":["秋律何时效，炎云莫肯阴。","烈风长鼓鞴，去水亦流金。","藿食无求饱，单絺不自任。","开怀幸宽政，事省得清心。"]},{"t":"宿荆门","f":"五言律诗","c":["山行厌曲折，小邑正欢哗。","流水才一带，居人聚两涯。","池偏饶草木，山晚聚云霞。","郢路定未远，梦魂还到家。"]},{"t":"西湖水决","f":"五言律诗","c":["平原出大水，蚁壤溃长汀。","舟楫疑藏壑，波涛骇建瓴。","蛟龙随过雨，鱼鳖问沧溟。","闻道蓬莱水，桑田亦屡经。"]},{"t":"素屏","f":"五言律诗","c":["陋室避尘杂，深居惟此屏。","虚空自生白，朴素拟忘形。","画手山林迹，先生几杖铭。","长来师绝学，未肯事丹青。"]},{"t":"烧残树","f":"五言律诗","c":["异时龙起蛰，一夕鸟焚巢。","摧落残孤干，荒凉委近郊。","莓苔深蚁穴，风雨诧神交。","尚想知音遇，空心或远庖。"]},{"t":"避风","f":"五言律诗","c":["南风多叠浪，逆水暂回船。","画鹢秋相对，沙鸥静独眠。","微明见云树，孤绝问人烟。","吾道常如此，听歌枉渚邅。"]},{"t":"同原甫咏秘阁诏藏古器图","f":"五言律诗","c":["昔占金宝气，天瑞告成功。","绘事今时绝，书文自古同。","剖钩记巫锦，按刻异桓公。","尘世无由睹，昆山策府中。"]},{"t":"王广渊郎中挽诗","f":"五言律诗","c":["家本秦川贵，旧传淮水占。","省郎时望在，公族主恩兼。","转烛风何急，栖尘草正纤。","襄阳今罢市，涕泪万人沾。"]},{"t":"刘彝学士挽诗","f":"五言律诗","c":["传闻四君子，同是五经师。","独以功名误，空思俎豆为。","不成宣室召，长负雁门期。","赖有铭泉室，千秋无愧词。"]},{"t":"重过观音精舍旧读书房","f":"五言律诗","c":["往作关东客，来携一束书。","旅人观所主，野性乐玄虚。","过事都如梦，精庐宛若初。","空怜两蓬鬓，萧飒十年馀。"]},{"t":"过雍熙院兴师房","f":"五言律诗","c":["习静未离解，悟空犹著禅。","斋居性所近，古寺境萧然。","瓶水寒生冻，炉香暝袅烟。","老僧眉雪白，晏坐已忘年。"]},{"t":"夜雨","f":"五言律诗","c":["天暝龙蛇化，风高鸟兽呼。","尘嚣一洒尽，暑病暂时苏。","电火将焚野，雷车若隘涂。","坐疑陵谷变，明发蹈江湖。"]},{"t":"江上夜雨","f":"五言律诗","c":["江黑暮潮生，云深骤雨倾。","风波两舟语，灯火一川明。","短夜苦难曙，羁怀方未平。","空怜梦中路，依约尽归程。"]},{"t":"庆寿挽诗二首 其一","f":"五言律诗","c":["史占书五鹿，世德活千人。","孝养东朝盛，徽音赤管新。","濯龙虚望幸，茧馆不知春。","历数姜任事，宁如复辟辰。"]},{"t":"庆寿挽诗二首 其二","f":"五言律诗","c":["卤簿严仙仗，笳箫去掖门。","昼閒长乐卫，春寂灞陵园。","壹德诒谋地，群生顾复恩。","神游馀仿像，日入际昆崙。"]},{"t":"营冬二首 其一","f":"五言律诗","c":["羁旅殊多事，崩腾欲老身。","连年俱异邑，几地愧邻人。","板屋秦诗旧，衡门泌水新。","何时仲长子，卜筑离风尘。"]},{"t":"营冬二首 其二","f":"五言律诗","c":["薙草元留径，开窗祇近檐。","成冬须少有，为客未尝淹。","朋旧看都绝，诗书剩欲嫌。","自知疏懒剧，决意老幽潜。"]},{"t":"思归","f":"五言律诗","c":["扁舟到北郭，屣履向东门。","不改蓬蒿陋，犹怜松菊存。","因秋动归兴，值物怆离魂。","早晚城头月，呼儿坐小轩。"]},{"t":"杨花","f":"五言律诗","c":["不分春色晚，杨花意气骄。","吹嘘轻一羽，容易点层霄。","细细穿檐隙，姗姗学舞腰。","暂来幽僻地，还复去人遥。"]},{"t":"移居观音寺","f":"五言律诗","c":["栖息避城市，尘埃将浼人。","虚空见佛性，简傲得吾真。","霜过草木改，斋馀鸟雀驯。","席门常昼闭，谁与驻车轮。"]},{"t":"题陕西图三首 其一","f":"五言律诗","c":["干戈今日事，关塞此图看。","白日长安近，苍山垄坂寒。","由来名百二，自古有艰难。","指以安西道，凝情意据鞍。"]},{"t":"题陕西图三首 其二","f":"五言律诗","c":["万里灵州地，他年汉朔方。","山河从割弃，关辅急堤防。","转益豺狼窟，堪嗟礼义乡。","拔胡须壮士，看画意苍茫。"]},{"t":"题陕西图三首 其三","f":"五言律诗","c":["河源来积石，天马涉流沙。","耳目成千古，丹青在一涯。","荒凉都护府，断绝使臣槎。","安得山河将，收功似汉家。"]},{"t":"五月","f":"五言律诗","c":["五月黄梅熟，江边昼雨初。","锈痕侵匣剑，润气蠹囊书。","乱恐翻银汉，喧愁泄尾闾。","时时双水鸟，往往上吾庐。"]},{"t":"江上雨中","f":"五言律诗","c":["江云似无信，山雨易翻盆。","鹏起天形黑，龙骧水面浑。","大舟才弱缆，孤树小前村。","濯热吾知慰，风波勿重论。"]},{"t":"和王待制湘东王故苑","f":"五言律诗","c":["故园悲帝子，高兴复清秋。","密竹娟娟静，通波细细流。","干戈馀鲁殿，池沼似沧洲。","鱼鸟应无恨，山公肯醉游。"]},{"t":"冬暖","f":"五言律诗","c":["南瘴无消息，玄冥为失威。","水深鸿雁宿，霜薄鹧鸪飞。","处处怜乔木，人人惯袷衣。","生涯卑湿地，日饮自知机。"]},{"t":"忝官","f":"五言律诗","c":["忝官东北藩，老拙复何言。","曹事辄付外，客车稀到门。","临池看鱼乐，倚杖听禽喧。","莫恨三年最，从今长子孙。"]},{"t":"雨中","f":"五言律诗","c":["沈阴连日雨，六月似高秋。","凉冷宵眠稳，泥涂昼事休。","尘昏旧铜镜，朽蠹敝貂裘。","赖有盈樽酒，能为懒病谋。"]},{"t":"雨后","f":"五言律诗","c":["积雨黄梅后，多风夕景天。","少阴回玉烛，秋气变薰弦。","孤鸟爰居外，残云螮蝀边。","羽陵书蠹尽，数怪绝韦编。"]},{"t":"欲雨","f":"五言律诗","c":["久晴惊础润，信宿候风回。","仰月光如瓦，烧云色变灰。","欢蛙疑自得，青鹢竞飞来。","正想江南地，清凉接过梅。"]},{"t":"北窗闻雨","f":"五言律诗","c":["庭梧不隐响，秋入意萧条。","过雨喧天籁，高风会海潮。","寒侵知洒近，气豁想云遥。","岁晚看摇落，无衣耻敝貂。"]},{"t":"雨","f":"五言律诗","c":["繁阴昼漠漠，日雨暝纷纷。","斗蚁仍移市，乖龙亦过云。","泥涂休不出，钟鼓遣相闻。","愿得辞昏垫，长风破宿氛。"]},{"t":"酴醾轩雨中二首 其一","f":"五言律诗","c":["小雨疏阴响，高风绿幕斜。","冷吹能却暑，细滴不妨花。","轻湿苔痕滑，连阴草色加。","路长车马少，暂喜息飞沙。"]},{"t":"酴醾轩雨中二首 其二","f":"五言律诗","c":["病身常自力，杖屦及比邻。","继日伤霖雨，深居若避人。","阴苔无数绿，秋草一番新。","入夜添凉冷，书灯顿可亲。"]},{"t":"巢湖阻风二首 其一","f":"五言律诗","c":["重云迷日月，异县失西东。","苦畏连天水，何须竟夕风。","微明分白鸟，摇落望青枫。","久客嗟留滞，吾生事事同。"]},{"t":"巢湖阻风二首 其二","f":"五言律诗","c":["四月风犹北，湖边气似秋。","天时如反置，吾道信淹留。","望远还吹帽，憎寒更拥裘。","无由开白日，晦暝使人愁。"]},{"t":"安河阻风","f":"五言律诗","c":["随湖寄渔浦，村戍起孤烟。","水色连天黑，沙禽亦昼眠。","柘田春种麦，客渡晚争船。","尽日无他事，寻村听野泉。"]},{"t":"凝翠堂","f":"五言律诗","c":["耸耸排修竹，萧萧拂蠹檐。","秋声送凉雨，晚影碎寒蟾。","居处贫非病，生涯智养恬。","著书聊自守，非欲效幽潜。"]},{"t":"留张十二宿","f":"五言律诗","c":["静外尘土息，故人从我游。","襟怀已潇洒，杯酒聊劝酬。","大笑呼五白，浩歌遣四愁。","劳生如此少，叹息为君留。"]},{"t":"王太傅河北阅马","f":"五言律诗","c":["丰草河壖地，平沙冀北区。","离宫连苜蓿，旧苑半騊駼。","夫子深诗者，无邪颁使乎。","宁令汉马少，不议击匈奴。"]},{"t":"庶几堂","f":"五言律诗","c":["碧草衡门里，凉天过雨初。","惊秋数甲子，隐几读残书。","近郭多鸣鹤，坳堂可钓鱼。","异方无到客，非是故人疏。"]},{"t":"岁除立春乾祐县献梅","f":"五言律诗","c":["除日应无岁，新春不待年。","风光生意里，梅信客情边。","冷艳来冰谷，疏风映雪天。","不逢江上使，相与竞芳妍。"]},{"t":"挽胡太傅二首 其一","f":"五言律诗","c":["州来推博物，伯始贵中庸。","论道宜黄发，铭功遍景钟。","龙门馀旧客，马鬣怅新封。","后世瞻遗德，南山万丈峰。"]},{"t":"挽胡太傅二首 其二","f":"五言律诗","c":["路车申伯去，白马庾公归。","殄瘁人相吊，哀歌露易晞。","石麟森立木，蜜印锁泉扉。","絮酒惭徐孺，回看旅雁飞。"]},{"t":"挽西京左藏使石太保二首 其一","f":"五言律诗","c":["勇掷诸生笔，终乘使者车。","家声唯孝谨，将略亦诗书。","鹤发遗荣始，泷冈卜兆初。","谬承公叔荐，曾未撇衣裾。"]},{"t":"挽西京左藏使石太保二首 其二","f":"五言律诗","c":["青绶股肱守，毳衣方伯监。","威名真落落，硕望自岩岩。","道远年如待，才长志尚缄。","家多二千石，会见集门凡。"]},{"t":"挽宋司空丞相二首 其一","f":"五言律诗","c":["斗枢齐七政，鼎铉象三公。","文武兼人际，安危注意同。","规随馀故事，止足畅高风。","他日云台画，依然想窦融。"]},{"t":"挽宋司空丞相二首 其二","f":"五言律诗","c":["蜜印加泉室，哀箫去国门。","降龙严冕服，画鹿并车轓。","山甫中兴业，臧孙既殁言。","定应天壤内，长与日星存。"]},{"t":"月夜吹箫","f":"五言律诗","c":["长路见秋月，空江连夜明。","吹箫不能寐，举酒递相倾。","贾客或垂泪，羁人多失声。","湘弦苦沉绝，曲尽一含情。"]},{"t":"秦国公主挽诗","f":"五言律诗","c":["渭阳追舅氏，婺女嫁天孙。","平日诸姑问，当时赤绶尊。","烟波空北渚，荻竹自长门。","后夜秦楼月，哀箫閟九原。"]},{"t":"宿岘山寺二首 其一","f":"五言律诗","c":["眷予倦羁旅，坎壈林壑间。","落日投古寺，秋虫吟乱山。","月明露已白，风定云方还。","王事殊未暇，怅兹清夜閒。"]},{"t":"宿岘山寺二首 其二","f":"五言律诗","c":["苍山若无路，落日听鸣钟。","旁舍适眠虎，古潭微见龙。","空窗向云月，高枕听风松。","幽境昔未遘，仙游如可逢。"]},{"t":"观虎翼士戍宜州","f":"五言律诗","c":["虎贲王爪士，铜柱国南门。","魑魅非人境，蛮夷尽鸟言。","瘴烟旗纛黑，雾雨剑铓昏。","即路皆无色，何时见北辕。"]},{"t":"再见士卒戍桂阳","f":"五言律诗","c":["驿书频插羽，汉士远征蛮。","四月天将暑，三苗旧阻艰。","悲笳背城邑，苦雾湿关山。","后夜东南望，妖氛翼轸间。"]},{"t":"悼杨公缊二首 其一","f":"五言律诗","c":["得君虽恨晚，白发幸前期。","分手遂陈迹，晤言成独悲。","隙驹得未久，风烛不胜危。","讵有修文选，高天可易知。"]},{"t":"悼杨公缊二首 其二","f":"五言律诗","c":["寄书曾未报，题墨宛如新。","长路归丹旐，孤儿泣画輴。","江湖馀气槩，星月聚精神。","冥漠九原上，空将万鬼邻。"]},{"t":"秋怀二首 其一","f":"五言律诗","c":["摇落看秋色，淹留倦郢城。","登临想自昔，风土最含情。","白露黄橙熟，清风绿桂生。","异乡随众醉，须尔析朝酲。"]},{"t":"秋怀二首 其二","f":"五言律诗","c":["蒹葭晚已变，天宇向来高。","风露一潇洒，江湖久郁陶。","鲈鱼越人脍，白露广陵涛。","归兴凭三鸟，悲秋叹二毛。"]},{"t":"夕雾","f":"五言律诗","c":["日落山气改，汀洲寒雾生。","深沈转墟落，迢递失重城。","树里迷人语，沙头见火明。","商帆宿何处，彷佛棹歌声。"]},{"t":"签判承议携官酒并具殽炙晚饮桧下二首 其一","f":"五言律诗","c":["烦携光禄酒，愧举使君觞。","伏尽转秋热，月明才夜凉。","暗蛩声蕊蕊，古桧影苍苍。","衰老淡薄味，殽蔬犹遍尝。"]},{"t":"签判承议携官酒并具殽炙晚饮桧下二首 其二","f":"五言律诗","c":["风月近秋好，君来蒙十觞。","尘劳我休息，炎暑此清凉。","玉露衣襟爽，金波鬓发苍。","知心一为足，何必似原尝。"]},{"t":"送仪父清溪县丞","f":"五言律诗","c":["虽方六七十，皆有万千家。","赞府亦制锦，到官殊及瓜。","山苗甘笋蕨，溪饭饱鱼虾。","为尔传清白，遗黎每叹嗟。"]},{"t":"次韵和周承议登仙源宫楼","f":"五言律诗","c":["屏星驻真境，乔木尽萧森。","野旷日偏永，山寒云更深。","九皇容尽信，万事盛来今。","回首灵光殿，飞鸦起暮林。"]},{"t":"送从兄思甫尉富阳","f":"五言律诗","c":["南州吏数千，尉事独神仙。","平日稀桴鼓，端居数醉眠。","潮声雷出海，山色剑横天。","会尽登临兴，淹留肯计年。"]},{"t":"送刘谊先辈尉泾县","f":"五言律诗","c":["诏除芸阁吏，名属太常书。","高第余无愧，同宗谁不如。","乡情欢赐服，寿酒庆安舆。","正复秋风起，沧江厌脍鱼。"]},{"t":"送张益宣州法曹","f":"五言律诗","c":["谢守宣城句，偏矜吕法曹。","郡斋应似旧，廷掾不徒劳。","东北归流驶，空虚去棹高。","木瓜因赠客，并择兔千毫。"]},{"t":"韩康公挽词三首 其一","f":"五言律诗","c":["初还丞相印，并授上公封。","门戟交行马，衣章杂绣龙。","策书休命毕，拜老未临雍。","遗爱无时息，凄凉在辍舂。"]},{"t":"韩康公挽词三首 其二","f":"五言律诗","c":["八龙归济美，四辅号无官。","鲁卫联三寿，韦平属二难。","大勋流竹帛，盛事绝衣冠。","今日哀荣礼，贤豪共永叹。"]},{"t":"韩康公挽词三首 其三","f":"五言律诗","c":["乘舆锡临吊，朝士盛班辞。","笳鼓千人仗，辒辌数仞旗。","坏梁萧画在，藏壑说舟移。","无复龙渊剑，空传禹甸诗。"]},{"t":"伤王都官正卿","f":"五言律诗","c":["巍然积德门，识此贵公孙。","譬彼芝兰秀，行看鸿鹄轩。","谁令武子死，无复孟尝言。","寂寞穗帷暝，流尘空酒樽。"]},{"t":"伤胥平叔都官","f":"五言律诗","c":["欲为大招赋，期子入修门。","昔尔南宗学，惭予庄叟言。","清樽湛凝绿，丹旐杳飞翻。","晨夕高堂念，此情难重论。"]},{"t":"伤杨元明都官","f":"五言律诗","c":["传家推德祖，似舅识刘牢。","刻意鸿都学，精心常侍曹。","万金酬六体，一字秃千豪。","讵有修文事，苍苍空自高。"]},{"t":"归雁","f":"五言律诗","c":["楚水几时绿，归鸿前后闻。","江湖久漂泊，南北忍辛勤。","意气融融日，声音漠漠云。","青冥易凌厉，况复未离群。"]},{"t":"雪中闻雁","f":"五言律诗","c":["四海困横绝，经年长往来。","雪霜空尽力，道路有馀哀。","水宿稻梁薄，云深罗网猜。","北方有杀气，缓缓及春回。"]},{"t":"新雁","f":"五言律诗","c":["南飞洞庭雁，稍复过衡阳。","宇宙同为客，春秋各异方。","边尘犹处处，杀气苦苍苍。","恐有伤弓翮，哀鸣少稻粱。"]},{"t":"观南戍士","f":"五言律诗","c":["膂力三军士，由来百战经。","舞旗翻鸟隼，叠鼓会风霆。","杀气过铜柱，欢声塞洞庭。","九州防盗贼，儒服愧青萍。"]},{"t":"平山堂","f":"五言律诗","c":["吴山不过楚，江水限中间。","此地一回首，众峰如可攀。","俯看孤鸟没，平视白云还。","行子厌长路，秋风聊解颜。"]},{"t":"伯父挽诗二首 其一","f":"五言律诗","c":["遂有终焉志，才成智者居。","户庭连水竹，几杖接舟舆。","爱客樽中酒，传家箧里书。","疏公知足计，不益旧田庐。"]},{"t":"伯父挽诗二首 其二","f":"五言律诗","c":["民思常在去，令德久犹存。","恸哭新阡树，迟疑旧里门。","大招声断绝，丹旐影翩翻。","后日谈随会，人知叹九原。"]},{"t":"挽刁景纯二首 其一","f":"五言律诗","c":["承明通佚老，仁智远归居。","门下无留客，灯前不废书。","舞筵交履舄，倚杖及田庐。","以此为家事，忘年八十馀。"]},{"t":"挽刁景纯二首 其二","f":"五言律诗","c":["延陵君子墓，南极老人星。","自古称遗爱，斯文重典刑。","一生隆许与，五福最康宁。","逝矣俱陈迹，临风祇涕零。"]},{"t":"挽孔经父二首 其一","f":"五言律诗","c":["乡里东南秀，衣冠伯仲贤。","先鸣俱中隽，竞爽故无前。","朔雪凋华萼，炎风急逝川。","斗间占紫气，应复在龙渊。"]},{"t":"挽孔经父二首 其二","f":"五言律诗","c":["往昔方闻策，中间五谏书。","直绳无废墨，利刃必投虚。","任重生何薄，年长恨有馀。","悲君虽视草，不及马相如。"]},{"t":"挽丁元珍","f":"五言律诗","c":["颜驷縻三省，君山困六安。","宦游俱邂逅，行路正艰难。","去水争还壑，凝霜苦败兰。","唯馀青简在，时为拂尘看。"]},{"t":"挽苏明允二首 其一","f":"五言律诗","c":["季子才无敌，桓公义有馀。","空悲武儋石，犹得茂陵书。","郢路营魂远，江源气象虚。","康成宜有后，正使大门闾。"]},{"t":"挽苏明允二首 其二","f":"五言律诗","c":["汉仪绵蕝盛，周谥竹书存。","益以春秋法，因知皇帝尊。","百年当绝笔，诸子谢微言。","诗礼终谁及，贤良萃一门。"]},{"t":"闻雷","f":"五言律诗","c":["过腊山微雨，开正两震雷。","渐南风土异，伤早岁时催。","放逐渔翁问，淹留漂母哀。","馀寒附烟火，尚有复燃灰。"]},{"t":"和孙宣德中秋不见月","f":"五言律诗","c":["便有倚天剑，决云殊细微。","清光自无蔽，绝境转知稀。","露重蝉时落，风高雁已飞。","嫦娥苦幽独，会载客槎归。"]},{"t":"和中秋对月","f":"五言律诗","c":["星稀如有避，云卷不辞劳。","露已深秋白，天应为月高。","幽怀向谁尽，诗兴更何逃。","勿负盈樽酒，须营千兔毫。"]},{"t":"十月四日离都归陈州","f":"五言律诗","c":["南浦三篙水，归人五日粮。","寒沙晨起雁，古树夜经霜。","久客复去国，有情知望乡。","鬓毛浑欲变，鸣笛不须长。"]},{"t":"去陈二首 其一","f":"五言律诗","c":["近关蘧舍卫，接淅孔违齐。","今日思狂简，儒生自滑稽。","归欤那愠见，去矣约轻赍。","颍水清如镜，风波定弗迷。"]},{"t":"去陈二首 其二","f":"五言律诗","c":["礼贤齐相国，爱客郑尚书。","徐孺曾悬榻，冯公预食鱼。","甘棠勿剪伐，客馆遂邱墟。","长铗还相语，冥鸿幸起予。"]},{"t":"端午","f":"五言律诗","c":["万里荆州俗，今晨采药翁。","浴兰从忌洁，服艾已同风。","泛酒菖蒲细，含沙蝘蜓红。","沉湘犹可问，角饭畏蛟龙。"]},{"t":"嘉祐大行皇帝挽诗十首 其一","f":"五言律诗","c":["七月期先远，三泉异卜征。","悲忧同轨事，遏密兆人情。","晚出苍龙驾，真游白玉京。","称天腾茂实，厚德始能名。"]},{"t":"嘉祐大行皇帝挽诗十首 其二","f":"五言律诗","c":["北发声名远，西城剑戟销。","万灵潜受记，百兽乐闻韶。","昧谷迷升日，璇霄失建杓。","仙游那可问，赋讽已飘飘。"]},{"t":"嘉祐大行皇帝挽诗十首 其三","f":"五言律诗","c":["盛德终无逸，元功熟间然。","启疆神禹绩，著记帝虞年。","桑变旋观海，弓遗杳望天。","霸陵无石椁，不改故山川。"]},{"t":"嘉祐大行皇帝挽诗十首 其四","f":"五言律诗","c":["尽礼三神事，斋居五日朝。","绨衣仍浣濯，禁籞亦刍荛。","汾水游何往，华胥梦转遥。","羹藜与环堵，无日不思尧。"]},{"t":"嘉祐大行皇帝挽诗十首 其五","f":"五言律诗","c":["属车全卤簿，宝玉焕渠眉。","万国瞻龙翣，三辰会素旗。","雪迷帝乡望，风动海隅悲。","今日西巡守，仍非八月期。"]},{"t":"嘉祐大行皇帝挽诗十首 其六","f":"五言律诗","c":["清光非可望，天道亦难闻。","策府开群玉，赓歌续庆云。","一经皆赐复，九译尚同文。","会尽南山竹，成书纪帝坟。"]},{"t":"嘉祐大行皇帝挽诗十首 其七","f":"五言律诗","c":["陵阙俨因山，明中恍下天。","燃鱼常照夜，耕象自成田。","鸿洞深投玉，莓苔密瘗钱。","涕流昭德舞，无复柏梁篇。"]},{"t":"嘉祐大行皇帝挽诗十首 其八","f":"五言律诗","c":["帝车旋北斗，驰道绕青松。","银海浮双阙，虞渊顿六龙。","深思倾杞国，遗恨泣华封。","述作无忧事，灵台与辟雍。"]},{"t":"嘉祐大行皇帝挽诗十首 其九","f":"五言律诗","c":["车书共文轨，律度出声身。","明白垂中典，优容礼直臣。","熊罴渭川叟，风雨越裳人。","更想攀髯士，犹知不犯鳞。"]},{"t":"嘉祐大行皇帝挽诗十首 其十","f":"五言律诗","c":["哀挽千人唱，崇冈万岁居。","呼关想传警，羡道法周庐。","晚日涂车静，深山灌柏初。","谷神知有术，犹欲信前书。"]},{"t":"次韵和麻直讲题杨直讲所种三樗树","f":"五言律诗","c":["谁能知散木，封植亦无心。","岁月如视荫，栖迟还息阴。","宦情移柳在，诗兴爱棠深。","定有归飞翼，怀音似泮林。"]},{"t":"神宗皇帝挽诗四首 其一","f":"五言律诗","c":["制作夸三正，规模壮百王。","自然推大略，谁得望清光。","东乐来蟠木，南琛过越裳。","白云那可测，应复向汾阳。"]},{"t":"神宗皇帝挽诗四首 其二","f":"五言律诗","c":["绵宇正欢心，虞韶骤遏音。","戴天忧杞国，就日怅崦岑。","贯朽三泉府，方输九牧金。","斯民已仁寿，至理更难忱。"]},{"t":"神宗皇帝挽诗四首 其三","f":"五言律诗","c":["四塞联初郡，千官仅代工。","舟车逾汉迹，台省变唐风。","贤杰程能际，戎夷率服中。","轩威百年在，何必画周公。"]},{"t":"神宗皇帝挽诗四首 其四","f":"五言律诗","c":["晚驾严仙御，西巡即旧都。","天寒馀鹤语，弓堕脱龙须。","白发孤臣泪，清湘万里途。","无由宣室问，回首叫苍梧。"]},{"t":"大行挽诗二首 其一","f":"五言律诗","c":["受名从大行，复土自因山。","秋草龙髯堕，宫烟泪竹斑。","不知汲水远，犹与化人还。","寂寞崦嵫日，空瞻咫尺颜。"]},{"t":"大行挽诗二首 其二","f":"五言律诗","c":["讴歌前授启，桑谷遂兴商。","恭己朝无事，优贤礼亦庄。","那惊同轨至，方奏万年觞。","西望归云白，悠悠指帝乡。"]},{"t":"又二首 其一","f":"五言律诗","c":["万国依无外，三登颂太平。","樵夫亦谈道，耆旧莫知兵。","云去仙乡远，龙来宝鼎成。","西风动阊阖，哀涕不胜情。"]},{"t":"又二首 其二","f":"五言律诗","c":["供张连三辅，梯航会九围。","属车疑晚驾，清跸望来归。","草露凄金阙，松风飏玉衣。","旧传当脱躧，遥见五云飞。"]},{"t":"日晚","f":"五言律诗","c":["清秋来早晚，落日正萧然。","稍见林外水，独听风际蝉。","牛羊暝知道，墟落远生烟。","岁事看禾黍，方知沮溺贤。"]},{"t":"挽杜祁公太师二首 其一","f":"五言律诗","c":["孤童迨耆老，仕郡至三公。","任重仍长道，材全信永终。","时推子房智，人识伯夷风。","存殁哀荣礼，千秋谁与同。"]},{"t":"挽杜祁公太师二首 其二","f":"五言律诗","c":["赤舄三师贵，诸公百里封。","旧勋兼注意，馀事寄明农。","哀动襄阳市，悲残郑国舂。","空馀灵寿赐，无复见临雍。"]},{"t":"秋雨四首 其一","f":"五言律诗","c":["冷雨黄昏暮，秋声众叶喧。","濯烦天宇阔，流恶楚江浑。","蛙黾烦当道，鱼龙稍在门。","一樽聊自劝，还欲笑臧孙。"]},{"t":"秋雨四首 其二","f":"五言律诗","c":["漠漠清秋雨，萧萧万宇寒。","蛟龙移窟宅，江汉急波澜。","瘴雾深蛮洞，旌旗湿汉官。","南征愁失道，后土若为乾。"]},{"t":"秋雨四首 其三","f":"五言律诗","c":["海风吹暮雨，淮上始秋声。","点滴潜滋润，阴沈未放晴。","林塘云似密，水鉴镜来清。","无事看鱼鸟，飞沈体亦轻。"]},{"t":"秋雨四首 其四","f":"五言律诗","c":["炎天常畏酒，秋兴忆开觞。","海面孤云黑，林端一叶黄。","岛夷歌似楚，村笛语如羌。","更觉非吾土，登临思旧乡。"]},{"t":"有怀北归","f":"五言律诗","c":["江汉不宜秋，羁人北望愁。","帝乡从此去，楚水正东流。","竟日悲鶗鴂，长歌倚蒯缑。","天边两黄鹄，那肯为人留。"]},{"t":"秘阁梅花","f":"五言律诗","c":["始知丹禁密，独见早梅新。","天上应常雪，人间未有春。","乱香交砌草，疏影媚庭筠。","浪作瀛洲客，催成白发人。"]},{"t":"雨中晚凉","f":"五言律诗","c":["落日浮云暝，沧江雨气来。","风灯殊未定，洞户故频开。","秋意梧桐急，宵征蟋蟀哀。","客心聊洒濯，天地久尘埃。"]},{"t":"始凉","f":"五言律诗","c":["秋风来几时，客病不相宜。","摇落令心苦，虚凉益气衰。","生涯贫更拙，交态卧尤知。","安得千金赠，鸱夷与尔期。"]},{"t":"送张直温主簿赴南阳","f":"五言律诗","c":["张君年少予，冠岁聚公车。","留落成强仕，声名就子虚。","穰橙千户富，潭菊万家居。","吏隐何为乐，优游不废书。"]},{"t":"黄知录园池","f":"五言律诗","c":["劫火无遗者，灵光独岿然。","寒池清照日，古木碧参天。","细雨来幽鹭，凉风急乱蝉。","颇知鱼乐意，仍得离钩筌。"]},{"t":"游李氏园池二首 其一","f":"五言律诗","c":["从人问乔木，系马得名园。","柳带晴先绿，禽声暖更喧。","临池照清水，拂石置芳樽。","不畏归侵夜，严城未掩门。"]},{"t":"游李氏园池二首 其二","f":"五言律诗","c":["树密浑成坞，花深更有蹊。","来游春尚浅，重到客应迷。","已近无人境，深怜快马蹄。","风光不负约，樽酒会长携。"]},{"t":"春阴","f":"五言律诗","c":["峡云春易雨，水国暮多风。","原草萋萋绿，林花淡淡红。","清江晚寒外，落景半晴空。","物色怜新燕，归怀目去鸿。"]},{"t":"秋雨","f":"五言律诗","c":["南国秋常暑，凉风起自今。","泄云无白日，度夕亦层阴。","摇落梧楸意，萧条蟋蟀音。","穷愁抵衰病，坐作老翁心。"]},{"t":"树阴二首 其一","f":"五言律诗","c":["清阴方丈得，暑气乍来无。","尘榻从箕踞，前贤亦锻炉。","晚虫多黑羽，秋草半青珠。","安得遗方客，玄谈似给孤。"]},{"t":"树阴二首 其二","f":"五言律诗","c":["避世长梧子，居贫五柳生。","清秋葛衣薄，晚日浊醪倾。","雨蝶轻犹舞，风蝉凉不鸣。","淮南摇落早，倚树不无情。"]},{"t":"夜坐","f":"五言律诗","c":["积雨凝凉气，疏林滴露华。","流星占使者，斜汉挹浮槎。","喜近天流火，回看斗转车。","秋风下阊阖，消散万人家。"]},{"t":"饮酒城南门赠高子中","f":"五言律诗","c":["苍山际碧霄，绿树及山腰。","青霭照残日，白云萦丽谯。","偶然成胜赏，长啸隔尘嚣。","少驻飞凫舄，吾无独酌谣。"]},{"t":"酬晁单州二首 其一","f":"五言律诗","c":["九载一相逢，侵寻头已童。","喜君真傲吏，老我未成翁。","简易文书省，悲欢酒盏空。","平生怀旧意，尽见醉醒中。"]},{"t":"酬晁单州二首 其二","f":"五言律诗","c":["弹琴君子邑，贤守智逾多。","不作长沙赋，仍传白雪歌。","解酲应用酒，成佛却须魔。","正买千金骨，何忧骥跋跎。"]},{"t":"送吕国博知常州","f":"五言律诗","c":["计然馀半策，贾子就新书。","屈意银青绶，之官鸟隼旟。","丹枫千里远，秋兴二毛初。","最可羞晨膳，莼丝杂脍鱼。"]},{"t":"李公择自滑州移知鄂州","f":"五言律诗","c":["黄河鲂与鲤，不及武昌鱼。","好去连城守，翩然双隼旟。","谏官仍重外，天禄不成书。","可待三年最，归来侍赤除。"]},{"t":"朝回","f":"五言律诗","c":["朝回还闭户，讲彻复观书。","重禄争消得，微躯且自如。","俗情矜不及，生理付无馀。","寂嘿怀张挚，淹留苦魏渠。"]},{"t":"同宋次道饮王史馆园","f":"五言律诗","c":["珍馆扫尘埃，宾阶馀绿苔。","凉风知广厦，清唱急行杯。","修竹端藏日，交流静殷雷。","欢穷有馀恨，不及壮年来。"]},{"t":"同韩持国饮城东俞氏园","f":"五言律诗","c":["贫家常汲汲，一饮自难营。","不笑烹鸡黍，因之同耦耕。","林花含秀色，谷鸟变新声。","归马无庸疾，郊扉最近城。"]},{"t":"泛舟城南二首 其一","f":"五言律诗","c":["清溪亦多曲，窄地颇宜花。","出水游鱼乐，惊人白鹭斜。","孤城旧郢树，三户楚人家。","归兴仍风雨，萧然眷物华。"]},{"t":"泛舟城南二首 其二","f":"五言律诗","c":["风逆湍声急，云酣雨气豪。","川蜺垂饮近，江鹤去飞高。","洗藕还馀味，操舟未觉劳。","蒹葭弥极望，秋意晚骚骚。"]},{"t":"早行","f":"五言律诗","c":["山鸟相呼曙，樯乌自指南。","健看帆席满，坐数舳舻衔。","水阔蛟龙舞，鱼肥鹳鹤贪。","阵云浓似墨，送雨向湘潭。"]},{"t":"晚行","f":"五言律诗","c":["天阔西曛久，风多客语闻。","九江秋落水，三峡暮归云。","饮啄鸥相并，归飞鹤不群。","湘潭早摇落，稍稍怅平分。"]},{"t":"次韵酬钱少卿","f":"五言律诗","c":["簿书非力学，何事不窥园。","乘兴缘心赏，忘怀到酒樽。","露蝉凉寂寞，风叶静翩翻。","少驻东方骑，前盟岂可温。"]},{"t":"送楚南","f":"五言律诗","c":["心寄江湖上，乐闻游子归。","送君从此去，脱叶正秋飞。","云水聊破浪，风尘今振衣。","山僧不善饮，定负蟹螯肥。"]},{"t":"送袁生","f":"五言律诗","c":["巴蜀穷天险，惊君便向西。","长年劳贾勇，悬度约轻赍。","行止千金子，艰危万丈梯。","自怜倾盖旧，即事复睽携。"]},{"t":"送刘四畋二首 其一","f":"五言律诗","c":["四海皆兄弟，吾宗加老成。","好书如子政，饮酒胜公荣。","今日鲈鱼脍，羡君乘兴行。","秋风峡中度，快意听潮声。"]}]};